window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_005"]={"n":"王夫之","dyn":"清","poems":[{"t":"和陶停云赠芋岩五十初度四首 其一","f":"古风","c":["蒸蒸良稼，涤涤灵雨。","滋湑以荣，炎威莫阻。","君子不遐，如琴在抚。","无念古人，空尔延伫。"]},{"t":"和陶停云赠芋岩五十初度四首 其二","f":"古风","c":["道延今者，爰如鸿濛。","靡明靡日，靡流靡江。","如彼暗室，召晖于窗。","匪君子任，其孰能从。"]},{"t":"和陶停云赠芋岩五十初度四首 其三","f":"古风","c":["有梅有梅，霜裛其荣。","人恤尔寒，尔怡予情。","不愆日迈，不负月征。","维仁引年，以保尔生。"]},{"t":"和陶停云赠芋岩五十初度四首 其四","f":"古风","c":["乔乔豫章，执彼斧柯。","匪不日劳，许许维和。","天期不假，物望实多。","蘧生知化，日益云何。"]},{"t":"杂诗","f":"古风","c":["清夕始澄，孤月出林。","繁阴绎绎，今我乍歆。","昔者驱车，适彼四野。","求我友生，赠以瑶斝。","昔者乘舟，顺彼中流。","解我冲牙，以赠同仇。","迢迢南山，崔崔峻峦。","暮云群飞，谷风泻湍。","阳雁差池，矧彼鹰鹯。","余生不再，余命不双。","短襟自寒，朔风摇缸。","岁暮薇枯，饥谁与同。"]},{"t":"分界岭","f":"五言古诗","c":["行役杳穷极，愁心积纷诡。","薄暮晻霭宿，晨望霏微起。","蜃气迎山云，苍流奔海水。","桂开信天枢，南条迁物理。","挥手谢寒烟，回头讶枫紫。","溟游渐穷发，行歌聊匪兕。","勾漏引丹砂，云何驻芳纪。"]},{"t":"晨发端州与同乡人别","f":"五言古诗","c":["海甸见新草，故园入春心。","天涯共萋萋，谁能辨浅深。","寒潮落沙影，晓塔郁曾阴。","日南绝征雁，桂水孤归禽。","遥分前渚泪，共湿故人襟。"]},{"t":"苍梧舟中望系龙洲","f":"五言古诗","c":["暮云笼山碧，绿树沉流影。","中江瀑珠分，孤屿画檐整。","团圞紫茸合，森萧翠光冷。","秀挺既歆别，高涵亦危秉。","烟浦极远天，槲香吹隔岭。","凌晨溯两桨，即目饱幽境。","万古苍梧愁，因兹慰孤耿。"]},{"t":"初入府江","f":"五言古诗","c":["粤草易春深，驶流知潮远。","樵火垂野云，滩花媚绝巘。","林迂委岸阴，水绵俯萝偃。","江介爱栖回，芳菲惜迟晚。","昔来取慰庄，吾穷良悼阮。","生事有幽栖，天游恣冥返。"]},{"t":"佛山","f":"五言古诗","c":["昔闻沧波兴，挂席奖微向。","荔棹戒晨征，葑田果迎望。","山尽时远飘，川分故微漾。","星河摇碧缀，天气复青荡。","寄身良已孤，行吟空自壮。","万端散纷诡，吾道有兴丧。","无取笑支离，徒滋罥禽尚。","繁虑本物先，冥欢辍想像。","迟尔海鸿飞，明珠怀佳贶。"]},{"t":"杂诗四首 其一","f":"五言古诗","c":["结璘耀东方，摇辉散庭戺。","褰帷视玉衡，何为倏东指。","汎爱惜流光，合旨抚逝水。","鶗鴂天涯鸣，繁英怨游子。","东园积落芳，安问桃与李。","悲歌无与听，拊琴复中止。"]},{"t":"杂诗四首 其二","f":"五言古诗","c":["孤云起江汉，摇影自徘徊。","飘风不相待，吹落阳云台。","肤寸既违阴，炎威已复开。","清音閟广野，鸾歌谁为来。","欲因广成子，返此元息胎。","时哉不易遇，摧折使心哀。"]},{"t":"杂诗四首 其三","f":"五言古诗","c":["昔我游汉水，遥与神女期。","琅玕非所欢，玉佩空相贻。","愿托双凤鸟，当时听者谁。","不惜蘼芜死，将为蔓草欺。","沟水自东下，繁星已西驰。","幽谷返椒岑，琴心终自知。"]},{"t":"杂诗四首 其四","f":"五言古诗","c":["悲风动中夜，边马嘶且惊。","壮士匣中刀，犹作风雨鸣。","飞将不见期，萧条阻北征。","关河空杳霭，烟草转纵横。","披衣视良夜，河汉已西倾。","国忧今未释，何用慰平生。"]},{"t":"胡安人挽诗","f":"五言古诗","c":["幽兰自著花，菖蒲自成节。","激流难久生，溪风易吹折。","夙昔兰闺英，金韬送远道。","历历视明星，悠悠思春草。","春草生有时，黄尘飞不已。","白玉忍蒙沙，清流怨何驶。","上有龙标月，下有沅江水。","沅水自东流，梧云向南开。","蒲花生石上，芳节待归来。"]},{"t":"晨发昭平县飞雨过驴脊峡上泊甑滩会月上有作","f":"五言古诗","c":["孤游息魂营，凉泛叶形美。","清晨理桂楫，薄言遵远水。","遂欣斯望协，遗彼群象诡。","微雨前峰来，清光错表里。","胥飒歆飞雪，婉约弄明绮。","下倚惊濑鸣，俄开新翠起。","云倦偶失群，雷殷歘何止。","金光界波流，大火循西指。","飞鸟归有期，劳枻聊文舣。","历忆众峰外，延秀纷可纪。","人籁偶旁托，真赏归大始。"]},{"t":"游子怨哭刘母四首 其一","f":"五言律诗","c":["北风吹凝云，游子行不息。","易挽游子车，难驻桑榆色。","车轮遽己远，流光太相逼。","游子岂不知，遐心荡凭轼。"]},{"t":"游子怨哭刘母四首 其二","f":"五言律诗","c":["凭轼日以远，流光日以晚。","夜望曷旦鸣，夕待牛羊返。","寒风动明烛，疑见游子饭。","夜梦续晨愁，九秋成偃蹇。"]},{"t":"游子怨哭刘母四首 其三","f":"五言律诗","c":["偃蹇不相期，迟暮岂自持。","昔为倚闾叹，今为绝命思。","讵怨游子去，翻怜游子悲。","啾啾孤鸟鸣，飏飏垂风丝。"]},{"t":"游子怨哭刘母四首 其四","f":"五言律诗","c":["丝断不复理，鸟鸣哀难止。","三年九春绝，衰草凌霜靡。","行行向隧道，邑邑歌蒿里。","掩涕会有时，苍天终何已。"]},{"t":"小霁过枫木岭至白云庵雨作观刘子参新亭纹石留五宿刘云亭下石门石座似端州醉石遂有次作二首 其一","f":"五言古诗","c":["松级偶晨登，樾馆聊夕止。","轻裾挟馀滋，溪烟宛方起。","夫君碧云期，良会伫难委。","凌霄岂有扪，步秀方可纪。","流耳延雨声，惊华粲石理。","架阁馺微霄，初英散新紫。","云观权众木，神楼耸弱水。","仙游亦在区，魏榭空云绮。","淹宿有馀清，实归载留喜。"]},{"t":"小霁过枫木岭至白云庵雨作观刘子参新亭纹石留五宿刘云亭下石门石座似端州醉石遂有次作二首 其二","f":"五言古诗","c":["三岁度岭行，薄言观世枢。","壮心销流丸，林泉聊据梧。","归心存醉石，取似在枌榆。","江湖忧已亟，神尻梦可趋。","漆吏称昔至，周臣怀旧都。","流止互相笑，外身理不殊。","委形凭大化，中素故不渝。","兴感既有合，触遇孰为拘。","海尘无定变，聊崇芳兰躯。"]},{"t":"春日书情","f":"五言古诗","c":["春云覆千里，飞雨来微霄。","良阴不待旦，宿昔非崇朝。","蘅皋英犹缓，蕙圃芳未遥。","连卷仍故蘤，敷被丽新条。","佳人阻采若，含情虚握椒。","行迈匪康涂，中心写长谣。"]},{"t":"西庄源所居后岭前壑古木清沼凝阴返映念居此三载行将舍去因赋一诗","f":"五言古诗","c":["物遇日屡迁，流止暂不遗。","浮云出丹巘，游鯈遵绿漪。","心知既无滞，躯质匪有期。","俯仰同久乍，令我奄宅兹。","修竹丛尚稚，冈桐荫每移。","云岫半明灭，霞嶂时参差。","坐闻春鸟鸣，亦睹秋叶离。","凌景延圆晖，迎寒却凉飔。","回首舜帝峰，濯足舂水湄。","芳草良未歇，佳期行可规。","行道昔已靡，槁木今何居。","俄顷已藉用，乘乘将焉之。"]},{"t":"冬遇","f":"五言古诗","c":["太华蜕奇骨，黄河问灵躯。","风雨恣所狎，金石等不渝。","坚脆各叛纪，正襟守中枢。","觏闵婴陆沉，陨问戒斯须。","吾生匪蜃雉，物状漫紫朱。","聊息朱鸟麓，梦无金简书。","延彼堪舆情，充兹营魄虚。","晶宇涤宿云，回风荡椒隅。","薄岚开夕暾，寒英媚霜趺。","佳期无定轸，元化随与俱。","悦心道已广，栖贞邻岂孤。","三寿同修促，二见息肥癯。"]},{"t":"山居杂体卦名","f":"五言古诗","c":["豫子殉其道，井生贵所希。","坎流邈殊涂，既济愉同归。","比肩通异理，蒙袂轻调饥。","蹇余纫秋兰，升高搴野薇。","剥芧充晨餐，畜荷资霜衣。","离离劈椒房，鼎鼎闭松扉。","履石探晴云，临崖款夕晖。","益知荣公乐，渐看卜子肥。","颐生喻明窗，观物避炎威。","随兹寒暑谢，遁迹冀无违。"]},{"t":"来时路","f":"五言古诗","c":["来时苦大难，寒雨飞瀼瀼。","今者复何日，秋原称叶黄。","遵路行以悲，飘风吹我裳。","流目心自喻，剧结车轮肠。","人生苦经历，精爽定往还。","踟蹰行俟之，轻烟霭容颜。","飞鸟过我前，流泉鸣其閒。","欲语不得接，浮云云何攀。","迢迢荒原路，曲曲粤楚甸。","匪羊亦匪牛，穷日历郊箐。","蘖苦梅复酸，宛转遂所绻。","凛矣秋霜心，哀哉白日变。"]},{"t":"感遇十一首 其一","f":"五言古诗","c":["海国有嘉卉，绍古兰蕙名。","迢递致远道，绮靡发檐楹。","悦彼情所合，矜兹芳有成。","稷下宠琴客，梁园誇词英。","物玩已亦劳，枝叶非天荣。"]},{"t":"感遇十一首 其二","f":"五言古诗","c":["迢迢黄姑星，临河发光耀。","织女扬熹微，脉脉如相炤。","被以缠绵情，指彼佳期妙。","高居无通理，下士纷疑料。","鉴貌以测真，悱然贻姗笑。"]},{"t":"感遇十一首 其三","f":"五言古诗","c":["湛湛北辰表，沆瀣充寒门。","安知光影微，不有众星繁。","言穷至弥寡，心绝理已谖。","容成置象外，羲和辍纷论。","大地有疆畛，群生各本根。","甫田空忉怛，念兹息心魂。"]},{"t":"感遇十一首 其四","f":"五言古诗","c":["韶月知为春，百卉欣及时。","精英取不息，掠美悦其姿。","元化遗糟粕，忻合无迟疑。","芳华及零落，悲愉各在兹。","商山有高歌，煜煜三英芝。"]},{"t":"感遇十一首 其五","f":"五言律诗","c":["汉南婵媛子，临歧忧清露。","罗袜惜已微，中心良有故。","美人去我遥，思之若晨暮。","莞簟有馀清，肃肃警宵寤。"]},{"t":"感遇十一首 其六","f":"五言古诗","c":["飞萤弭清昼，熠熠流暗空。","炫影从彼异，匿光背所同。","胡不怀应求，殊德乐为攻。","忾然念吾生，晶宇共昭融。","捐情不矜己，云日相雍容。","嗟哉猖狂子，何为悲道穷。"]},{"t":"感遇十一首 其七","f":"五言古诗","c":["绾绾西塘柳，垂丝荡春色。","天情亦容曳，元化无悁亟。","骀宕不损贞，萧森非尚力。","昭质岂枯槁，乐天消偪侧。","迟迟舂日心，悠然庶相识。"]},{"t":"感遇十一首 其八","f":"五言古诗","c":["浮云起岱阴，萧屑积空微。","翕合非一气，灵雨千里飞。","如何彼姝子，孤爱俄顷辉。","光影或相报，寸心先已违。","歧路勿相问，行行各是非。"]},{"t":"感遇十一首 其九","f":"五言古诗","c":["涉雒想宓妃，游楚梦高唐。","宫中多婵媛，弃置如遗忘。","岂其浊河流，独有鲤与鲂。","芸堂是燕寝，兰阁有芳香。","归来欢日夕，至乐方未央。"]},{"t":"感遇十一首 其十","f":"五言古诗","c":["阪月漾初暄，桃李耻未开。","既欣新绪荣，亦畏霜雪摧。","迟疑志不决，东风徒增哀。","两者谁为佳，旁人难与裁。","静女远逢迎，置彼良愿乖。","巫咸已上天，鸩鸟非吾媒。","欢怨物自劳，于我何嫌猜。"]},{"t":"感遇十一首 其十一","f":"五言古诗","c":["清风起蘋末，吹荡兰与芷。","迨其明灭间，歘然迷端委。","相望不相见，幽动无能纪。","万岁亦匪他，今者为我始。","条绪皆芬芳，勿为叹逝水。"]},{"t":"夏日端居","f":"五言古诗","c":["岫云无本始，飘风善因依。","暑坐一以望，空明两不违。","白日舒中陆，绿草澹鲜辉。","游蝶池阴飞，双鸟云际归。","自治欣有合，炎情中已微。"]},{"t":"云山妙峰庵云是申泰芝炼丹处","f":"五言古诗","c":["松阴合绿雾，木末飞空光。","幽烛既云密，遥情歘已长。","首夏积翠鲜，亭午条风凉。","烟容澄岳壑，水气辨蒸湘。","圆宇目所镜，孤立心未央。","寓形俄邂逅，仙游昔回翔。","恻彼鸾鹤情，引兹邱海望。","羽蜕固有待，仁乐讵无方。","怀炎登天庭，悲忧陟首阳。","缮性良有藉，终生胡弭忘。"]},{"t":"秋阴","f":"五言古诗","c":["徂夏气未澄，涤暑期久误。","西爽歘浮云，落晖难再驻。","轻霄泊霏微，星影见回互。","疏雨润晨光，馀霭亘日暮。","冷吹不更惜，昭融逝何遽。","惊兹四序改，迁此百年遇。","天物无宿留，吾生阅已屡。","藏舟壑谁在，流丸迹匪故。","大力非我知，瓯臾亦何措。","但此欣萧清，迟回惬幽素。"]},{"t":"欧子直自南岳返讯之","f":"五言古诗","c":["灵壑有冬荣，幽人时晏出。","天物无孤清，闲情自相匹。","徘徊度飞鸟，乘凌俯落日。","虚旷断不穷，丹碧绚非一。","夕宿抱馀爽，各言纷欲悉。","岂无濠上情，言眺双径逸。","神晤遗形区，于焉记良昵。"]},{"t":"古意","f":"五言古诗","c":["堂堂背春日，悠悠送落英。","春日无返暄，落英无固情。","遥知当决绝，中心澹不惊。","济水穿河梁，河水无为清。","女萝萦枯枝，缠绵待新荣。","荣谢意亦尽，移言怨孀贞。"]},{"t":"问芋岩疾","f":"五言古诗","c":["二仲浴清肌，三五养妙婴。","相顾云已敛，待尔月将盈。","化碧既乖期，伫鹤方含情。","狞龙诚就辔，画虎何足烹。","袅烟自离合，泛舟无回萦。","念彼非心竞，释兹若羽轻。","黄芽抽别颖，金蕊有冬荣。","元笈君已授，勿为吝玉笙。"]},{"t":"浈峡谣五首 其一 弹子矶","f":"五言绝句","c":["弹子矶空峙，翻风燕不迷。","朝天台已筑，何处着丸泥。"]},{"t":"浈峡谣五首 其二 望夫江","f":"五言绝句","c":["烟水凝眸远，蘼芜且着花。","章台扳折后，依旧属韩家。"]},{"t":"浈峡谣五首 其三 观音岩","f":"五言绝句","c":["苍壁空青破，清江拂翠开。","越王虚胜槩，留待佛东来。"]},{"t":"浈峡谣五首 其四 飞来寺","f":"五言绝句","c":["辛苦浈江水，晨潮接暮潮。","飞来金碧影，劫火不曾烧。"]},{"t":"浈峡谣五首 其五 归猿洞","f":"五言绝句","c":["故山元有主，新宠讵难忘。","犹恐孙郎妒，相邀弄夕阳。"]},{"t":"秦王卷衣","f":"五言绝句","c":["渭南宫草绿，上殿带香归。","识得邯郸美，丛台旧舞衣。"]},{"t":"长干曲","f":"五言绝句","c":["秦淮通北固，流月带潮来。","郎今渡京口，日暮使人猜。"]},{"t":"白鼻騧","f":"五言绝句","c":["柳絮随檐帽，香尘污马鞯。","春光无赖甚，谁与醉芳年。"]},{"t":"江南曲","f":"五言绝句","c":["自有三台曲，齐抛八宝簪。","可怜秋色里，独唱望江南。"]},{"t":"为晋宁诸子说春秋口占自笑四首 其一","f":"五言绝句","c":["腹借征南库，灯邀汉寿光。","伤心难自遣，开卷是春王。"]},{"t":"为晋宁诸子说春秋口占自笑四首 其二","f":"古风","c":["蠹死墨魂失，?饥远视仍。","纸窗钻不透，大扺是痴蝇。"]},{"t":"为晋宁诸子说春秋口占自笑四首 其三","f":"五言绝句","c":["南岳经声苦，东林眉宇嚬。","似他添强笑，犹恐隔邻嗔。"]},{"t":"为晋宁诸子说春秋口占自笑四首 其四","f":"五言绝句","c":["荧泽宏演肝，伊川辛有泪。","未知家则堂，云何宣此义。"]},{"t":"春尽从子敞寄山居雪咏绝句歘尔隔岁聊复和之二首 其一","f":"五言绝句","c":["春去天涯雨，南留客影单。","梁园裁赋好，遥送杏花寒。"]},{"t":"春尽从子敞寄山居雪咏绝句歘尔隔岁聊复和之二首 其二","f":"五言绝句","c":["残雪留双鬓，馀寒抱死灰。","君还愁岁暮，不畏老夫猜。"]},{"t":"痛","f":"五言绝句","c":["阿旁□□□，严霜杀人鬓。","刺□日千□，十年皆□尽。"]},{"t":"哕","f":"五言绝句","c":["河间酒垆前，常愁欢见绝。","絮杀采桑人，同心若为结。"]},{"t":"颤","f":"五言绝句","c":["白刃甜如蜜，清流险似波。","羊牢须壁立，臧谷较无多。"]},{"t":"寒","f":"五言绝句","c":["借书败蕉叶，索字黄菅梗。","一倍粟生肌，霜衾未恁冷。"]},{"t":"热","f":"五言绝句","c":["真作寒灰好，禁他冷灶头。","烧灯围傀儡，鲍老汗珠流。"]},{"t":"痒","f":"五言绝句","c":["汗虱亦我液，疥虫亦我肌。","喉间冲败絮，鸟爪复奚为。"]},{"t":"哭","f":"五言绝句","c":["背我堂堂去，随他昔昔来。","无情犹有恨，独上望春台。"]},{"t":"笑","f":"五言绝句","c":["牛湩持作酥，渴分犊子饭。","客作不得尝，垂头打闷顿。"]},{"t":"山居杂体吃口诗","f":"五言绝句","c":["晴即前岫樵，峰分方未返。","路乱笼绿罗，云晕涌愈远。"]},{"t":"口字诗","f":"五言绝句","c":["岩路临磊砢，高棂营观皓。","蝉语敛嚣啁，鸥侣欢沤藻。"]},{"t":"为宋子主人送高渐离入秦","f":"五言绝句","c":["每见关中客，无心理筑哀。","徵书昨夜到，不待曙光催。"]},{"t":"绝句三首 其一","f":"五言绝句","c":["乍㬉回亭午，云生叶叶低。","轻云将雨足，侵入夕阳西。"]},{"t":"绝句三首 其二","f":"五言绝句","c":["弱柳垂新润，春风款款中。","濲波飘一晌，绿影过池东。"]},{"t":"绝句三首 其三","f":"五言绝句","c":["转转春条缓，鳞鳞野水肥。","疏云飘雨白，缭绕鹭丝飞。"]},{"t":"咏百合","f":"五言绝句","c":["莲瓣浓含粉，药房素养胎。","繇来千种束，不放寸心开。"]},{"t":"结袜子","f":"五言绝句","c":["初识张公子，投琼气已横。","匣中报恩剑，不为汝曹鸣。"]},{"t":"月斜","f":"五言律诗","c":["月斜空碧合，河汉几时生。","杳霭岳莲出，萧条露叶横。","归云飞带雨，凉雁过留声。","祇讶西峰上，清宵有奏笙。"]},{"t":"永兴廖邓二君邀宿石角山僧阁是侍先君及仲兄䃘斋游处","f":"五言律诗","c":["十月寒潭改，三年客艇过。","画櫩星影近，甃草夜霜多。","急难迷原隰，飘零废蓼莪。","郴江无限水，不与挽流波。"]},{"t":"清远城下忆湖湘旧泊","f":"五言律诗","c":["乍放浈江峡，疑连青草湖。","星河摇古岸，渔火历蒋菰。","霜后迷南雁，日斜忆庙乌。","佳人多楚塞，谁解赠明珠。"]},{"t":"春江古体","f":"五言律诗","c":["春鸟弄芳洲，初英照碧流。","晴云捲山入，晓露炫烟浮。","昨日宾鸿北，来时木叶秋。","湘江连桂岭，瑶草趁新愁。"]},{"t":"南中霜降","f":"五言律诗","c":["北候怀青女，南飙拂白蘋。","墟烟深漠漠，江草故鳞鳞。","翠袖寒犹薄，黄华泪已新。","炎洲无限橘，谁与寄湘津。"]},{"t":"不寐","f":"五言律诗","c":["夜火榜人惊，江沙依舸平。","落花逢昨日，潮月应初生。","芳草空凝望，绿云讵有情。","含凄愁梦杳，鱼柝警严城。"]},{"t":"刘端星学士昭州初度时初出诏狱","f":"五言律诗","c":["昭州迁谪地，清冽道乡泉。","过岭金风缓，当秋暑日悬。","重开初度酒，莫诵四愁篇。","萧艾吾何有，灵椿正大年。"]},{"t":"落日遣愁","f":"五言律诗","c":["落日群峰外，青空邀晚红。","晴山添雪色，远树缓霜鸿。","心放闲愁后，生凭大化中。","天年聊物理，楚国想遗风。"]},{"t":"癸已元日左素公邹大系期同刘子参过白云庵茶话二首 其一","f":"五言律诗","c":["晴鸟曙山天，林光捲宿烟。","壑阴藏雪润，麦露泫珠圆。","江树南开早，唐松东向偏。","殷勤悬有待，请组旧行边。"]},{"t":"癸已元日左素公邹大系期同刘子参过白云庵茶话二首 其二","f":"五言律诗","c":["昨夜梅边约，春情悄不禁。","刀环光阵阵，佛火照心心。","箕颍徐生拙，江湖魏子深。","南阳凭羽翼，恩泽放山林。"]},{"t":"春尽三首 其一","f":"五言律诗","c":["高树莺飞尽，流声能几闻。","微晴通雨色，深绿过花熏。","病浅心心在，欢遥曲曲分。","定知双鬓谢，无复惜殷勤。"]},{"t":"春尽三首 其二","f":"五言律诗","c":["杂甸与芳洲，当时不可留。","还持流景谢，长遣故心愁。","云际仍行药，东皋倦理畴。","滔滔属孟夏，骚怨寄灵修。"]},{"t":"春尽三首 其三","f":"五言律诗","c":["止竟春须去，灰心揽鬓丝。","薄晴长景困，馀冷晚风欺。","啼鴂犹争序，藏鸦已后期。","寄芳终契阔，阴绿听繁枝。"]},{"t":"哭李一超","f":"五言律诗","c":["鶗鴂春先逝，龙蛇斗未开。","容头馀子在，匕首酒人灾。","白发摇风木，丹心亘夜台。","报恩无意日，留取劫前灰。"]},{"t":"再哭季林兼追悼小勇匡社旧游","f":"五言律诗","c":["古寺青溪路，东窗隔一峰。","缘花忘柳径，驱酒试蘋风。","墨冷袜材客，巾残垫角雄。","馀生悲梦赋，不与勒新宫。"]},{"t":"晦日二首 其一","f":"五言律诗","c":["春色去堂堂，清和损岁芳。","夕烟青带远，晴树绿浮光。","秋稻江乡雨，琅玕竹径香。","定情裁古怨，迟晚意偏长。"]},{"t":"晦日二首 其二","f":"五言律诗","c":["白日奈朱颜，流光几暂闲。","九春馀此夕，落照已前山。","红豆留谁折，落花去不还。","逢迎他日恨，旧上鬓丝间。"]},{"t":"夏夜","f":"五言律诗","c":["裛露青林合，微凉生未央。","太清平野阔，薄雾远山长。","南树惊乌鹊，双星忆凤凰。","吹来何处笛，急调欲清商。"]},{"t":"重登双髻峰","f":"五言律诗","c":["拾级千寻上，登临一倍难。","日斜双树径，云满曼花坛。","龙雨腥还合，佛灯青欲残。","振衣情不惬，北望暮云寒。"]},{"t":"二贤祠重读义兴相公诗感赋","f":"五言律诗","c":["谢傅青山志，羊昙旧见招。","千秋馀版椠，孤榭托云霄。","弦望何时合，杜蘅今已凋。","清浔二千里，遗恨在军谣。"]},{"t":"花咏八首 其一 樱桃","f":"五言律诗","c":["艳深消雪冷，行密迓春酣。","弱蒂东风试，繁枝细雨堪。","大官谁复荐，啼鸟定先含。","献岁摇新恨，群芳且未谙。"]},{"t":"花咏八首 其二 迎春","f":"五言律诗","c":["玉峰疑菡萏，绛佩讵辛夷。","蝶醒初春里，香寻未绽时。","云生仙袂重，月上素痕滋。","愿结青萝好，亭亭寄远思。"]},{"t":"花咏八首 其三 山?","f":"五言律诗","c":["韶月飞金粟，春云降瑞霙。","暄风别有约，芳草共含情。","须浅容寻蝶，香过恰趁莺。","仙軿来早暮，即此玉为京。"]},{"t":"花咏八首 其四 紫荆","f":"五言律诗","c":["珍第偕金枕，同欢感异株。","虞渊衣未浣，汉玺泥应濡。","疏干捎莺羽，繁英碍蝶须。","桃蹊别弄色，泫露泣邢姝。"]},{"t":"花咏八首 其五 杜鹃","f":"五言律诗","c":["采缬轻红药，丹痕竞紫榴。","仙归十里幄，云指九重楼。","晴雾笼深晕，平塘炫碧流。","如何蜀鸟恨，夜月未消愁。"]},{"t":"花咏八首 其六 黄杜鹃","f":"五言律诗","c":["啼鸟愁如歇，闲情寄浅缃。","眉新欲试喜，额晓待添妆。","酒色醅莺羽，春情驻柳香。","愁心迷望帝，聊学赭袍黄。"]},{"t":"花咏八首 其七 金钗股","f":"五言律诗","c":["金虎胎含素，黄银瑞出云。","参差随意染，深浅一香薰。","雾鬓欹难整，烟鬟翠不分。","无惭高士韵，赖有暗香闻。"]},{"t":"花咏八首 其八 冈桐","f":"五言律诗","c":["樾馆辞寒候，江乡记稻春。","笑迎朝日上，繁映晚霞匀。","紫沁侵铅粉，青趺藉绿茵。","似怜芳草弱，飞覆玉鳞鳞。"]},{"t":"即事 其一","f":"五言律诗","c":["秋晚翠娟娟，寒条经雨边。","断云藏半树，归鸟没孤烟。","筱弱梢梢重，藤轻叶叶便。","上方夕磬早，亭午落清喧。"]},{"t":"山居杂体药名","f":"五言律诗","c":["白日及闲年，寻常山色妍。","古松香满径，修竹叶参天。","紫菀朝霞雨，黄连夕照烟。","柴桑寄生理，不受督邮怜。"]},{"t":"山居杂体县名","f":"五言律诗","c":["月上林间夜，烟含山际秋。","蛙吹传静乐，尻马足仙游。","抱瓮安园䔩，忘机定海鸥。","馀生随大冶，沤沫委东流。"]},{"t":"岳峰悼亡四首 其一","f":"五言律诗","c":["不愁云步滑，慊慊故慵来。","多病霜风路，馀生隔岁回。","凤绡残染泪，蛛网誓封苔。","旧是销魂地，重寻有劫灰。"]},{"t":"岳峰悼亡四首 其二","f":"楚辞体","c":["到来犹自喜，髣髴近檐除。","小圃忙挑菜，閒窗笑读书。","忽惊身尚在，莫是客凌虚。","楚些吾能唱，魂兮其媵余。"]},{"t":"岳峰悼亡四首 其三","f":"五言律诗","c":["关塞天涯黑，精魂一倍丹。","停云迷鸟宿，舞雪耐梅寒。","不遣琴心寂，相怜剑影残。","三年烹白石，馀沈咽龙湍。"]},{"t":"岳峰悼亡四首 其四","f":"五言律诗","c":["岳阡初甃罢，君此拜姑嫜。","地下容能聚，人间别已长。","蝶飞三月雨，枫落一林霜。","他日还凄绝，余魂半渺茫。"]},{"t":"迎秋八首 其一","f":"五言律诗","c":["昨夜月初明，青枫引露清。","稻香三日雨，虹影一溪晴。","落照低犹赤，蘋风晚更轻。","定情凡几日，银汉映阶平。"]},{"t":"迎秋八首 其二","f":"五言律诗","c":["斜日飐垂树，因风欲上黄。","侵苔依浅碧，漏月透微凉。","去鹭惊溪改，跳鱼拂荇香。","森森芦叶满，幸缓一头霜。"]},{"t":"迎秋八首 其三","f":"五言律诗","c":["长日倦何曾，棋枰早不胜。","杨枝愁少府，杜若老吴兴。","星影微侵幌，萤光几背灯。","西风才一夕，先与客愁应。"]},{"t":"迎秋八首 其四","f":"五言律诗","c":["旧不解惊秋，于今预理愁。","雄风三楚国，残月四更楼。","天外芙蓉剑，人间竹叶舟。","凉宵聊邂逅，不似梦中游。"]},{"t":"迎秋八首 其五","f":"五言律诗","c":["青山秋缓缓，白发鬓匆匆。","赋笔期霜雁，琴心款夜桐。","藕丝侵水碧，鱼眼泣波红。","莲唱歌年少，江南一梦中。"]},{"t":"迎秋八首 其六","f":"五言律诗","c":["当暑病犹轻，离魂几日阴。","羽笙天上曲，沟水路傍吟。","渡鹊无聊事，归禽有限心。","炎光劳缱绻，回首怨寒砧。"]},{"t":"迎秋八首 其七","f":"五言律诗","c":["投分留纨扇，怀恩记葛衣。","兴亡凭一泪，去住恨双违。","戏蝶情还在，元禽巷已非。","贮愁蜻蛚馆，旧已遣莎肥。"]},{"t":"迎秋八首 其八","f":"五言律诗","c":["吴茧初成练，商声畏上弦。","到来拚落叶，先事怪鸣蝉。","暗湿三更露，公收万里烟。","亭亭苍壁外，云岫弄馀妍。"]},{"t":"寒月","f":"五言律诗","c":["寒光清不极，一半上东峰。","霜净初弦小，烟平素影重。","江山群动息，河汉九霄封。","迥绝宵钟后，吾生定几逢。"]},{"t":"早春三首 其一","f":"五言律诗","c":["光气浮莎径，红滋点药畦。","晴丝弱柳外，夕蝶小窗西。","风细千波绿，云生一片低。","天情随物理，色色与春齐。"]},{"t":"早春三首 其二","f":"五言律诗","c":["不觉故心移，年华冉冉知。","晴窗熏午睡，喧步爱芳吹。","幸缓西园梦，还留朔雪悲。","含情方几日，谁道鬓添丝。"]},{"t":"早春三首 其三","f":"五言律诗","c":["向夜月迎人，空烟合望新。","落梅轻去影，乳鸟乍啼晨。","碧水涵苔暗，流光散露匀。","良宵仍蕴藉，悽恻奈何春。"]},{"t":"十二月八夜看月","f":"五言律诗","c":["寒月静不迥，中天白霭分。","烟空含树色，星浅入冰纹。","梦觉疑无定，凄清受已勤。","遥情谁寄托，千里一氤氲。"]},{"t":"初九夜再赋","f":"五言律诗","c":["迢递缓当天，浮光始出弦。","桂丛含雾隐，梅影弄霜妍。","分镜知谁照，寒蟾苦欲仙。","明珠期有赠，还恐雪侵年。"]},{"t":"正月十六夜重赋","f":"五言律诗","c":["出岫试娟娟，光侵落照天。","昨宵深困雨，初夜未亏圆。","透碧融霜气，凝晖款夕烟。","梅香来近远，稍觉送微暄。"]},{"t":"与唐须竹夜话二首 其一","f":"五言律诗","c":["九春初歇雨，花屐不相期。","踏藓亦何适，临风久系思。","秋毫分九级，火电掣双眉。","不与通消息，含情更待谁。"]},{"t":"与唐须竹夜话二首 其二","f":"五言律诗","c":["鼎鼎千秋意，劳劳夜语传。","六经谁楚汉，一击试鹰鹯。","偶觉空群马，人疑泛月船。","名心消已尽，无望古今怜。"]},{"t":"始晴","f":"五言律诗","c":["春尽试新晴，高天起夕清。","南飞双鸟白，西上一星明。","润叶沾青露，凉萤傍紫萍。","当年未萧瑟，曾此晚愁轻。"]},{"t":"湄水月泛同芋岩","f":"五言律诗","c":["泛宅非今日，清欢任偶携。","滩光月影上，山色晚霞西。","极目随移棹，生涯试杖藜。","江洲无载酒，还似武陵溪。"]},{"t":"八月梨花","f":"五言古诗","c":["夕吹喧风叶，初暾炫露条。","涂阴新紫荐，大谷早英飘。","留蝶寻香薄，迟莺忆梦遥。","迎凉催晓色，倚雪抗清霄。","恨讵青春谢，姿矜白日昭。","洁纨悲汉扇，瑶馆驻秦箫。","抱影空含碧，凝魂映泬寥。","云痕将桂粟，湘怨亘兰苗。","修月飞琼柹，凌空舞素潮。","西乌歌正急，南树梦犹妖。","瀚海寒偏耐，哀家韵未饶。","一桐虚井砌，片叶点诗瓢。","衔去元禽远，归来白雁邀。","馀芳回羯鼓，幽约后星桥。","江介芦花冷，扬州玉蕊凋。","函情摇落日，芳信在山椒。"]},{"t":"新秋看洋山雨过","f":"五言古诗","c":["南楚秋风日，轻阴太白方。","参差分远嶂，明灭互斜阳。","旋度云间树，还吹山际香。","鹭飞初掠润，燕语乍矜凉。","云断天逾碧，林疏野乍光。","馀霞侵月浅，晚雾过溪长。","薄袂泠泠善，闲愁鼎鼎忘。","萧斋聊隐几，吾道在沧浪。"]},{"t":"山居杂体建除","f":"五言古诗","c":["建宇依回岫，锄畦沿涧流。","除云无过客，留鸟伴孤游。","满径萦霜带，遥天佩月钩。","平泉空木石，元晏自春秋。","定里窥僧际，醺馀缓宿愁。","执交顽石古，送远野鸥浮。","破雪寻新蕈，迎晴验午鸠。","危烟征杳汉，细草藉香柔。","成绩缘蜂课，纷争笑蚁䗋。","牧书袪粉蠹，篆壁写蜗牛。","开圃蛛丝密，支床龟息幽。","闭关思物理，杜德拟天休。"]},{"t":"哀管生永叙","f":"五言古诗","c":["落叶风喧夕，啼鸦柏冷霜。","如何悼亡客，还有丧予伤。","岳径云藏雪，洋泉月引凉。","培兰将九畹，鍊镜巳三商。","带草先摧绿，传灯独秉光。","思深千里驾，望属百身良。","煜煜芝房折，悠悠蒿里长。","紫囊悲太傅，缃帙冷中郎。","春谷江流远，南云塞路荒。","人情谁剑挂，天道岂弓张。","交绝怜东里，狂歌问子桑。","贡生空委佩，鲍叔未分粻。","笛咽山阳馆，琴残子敬床。","宁知哀九辩，不及待沈湘。"]},{"t":"恺六种凤仙花盈亩聊题长句","f":"五言古诗","c":["光风何处好，樾径启朝阳。","竹里天凝绿，梅村月旧黄。","名花拚物玩，小品眷幽芳。","蕉露分长润，苔茵荫午凉。","学仙初羽化，字凤欲歌狂。","茎脆空清八，阴圆碧霭张。","欲言鹦咮曲，如舞蝶襟忙。","紫晕飞初日，华吹结绀霜。","凝丹猩褫血，浅素雪添香。","不解邢憎尹，终谐鶠侣皇。","分妍矜色色，薄袂共洋洋。","蝾臂虽多妒，荑尖得上妆。","素轮宜晚拍，义甲惜春藏。","小触娇旋怒，多灵敛亦翔。","清琴蛇腹古，丸药蔻胎康。","瑞约宜男早，心同栀子长。","闲居人自雒，至止客怀湘。","相约秋光里，娟娟誓不忘。"]},{"t":"咏史二十七首 其一","f":"古风","c":["箕子生传淇范，刘歆死击谷梁。","叛父祇求媚莽，称天原是存商。"]},{"t":"咏史二十七首 其二","f":"古风","c":["堕泪曲江秋燕，白头小范黄花。","变雅三年破斧，续骚一部怀沙。"]},{"t":"咏史二十七首 其三","f":"古风","c":["桎梏荀卿性恶，逍遥王衍无为。","指鹿不迷物则，问蛙方證希夷。"]},{"t":"咏史二十七首 其四","f":"古风","c":["安世不藏父恶，南轩尽掩前羞。","迁史直承尧典，紫阳曲学春秋。"]},{"t":"咏史二十七首 其五","f":"古风","c":["公主盘飧赌命，上卿片唾输头。","偏是羁孤臣妾，贪他菌蟪春秋。"]},{"t":"咏史二十七首 其六","f":"古风","c":["中垒传经烧汞，东坡抗疏逃禅。","梦傍昌黎床榻，炉兼万毕铜铅。"]},{"t":"咏史二十七首 其七","f":"古风","c":["信陵饮酒近内，步兵泣路驱车。","赢得不知别苦，难忘聊复愁予。"]},{"t":"咏史二十七首 其八","f":"古风","c":["田丰死争官渡，鸱夷不谏夫椒。","未到水穷山尽，难回坠石狂潮。"]},{"t":"咏史二十七首 其九","f":"古风","c":["凤杳扬雄拾羽，龙乖谷永探鳞。","奇字詅痴万卷，危言卖绽千春。"]},{"t":"咏史二十七首 其十","f":"古风","c":["元载饥寒扫迹，苏秦车骑迎门。","裹马装妻勾当，髑髅血肉乾坤。"]},{"t":"咏史二十七首 其十一","f":"古风","c":["李绩逢人便杀，西巴见鹿犹怜。","自让孟孙眼孔，何须武瞾金钱。"]},{"t":"咏史二十七首 其十二","f":"古风","c":["泜水潍城垓下，陈仓子午褒斜。","先手偏争后着，一羊不奈三叉。"]},{"t":"咏史二十七首 其十三","f":"古风","c":["曹魏登坛舜禹，萧梁塔庙瞿昙。","酸得不禁太苦，悟来妙在无惭。"]},{"t":"咏史二十七首 其十四","f":"古风","c":["代契丹憎延广，为司马爱谯周。","一线容头活计，二毛肉袒风流。"]},{"t":"咏史二十七首 其十五","f":"古风","c":["肯死魔留佛种，再来鹰化鸠啼。","借问邦昌伪相，何如任永淫妻。"]},{"t":"咏史二十七首 其十六","f":"古风","c":["方寸止知老母，始终唯报韩王。","家鹜尽供玉馔，元禽长寄雕梁。"]},{"t":"咏史二十七首 其十七","f":"古风","c":["魏篡陈思堕泪，晋亡谢客挥戈。","夺嫡封侯愿力，顽民义士风波。"]},{"t":"咏史二十七首 其十八","f":"古风","c":["孝逸妆台授钺，崔生穹帐修文。","临镜妖狐国史，擭阑鹦鹉将军。"]},{"t":"咏史二十七首 其十九","f":"古风","c":["郗鉴生怜逆子，沈充死愧贤孙。","桂蠹何伤芳树，兰芽不染滫根。"]},{"t":"咏史二十七首 其二十","f":"古风","c":["着面维州黑子，还魂免役青蚨。","皮砌只争燖揉，头倾忘却支吾。"]},{"t":"咏史二十七首 其二十一","f":"古风","c":["狄青非万人敌，韦皋亦百里才。","学击鹰鹯誇俊，知音黄雀生灾。"]},{"t":"咏史二十七首 其二十二","f":"古风","c":["子厚县崖题壁，昌黎华岳投书。","小人可使有勇，君子其蔽也愚。"]},{"t":"咏史二十七首 其二十三","f":"古风","c":["擒守忠如捉鳖，奉嘉王亦建瓴。","流汗帆风摇橹，埋头白昼囊萤。"]},{"t":"咏史二十七首 其二十四","f":"古风","c":["习气齐邱说法，门头唐主参禅。","圆顶方袍天子，黄扉紫阁神仙。"]},{"t":"咏史二十七首 其二十五","f":"古风","c":["家法销兵杯酒，朝章决狱风波。","无信人言采苦，其则不远伐柯。"]},{"t":"咏史二十七首 其二十六","f":"古风","c":["蟋蟀消归秋壑，鹦?生受思陵。","几队吟虫语鸟，一抔秋州冬青。"]},{"t":"咏史二十七首 其二十七","f":"古风","c":["乍可黄冠归宋，羞将白血殉元。","蜜蘖不争甜苦，猿虫各有精魂。"]},{"t":"耒阳曹氏江楼迟旧游不至","f":"七言律诗","c":["野水瑶光上小楼，关河寒色满楼头。","韩城公子椎空折，楚国佳人橘过秋。","淅淅雁风吹极浦，鳞鳞枫叶点江洲。","霜华夜覆荒城月，独倚吴钩赋远游。"]},{"t":"圆通庵初雨睡起闻朱兼五侍御从平西谒桐城阁老归病书戏赠","f":"古风","c":["秋井拖阴柳色阑，疏云开碧整归鞍。","梧桐新坠平津苑，鸂?遥飞御史滩。","愁里关山江北杳，尊前星汉粤天寒。","棋枰应尽中原略，莫遣苍生属望难。"]},{"t":"李广生自黔阳生还归阙率尔吟赠并感洪一龙三阳太仆山公及郎君郑石诸逝者浮湘亭之游","f":"七言律诗","c":["涟水东流落月横，浮湘亭上似三生。","汉庭旧节归华表，粤道旌旗乱早莺。","酒侣垂杨悲墓合，世情蛱蝶到春惊。","如君豪气矜淮海，恨到消沈泪亦倾。"]},{"t":"答姚梦峡秀才见柬之作兼呈金道隐黄门李广生彭然石二小司马","f":"七言律诗","c":["遥求勾漏寻灵饵，却背仙坛访上元。","初服偶然抛竹箨，融情一倍感芳荃。","云畦过雨怀红药，春泛消愁畏绿尊。","千古英雄无死处，酒徒高唱感夷门。"]},{"t":"五日小饮兼五舟中寄人时两上书忤时相俟谴命故及之","f":"七言律诗","c":["垂垂江上瘴云飞，也听莲舟挝鼓归。","炎海蛟龙吞楚客，绿云烟水吊湘妃。","故园蒲草空盈把，过岭笳声尚合围。","哀些远凭清思抑，目前殊觉解人稀。"]},{"t":"留守相公六帙仰同诸公共次方密之学士旧韵二首 其一","f":"七言律诗","c":["千古英雄此赤方，漓江南下正汤汤。","情深北阙多艰后，兴寄东皋信美乡。","进酒自吹松粒曲，裁诗恰赋芰荷裳。","萧森天放湘累客，得倚商歌侍羽觞。"]},{"t":"留守相公六帙仰同诸公共次方密之学士旧韵二首 其二","f":"七言律诗","c":["凉生恰恰桂江天，万里吴皋秋信传。","月拟上轮分海晕，风初过岭霁蛮烟。","雕戈数转三襄影，花坞凭留七月仙。","莫讶维州争论亟，河山清晏自平泉。"]},{"t":"石板滩中秋无月奉怀家兄","f":"七言律诗","c":["颓岸清江隔晚烟，鳞鳞云起夕阳天。","秋声已觉频喧夜，明月心知不易圆。","桂阙参差疑羽客，芦中迷离访渔船。","刀头飞镜终无准，今夕何年倍惘然。"]},{"t":"读指南集二首 其一","f":"七言律诗","c":["绛节生须抱璧还，降笺谁捧尺封闲。","沧波淮海东流水，风雨扬州北固山。","鹃血春啼悲蜀鸟，鸡鸣夜乱度秦关。","琼花堂上三生路，已滴燕台颈血殷。"]},{"t":"读指南集二首 其二","f":"七言律诗","c":["扬州不死空坑死，出使皋亭事未央。","鸣鴂春催三月雨，丹枫秋忍一林霜。","䃃门鹤唳留朱序，文水鱼书待武阳。","沧海金椎终寂寞，汗青犹在泪衣裳。"]},{"t":"冬尽过刘庶先夜话效时","f":"七言律诗","c":["端自莲花瓣里来，幻身真作冻蜂猜。","世如棋弈辘轳劫，话到文章婪尾杯。","三公叔夜龙鸾客，兀者郑侨斥鴳才。","金销石泐寻常事，惭愧寒香一径梅。"]},{"t":"续哀雨诗四首 其一","f":"七言律诗","c":["寒烟扑地湿云飞，犹记馀生雪窖归。","泥浊水深天险道，北罗南鸟地危机。","同心双骨埋荒草，有约三春就夕晖。","檐溜渐疏鸡唱急，残灯炷落损征衣。"]},{"t":"续哀雨诗四首 其二","f":"七言律诗","c":["晴月岚平北斗移，挑灯长话桂山时。","峒云侵夜偏飞雨，宿鸟惊寒不拣枝。","天吝孤臣唯一死，人拚病骨付三尸。","阴晴旦暮寻常极，努力溯洄秋水湄。"]},{"t":"续哀雨诗四首 其三","f":"七言律诗","c":["羊肠虎穴屡经过，老向孤峰对梦婆。","他日凭收柴市骨，此生已厌漆园歌。","藤花夜落寒塘影，雁字云低野水波。","樾馆无人苔砌冷，桂山相较未愁多。"]},{"t":"续哀雨诗四首 其四","f":"七言律诗","c":["桂山哀雨旧诗留，读向泉台忆得不。","卞壸可容魂大笑，王章不为死含愁。","丹枫到冷心元赤，黄鞠虽晴命亦秋。","韶月年年春日㬉，倡条冶叶漫当头。"]},{"t":"人日 其一","f":"七言律诗","c":["人日犹馀寅正腊，深阴不识月初弦。","春光荏苒虚梅信，朔雪霏微乱柳烟。","何处暄风催綵胜，谁将病骨祀华年。","中宵欲待清霜霁，珠雨还飞玉粟田。"]},{"t":"又雪同欧子直","f":"七言律诗","c":["溪边林外转霏微，几处新莺禁不飞。","即次青春欺白发，丁宁酒力试寒威。","连天朔雪悲明月，昨日西清忆落晖。","为报春光多蕴藉，来朝一倍报芳霏。"]},{"t":"五日携攽儿同子直洎贤从哲仲小饮分得端字","f":"七言律诗","c":["今年五日尚馀寒，剪剪菖风摆露难。","雨歇罩鱼垂柳径，人归贳酒白云端。","丹心綵笔三湘事，霜鬓朱颜一镜看。","彭泽无田供秫米，何须粔敉饱龙餐。"]},{"t":"即事有赠","f":"七言律诗","c":["青门绿野两情忘，柳宅桃津一径长。","四海交穷怜白发，双星夜永看珠光。","梅香早透胧胧月，酒坐寒侵款款霜。","咏史已惊开竹素，挑灯无事话沧桑。"]},{"t":"人日新晴","f":"七言律诗","c":["昨宵弦上晴天月，人日青开媚景烟。","柳带小吹摇露颗，红芽纤出破苔钱。","胜常难问求凰意，怀旧空吟落雁篇。","为恼新莺惊午睡，不容梦蝶驻华年。"]},{"t":"秋雨同子直","f":"七言律诗","c":["秋阴何来飞雨淙，杜陵叹之后尧江。","井桐已落不知数，水鸟无愁聊自双。","游屐几曾过柳岸，青尊只少对兰缸。","犹传锦字开幽独，湿月穿云上小窗。"]},{"t":"又雨","f":"七言律诗","c":["昨日馀暄黄稻天，轻雷斜过晚霞边。","林光留日犹多碧，暝色侵云不耐烟。","凌藉晚红欺菡萏，风光苔色长连钱。","栖迟藋径经过少，几厌溪声柳外喧。"]},{"t":"夜","f":"七言律诗","c":["始夜枫林初下叶，清秋弦月欲生华。","凉凝露草流萤缓，云断西峰大火斜。","藏壑馀生惊逝水，迷津天上惘星槎。","兴亡聚散经心地，高柳萧森隐荻花。"]},{"t":"元日过子直奕","f":"七言律诗","c":["今日何年复岁朝，晓窗新梦试逍遥。","韶光流转谁消息，春赏殷勤久寂寥。","竹径云深通绿霭，兰芽雨沁透红苗。","高斋奕散前溪路，回望炊烟隔小桥。"]},{"t":"故孝廉李一超以怀贞穷愁死不及有嗣息元配林孺人掖咡太孺人于痹病中十四年不舍榻右猝遘危疾临终悲咽以不得躬亲大事为憾啼声未绝而逝余于一超不浅视道路感泣者自逾涯量裁二诗以将哀尤为太孺人悯悼焉 其一","f":"七言律诗","c":["怀清台上望孤忠，剩水馀山恨尽同。","块肉无留犹赵氏，炊烟不热自梁鸿。","亭亭宝婺邀残月，转转金轮御朔风。","十四年来千种事，凄凉彤管不书功。"]},{"t":"故孝廉李一超以怀贞穷愁死不及有嗣息元配林孺人掖咡太孺人于痹病中十四年不舍榻右猝遘危疾临终悲咽以不得躬亲大事为憾啼声未绝而逝余于一超不浅视道路感泣者自逾涯量裁二诗以将哀尤为太孺人悯悼焉 其二","f":"七言律诗","c":["从知生死一浮沤，大誓宏深不易酬。","萱草幸留春百岁，桂轮难满月三秋。","鸡声五夜闻遗语，鹤发千梳绾别愁。","犹有寒荠青半亩，留调膏粥侍晨羞。"]},{"t":"刘若启为余兄弟排难已招泛虎塘叙其家乘会当六帙帨辰欢宴之下遂允贶室子敔儿","f":"七言律诗","c":["此生相聚太从容，海徙山移梦后逢。","急难情深矰缴缓，根株心许茑萝封。","百年初识团圞相，双径从看偃盖松。","拟煮丹砂回白首，年年吹笛上嵩峰。"]},{"t":"湖外遥怀些翁","f":"七言律诗","c":["心心长不断湖天，满月孤星旧有缘。","野烧三叉馀幸草，湘流九面惘胶船。","寒深鹤带尧年雪，海阔龙分佛口涎。","闻说当机唯一指，皈心欲扣逆流舷。"]},{"t":"寄怀青原药翁","f":"七言律诗","c":["霜原寸草不留心，一线高秋入桂林。","哭笑双遮∴字眼，宫商遥绝断纹琴。","情知死地非长夜，屡卜游魂得返吟。","唯有寻思归计好，黄金装额怕春深。"]},{"t":"春日山居戏效松陵体六首 其一","f":"七言律诗","c":["垂垂雨足晓雷收，草阁凭崖似倚楼。","上赤数莺吹几叠，之元一瀑写双钩。","云生右史蟫餐润，花坠中丞蚁渡幽。","已过清明瓜未种，憎人相拟到秦侯。"]},{"t":"春日山居戏效松陵体六首 其二","f":"七言律诗","c":["小窗日卯破清酣，渐老帘帏上午岚。","梵夹偶披唯以九，丹图横看亦函三。","西峰月瓦从飘练，曲径苔裀稳卧蚕。","千亩琅玕溪涨外，经旬玉版不曾参。"]},{"t":"春日山居戏效松陵体六首 其三","f":"七言律诗","c":["即栗无多染沁泥，危桥不渡只前溪。","杨花甲坼占风北，鷤䳏丁宁唤日西。","漏白蘋开十字眼，路青蘅试五花蹄。","行縢还惹空青湿，篝火垆边恰煮藜。"]},{"t":"春日山居戏效松陵体六首 其四","f":"七言律诗","c":["夭桃十树柳千条，诅雨迎晴意两消。","活影玻瓈沈曲沼，吹香靺鞨糁平桥。","游龙依藓红鳞密，鱼虎分波翠晕摇。","莫厌溪声喧午梦，乘流初好泛诗瓢。"]},{"t":"春日山居戏效松陵体六首 其五","f":"七言律诗","c":["荠美先登谶岁饶，回塘及㬉浸长腰。","圆餐韧雪舂猫耳，甂瓮盦香糁虌苗。","带雨馌妻簪踯躅，催耕抟黍啄螵蛸。","高斋寓目忘天暝，黄犊将鸠上小桥。"]},{"t":"春日山居戏效松陵体六首 其六","f":"七言律诗","c":["垂杨擭径转依依，绿掩芉眠不置扉。","茧室拟营桑叶少，虫书欲就柿林稀。","閒栽生苄蒸寒药，拟架番松却暑威。","新韭半畦钟乳长，无妨览镜诧新肥。"]},{"t":"期徐蔚子虎塘迟至余暑病先归蔚子独留万绿池与若启月饮共相太息寄此谢之","f":"七言律诗","c":["稻花风转接䍦吹，系辔萧条占桧枝。","画扇红牙前夕酒，青山白雪几年诗。","千秋华表留仙语，一曲沧浪鼓枻悲。","为惜君愁须缓缓，相逢知有泪双垂。"]},{"t":"答黄度长","f":"七言律诗","c":["东篱花冷候虫惊，澬水连湘一雁征。","霜色已凋隋岸柳，秋风遗意武昌城。","传经鲁壁闻丝竹，述酒柴桑访秫粳。","心迹元同难举似，云飞叶落两含情。"]},{"t":"得青原书","f":"七言律诗","c":["青原题书寄南岳，经年霜雪中回还。","夕阳秋雨各津涘，鸟道别峰许跻攀。","西台江水流清泚，东林菡萏开斑斓。","春鸿社燕皆旦夕，不碍幽忧长闭关。"]},{"t":"河田营中夜望","f":"七言绝句","c":["夜烧连山接暮云，牙旌高捲管弦闻。","负恩自笑夷门客，魂断邯郸晋鄙军。"]},{"t":"桂林偶怨","f":"七言绝句","c":["灵药成虚旧恨空，征衣无那楝花风。","丝丝春雨垂帘下，又向天涯识塞鸿。"]},{"t":"自南岳理残书西归慈侍困于土人殆滨不免太孺人怛悯废食既脱谕令去此有作聊呈家兄","f":"七言绝句","c":["春零慈竹惜徘徊，孤燕孤飞鹰隼猜。","莫是渔郎归棹错，桃花不为避秦开。"]},{"t":"题彭然石舠壁","f":"七言绝句","c":["旧曾相识此扁舟，江黑云低对戍楼。","象帝祠前秋似叶，伏波山下月如钩。"]},{"t":"偶闷自遣","f":"七言绝句","c":["鸡声残月夜如何，水级危轮又一过。","扯断藕丝无住处，弥天元不罥修罗。"]},{"t":"过涉园问季林疾遣作早梅诗四首 其一","f":"七言绝句","c":["雨轻偶破山云出，花浅时闻小径香。","总是村烟开不彻，尽教无月也昏黄。"]},{"t":"过涉园问季林疾遣作早梅诗四首 其二","f":"七言绝句","c":["晚香消尽寒香接，无日无花不早开。","莫倚文殊能问病，现身天女出檐来。"]},{"t":"过涉园问季林疾遣作早梅诗四首 其三","f":"七言绝句","c":["江南塞北总阑珊，幽谷嫣然一破颜。","无数明玑垂屋角，牵萝何必卖珠还。"]},{"t":"过涉园问季林疾遣作早梅诗四首 其四","f":"七言绝句","c":["先机买隐君能早，后着投生我自痴。","也共巡檐吟不了，耐他冷蕊共疏枝。"]},{"t":"过西明寺追怀怡一上人示苍枝慈智二首 其一","f":"七言绝句","c":["缥渺诸天缟雪飞，垆烟初㶿湿云衣。","重来春水迷苍翠，凄绝苏闉画板归。"]},{"t":"过西明寺追怀怡一上人示苍枝慈智二首 其二","f":"七言绝句","c":["冬葵滑熟菠薐脆，云子抄香凤乳花。","惭愧千金无报处，三生客在自蒸砂。"]},{"t":"从子敉遘闵以后与予共命而活者七年顷予窜身猺中不自以必生为谋敉因留侍伯兄时序未改避伏失据掠骑集其四维方间道往迎已罹鞠凶矣悲激之下时有哀吟草遽佚落仅存绝句四首 其一","f":"七言绝句","c":["斜日荒荒打枣天，山头回首杳墟烟。","当时不道今生别，犹向金风泪黯然。"]},{"t":"从子敉遘闵以后与予共命而活者七年顷予窜身猺中不自以必生为谋敉因留侍伯兄时序未改避伏失据掠骑集其四维方间道往迎已罹鞠凶矣悲激之下时有哀吟草遽佚落仅存绝句四首 其二","f":"七言绝句","c":["黑海难全一叶舟，谁将完卵望鸺鹠。","含羞含恨无终极，稚子牵衣笑邓攸。"]},{"t":"从子敉遘闵以后与予共命而活者七年顷予窜身猺中不自以必生为谋敉因留侍伯兄时序未改避伏失据掠骑集其四维方间道往迎已罹鞠凶矣悲激之下时有哀吟草遽佚落仅存绝句四首 其三","f":"七言绝句","c":["割骨分肌亦屡禁，如今万矢倍攒心。","岳阡秋草应含怨，万树严霜杀一林。"]},{"t":"从子敉遘闵以后与予共命而活者七年顷予窜身猺中不自以必生为谋敉因留侍伯兄时序未改避伏失据掠骑集其四维方间道往迎已罹鞠凶矣悲激之下时有哀吟草遽佚落仅存绝句四首 其四","f":"七言绝句","c":["情根悔不锄苗早，蔓草萦丝自惹愁。","至竟潘安悲白首，人间何有坠珠楼。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其一","f":"七言绝句","c":["菖雨蘋风杜若香，怀沙千古吊潇湘。","迟回怕唱招魂曲，不信人间别已长。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其二","f":"七言绝句","c":["通眉旧是玉楼仙，昌谷春消野竹烟。","誓倒奚囊传好句，人间差有外兄贤。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其三","f":"七言绝句","c":["荆榛小径对春溪，月上芭蕉碧影迷。","池馆山阳留不得，愁来唯伴野猿啼。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其四","f":"七言绝句","c":["枯木难消只赋心，散愁长欲寄知音。","调孤雌霓休文句，哭碎灵床子敬琴。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其五","f":"七言绝句","c":["瓣香洒血气奔雷，采葛歌残击筑哀。","十四年来争一死，英雄消受野棠开。"]},{"t":"哭欧阳三弟叔敬沈湘六首 其六","f":"七言绝句","c":["南荣枝叶各相当，抛玉挥金意共长。","岸谷消沉羊叔子，推恩无分到中郎。"]},{"t":"小步 其一","f":"七言绝句","c":["新虹酿㬉带馀清，云里东峰一曲晴。","步步看花兼看叶，胎红乳白各分明。"]},{"t":"吟得","f":"七言绝句","c":["双溪欲合声逾急，孤鸟将栖晚更飞。","唯有小窗人睡起，不知香尽落春衣。"]},{"t":"折杨柳","f":"七言绝句","c":["儿家门前杨柳枝，南来北往折残时。","去去青骢都不返，郎行莫再挽青丝。"]},{"t":"明妃曲","f":"七言绝句","c":["金殿葳蕤锁汉宫，单于谈笑借春风。","黄沙已作无归路，犹愿君王斩画工。"]},{"t":"南岳摘茶词十首 其一","f":"七言绝句","c":["深山三月雪花飞，折笋禁桃乳雀饥。","昨日刚传过谷雨，紫茸的的赛春肥。"]},{"t":"南岳摘茶词十首 其二","f":"七言绝句","c":["湿云不起万峰连，云里闻他笑语喧。","一似洞庭烟月夜，南湖北浦钓鱼船。"]},{"t":"南岳摘茶词十首 其三","f":"七言绝句","c":["晴云不采意如何，带雨掠云摘倍多。","一色石姜叶笠子，不须绿箬衬青蓑。"]},{"t":"南岳摘茶词十首 其四","f":"七言绝句","c":["一枪才展二旗斜，万簇绿沈间五花。","莫道风尘飞不到，鞠尖队队满洲靴。"]},{"t":"南岳摘茶词十首 其五","f":"七言绝句","c":["琼尖新炕凤毛毸，玉版兼蒸龙子胎。","新化客迟六峒远，明朝相趁出城来。"]},{"t":"南岳摘茶词十首 其六","f":"七言绝句","c":["小筑团瓢乞食频，邻僧劝典半畦春。","偿他监寺帮官买，剩取筛馀几两尘。"]},{"t":"南岳摘茶词十首 其七","f":"七言绝句","c":["丁字床平一足雄，踏云稳坐似凌空。","商羊能舞晴天雨，底用劳劳百脚虫。"]},{"t":"南岳摘茶词十首 其八","f":"七言绝句","c":["清梵木鱼暂放松，园园锯齿绿阴浓。","揉香挼翠三更后，刚打乌啼半夜钟。"]},{"t":"南岳摘茶词十首 其九","f":"七言绝句","c":["山下秧争韭叶长，山中茶宝马兰香。","逐队上山收晚茗，柰他布谷为人忙。"]},{"t":"南岳摘茶词十首 其十","f":"七言绝句","c":["沙弥新学唱皈依，板眼初清错字稀。","贪听姨姨采茶曲，家鸡又逐野凫飞。"]},{"t":"初度日占六首 其一","f":"七言绝句","c":["横风斜雨掠荒邱，十五年来老楚囚。","垂死病中魂一缕，迷离唯记汉家秋。"]},{"t":"初度日占六首 其二","f":"七言绝句","c":["一万五千三百三，愁丝日日缠春蚕。","天涯地窟知音绝，新剪牛衣对雨谈。"]},{"t":"初度日占六首 其三","f":"七言绝句","c":["十一年前一死迟，臣忠妇节两参差。","北枝落尽南枝老，辜负催归有子规。"]},{"t":"初度日占六首 其四","f":"七言绝句","c":["新买茱萸半亩堂，苔侵床足月侵墙。","天涯芳草迷归路，病叶还禁一夜霜。"]},{"t":"初度日占六首 其五","f":"七言绝句","c":["十载每添新鬼哭，泪如江水亦乾流。","青髭无伴难除雪，白发多情苦恋头。"]},{"t":"初度日占六首 其六","f":"七言绝句","c":["陈抟驴背笑难禁，龚胜床头饿称心。","雪搅九微香炬暗，未知除夕是晴阴。"]},{"t":"竹枝词十首 其一","f":"七言绝句","c":["嫩鹌鹑斗不相降，野鸳鸯飞不作双。","昔年挑冰上雪岭，今年贩水下长江。"]},{"t":"竹枝词十首 其二","f":"七言绝句","c":["暮雨朝云神女峰，三朝三暮黄牛踪。","入峡来回看不厌，出峡对面不相逢。"]},{"t":"竹枝词十首 其三","f":"七言绝句","c":["巫山不高瞿塘高，铁错不牢火杖牢。","妾意似水水滴冻，郎心如月月生毛。"]},{"t":"竹枝词十首 其四","f":"七言绝句","c":["洞庭湖北汉水横，青草湖南湘水清。","两道湖光争潋滟，两般艇子各分明。"]},{"t":"竹枝词十首 其五","f":"七言绝句","c":["黄陵庙前班竹丛，巴邱湖上水连空。","生受鹧鸪啼夜雨，生成江兔拜秋风。"]},{"t":"竹枝词十首 其六","f":"七言绝句","c":["鸬鹚衔鱼只道饥，鵁鶄运目也孤飞。","江花笑水郎不去，白浪掀天郎不归。"]},{"t":"竹枝词十首 其七","f":"七言绝句","c":["荷花有日绽金须，荷叶无心系水珠。","浪打萍开从恼妾，萍留浪去恰怜渠。"]},{"t":"竹枝词十首 其八","f":"七言绝句","c":["江边寒梅自着花，江上女儿自斗茶。","浪向花前爇片脑，浪疑茶里点脂麻。"]},{"t":"竹枝词十首 其九","f":"古风","c":["杨柳湾头?舸开，杨花飞雪逐船来。","郎爱杨花随舵转，侬怜杨柳倒根栽。"]},{"t":"竹枝词十首 其十","f":"七言绝句","c":["巫山欲出三峡中，狼山还隔海门东。","何人不打开船鼓，何人解使斗帆风。"]},{"t":"忍俊九首 其一","f":"七言绝句","c":["金鸡只遣报青蝇，发箧探丸等不应。","东海未亏输一粒，无妨郭索与横行。"]},{"t":"忍俊九首 其二","f":"七言绝句","c":["鲩眼红如鲤尾红，吹沙蚀岸尽春风。","任公无用钓缗处，毕竟鱼还死水中。"]},{"t":"忍俊九首 其三","f":"七言绝句","c":["腊月桃花带雪妍，迎头早唱卖花喧。","若教赊贩春千日，借问姚黄得几钱。"]},{"t":"忍俊九首 其四","f":"七言绝句","c":["豺祭羔豚獭祭鲜，不须欣享且争妍。","王唐瞿薛当年盛，又束潘妃步步莲。"]},{"t":"忍俊九首 其五","f":"七言绝句","c":["波斯匿王不自知，恒河未改雪飘眉。","流沙瀰瀰鱼虾少，惆怅滩头立鹭鸶。"]},{"t":"忍俊九首 其六","f":"七言绝句","c":["勾芒跣足苦争先，昨夜酸风雪满天。","不见旗亭游冶客，春归才着土牛鞭。"]},{"t":"忍俊九首 其七","f":"七言绝句","c":["苦为侯城惜道穷，姚师闲泪洒秋风。","螟蛉若续读书种，上计偷香是贾充。"]},{"t":"忍俊九首 其八","f":"七言绝句","c":["悟尽人间得未曾，食轮先转法轮僧。","莫将负鼎嗤伊尹，草具匆匆杀范增。"]},{"t":"忍俊九首 其九","f":"古风","c":["五色云中鸂?衣，凤凰池上带香归。","并刀剪落金风里，乞与谁家作舞衣。"]},{"t":"长歌行","f":"五言古诗","c":["搏桑无落景，瑶水无逝波。","千岁有问津，微生遂经过。","偶零玉露浆，聊弄素女蛾。","不知人间秋，落叶纷已多。","进酒白玉觞，侑之缓声歌。","长旦无凝云，毕景皆赪霞。","俯睨星火流，停欢待伊何。"]},{"t":"独漉篇","f":"古风","c":["独漉浊水江，水浊菱叶青。","不畏浊水寒，但畏浊水腥。","水腥鱼乱，虾蟹相半。","风起月黄，菱叶苦绊。","东家孤儿西家妇，夜闻啼声旦拍手。","宝刀旧结并州豪，春风日醉新丰酒。","耐可死浊水中，不能宿秋草陌。","挥刀难割空中烟，长叹流光坐閒掷。"]},{"t":"君子有所思行","f":"古风","c":["天道不可见，往来孰令亲。","求仁信繇己，循我得其真。","宿粮陟穹谷，问彼度世人。","浮屠东入汉，老?西去秦。","骛神离宝命，歘景搴轻尘。","屈理遂所欢，淫曼增迷沦。","孟轲丧齐梁，辩言隐千春。","坚垒拒输攻，墨守固重闉。","倾筐贵所寘，室远愿不伸。","夜闻曷旦急，秋惊络纬新。","时哉随逝水，极渚暇逡巡。"]},{"t":"枯鱼过河泣","f":"古风","c":["笼中鸭，声唈唈。","水中鸭，游濈濈。","谓水中鸭，何妨分我以馀湿。","越王尝吴溲，宫中皆含蕺。","汉有张良楚项伯，泾清渭浊皆吞吸。","凤凰餐竹花，桑扈啄场粒，嗟尔唼唼今何及。","君不见枯鱼过河泣，胡不早淤浊水学鳅鳛。"]},{"t":"来日大难","f":"古风","c":["来日大难，毛凋羽残。","不知今者，谁为妙颜。","醇酒肥牛，何用解忧。","仙人王乔，足可遨游。","黄金可作，尘世可度。","鳅游浊水，龙上天角。","没命黄泉，志存偓佺。","遗物独往，杳若孤烟。","轩辕乘龙，髣髣云中。","天老操辔，髣髴云内。","精魂相存，生死同门。","千秋万岁，乐以忘言。"]},{"t":"长相思二首 其一","f":"古风","c":["长相思，永别离，愁眉镜觉心谁知。","蛛网闲窗密，鹅笙隔院吹。","年华讵足惜，肠断受恩时。"]},{"t":"长相思二首 其二","f":"古风","c":["长相思，永离别，地坼天乖清泪竭。","油卜罢春灯，寒砧谢秋节。","宝带裂同心，他生就君结。"]},{"t":"箜篌引 其一","f":"古风","c":["弹箜篌，击鼍鼓，款留君，君不住。","素丝玉壶白水清，博山兰膏飞烟轻。","华月微风吹凤笙，他人不语君含情。","胡为乎凌狂波而乱流，从君不果心繁忧。","东海之鱼不可得，西飞之鸟不可留。","往者不谏，来者徒伤。","寸心炯炯明月光，千里万里随君旁。","君凌浊水不见影，青天高悬独傍徨。"]},{"t":"休洗红","f":"古风","c":["休洗红，洗多颜色坏。","东园桃李花，阳春不相待。","去时罗衣薄，来时罗衣寒。","天风日暮急，举袖君自看。","鸣蜩札札落柳枝，深闺年少犹不知。"]},{"t":"莫种树戏代山阴相公赠怀宁朱侍御","f":"古风","c":["莫种树，树长青扶疏。","朅来九子凤，故是白门乌。","白门乌，柏台鸟，欲啼不啼天未晓。","街鼓鼕鼕星欲稀，还向羽林门外飞。"]},{"t":"康州谣追哭督府义兴相公是去秋同邹管二中舍会公地","f":"古风","c":["可怜康州城，泷水从南来。","龙旗翩翩去何繇，苍梧迷密云不开。","秋风起，秋叶飞，旗翩翩，去不归。","乌头黑，雀头白，城上飞，声哑哑。","羽林军，神厩马，昨日灵羊溪，今日康江下。","杨花自飞鸟自栖，相公白旐清浔西，康州城下生蒺藜。"]},{"t":"斸蕨行","f":"古风","c":["清晨上南坂，芜草深没腰。","黄云冒山起，雪花零乱飘。","雪子穿棕笑，雪花漫棕衣。","飘衣湿尚可，悬愁空筐归。","土皮滑白斸断柄，短茎泥重淘寒井。","黄茅盖头雪侵领，奋椎力尽刚过颈。","绵绵咽咽声可怜，阿儿涕堕牵丝饼。","流泉浑浑浊如蓝，朦胧犹见伶仃影。","伶仃相扶过眼前，黄绵袄子雀儿毡，梦里春光快活天。","君不见马槽□□□东去，雪花洒血痕丹鲜。"]},{"t":"山居杂体两头纤纤","f":"七言绝句","c":["两头纤纤水溜绝。","半黑半白烧岭雪。","腷腷膊膊冻竹折。","磊磊落落飞霰屑。"]},{"t":"山居杂体五杂俎","f":"古风","c":["五杂俎，采野䔩。","往复还，沿溪谷。","不获巳，黄农伏。"]},{"t":"哭内弟郑忝生","f":"古风","c":["悠悠重悠悠，送子冈陇头。","乍可为陌上之秋草，繁霜一夕同荒邱。","不能为磷磷之白石，相看逝水旋东流。","与君别何所，庭前绿竹下。","日夕君不来，春云覆平野。","与君期何日，三五轮魄充。","君归黄泉去，月轮故未空。","君家旧住鹿门溪，君魂欲归道路迷。","与君相逢入桂城，铁骑斥野飞箭鸣。","旧愁疑在春梦惊，乃知君死而余生。","生亦不可期，死亦不可悲。","鸡鸣月落杉桥路，且与须臾哭别离。"]},{"t":"管大兄弓伯挽歌二首 其一","f":"古风","c":["薤上露，光油油，日出曈曈，其光易收，乐日之匿得久留。","将何奉，奉咿嚘。","室有妇，膝有儿。","儿为父，妇为师。","夔夔终日夕，鸡鸣晨起以奉之。","妇步亦步，妇趋亦趋，伛伛偻偻，为儿觅肥腴。","如何令死心怦摧，姝姝媚媚，眉不得开，将此悲君胡当哉。","日已匿，阴已霾，轶云霓，足徘徊，露晞朝阳乐无涯。"]},{"t":"管大兄弓伯挽歌二首 其二","f":"古风","c":["蒿里谁家地，不在蒸江上。","不在湘潭城，不在苍梧黄茅瘴。","祝融为盖，白石为舆，安安缓缓驾輀车。","挽人勿諠，听我唱言。","魂归湛湛之青天，形返茸茸之墓田。","鼓毋怒，笛毋悲，庸夫不骂鬼，世间何用庸夫为。","以尔笑骂代痛哭，鸺鹠乾鹊齐上屋。","主人弃屋返青山，庸夫他家觅酒肉。","我有酒，不酬黄泉将润庸夫口。","肥牛十脔醇醪三斗，辘辘轴轴狂鼓庸夫死奔走，黄泉之人应拍手。"]},{"t":"避暑王恺六山庄会夕雨放歌","f":"七言古诗","c":["杨梅塞前杨梅熟，草覆溪流绕南麓。","雷声昨夜破疏星，片片馀云留岳足。","云留云去争新晴，蕉叶回风绿倒倾。","吹灯相照两含情，良宵不负新凉生。","我不能饮君不歌，华月出云光奈何。","电漾金液雷颤牖，浮云上头悬北斗。","放棹唯寻杜景贤，倚藤长爱支离叟。","就君销夏借君闲，无归之客身阑珊。","稻脚将圆子鱼长，高枕无心谋往还。"]},{"t":"些翁补山堂诗和者数十人今春始枉寄次韵奉和并敩翁体","f":"古风","c":["当其为人不知虎，何妨疑虎能生羽。","罗刹刀兵诸天花，此土强名之为雨。","山非山，湖非湖，无弦之琴知音孤。","凭空结，架飞楼，琼岛八千仞，东海之西疑有无。","肃慎之矢其长咫，公孙见鸡有三耳。","清波不犯自垂纶，何但胸中五岳起。","东藏郓欢龟阴之田，西虞芮倒影晶天无表里。","有虞之媦吮毫腐，九疑云霾十疑补。","非公拄杖划破苍梧烟，下士痴将修眉黛茎数。","我不出门登公堂，公勿谓我精神荒。","别峰凝紫鸟道碧，从门入者徒徬徨。"]},{"t":"拟古诗十九首 其一","f":"五言古诗","c":["临歧送远道，春草生道旁。","春草生有时，远行去无方。","逝水无西归，游子怨流光。","高台多夕风，平原足晨霜。","去者日益永，留者情益警。","元云迷四郊，方望不得逞。","思君褰罗帏，灭烛无馀影。","弃置良独难，没生誓幽秉。"]},{"t":"拟古诗十九首 其二","f":"五言古诗","c":["东园桃李花，南国蛾眉女。","灼灼相矜悦，遥遥动心语。","清歌不再发，舞袖无双举。","昔为弦上思，今为梦中聚。","芳菲非我春，为欢复何许。"]},{"t":"拟古诗十九首 其三","f":"五言古诗","c":["灼灼三春风，萦萦杨柳色。","年少去我徂，芳菲不再得。","迟我心所钦，良书寄怀忆。","迢递千里间，神皋有仙宅。","朱凤遗清音，青天回羽翼。","玉轸动鸣琴，素月辉相即。","髣髴垂丹梯，云签降消息。","愿言欣相从，含情无终极。"]},{"t":"拟古诗十九首 其四","f":"五言古诗","c":["殷勤重殷勤，置酒遥相期。","华烛摇虚慵，流光动哀丝。","中觞促密坐，欲言还自疑。","怀情不忍戢，劝勉当及玆。","为欢托荣观，结爱在新知。","飞蓬非久要，胡为守枯枝。","词终起相谢，微生命有涯。"]},{"t":"拟古诗十九首 其五","f":"五言古诗","c":["客从淇水来，导我游朝歌。","广陌聚高居，冠盖彯绮罗。","良夕奏哀弦，繁声惊素波。","师延亡千载，遗怨何其多。","黄鹄感其音，群飞以阿傩。","高楼离思女，长夜颦青蛾。","闻者无厌情，歌者益以和。","清琴有希音，吾心将如何。"]},{"t":"拟古诗十九首 其六","f":"五言律诗","c":["日南有归客，问讯珊瑚枝。","海水深不测，飘零无反时。","相见既无端，相忆无与知。","唯持憔悴心，毕命以为期。"]},{"t":"拟古诗十九首 其七","f":"五言古诗","c":["太阳敛西晖，纤月出云际。","夕风改晨色，群星相连缀。","征鸟怀故栖，遥天方远逝。","巢燕依梁宇，流萤漾池砌。","念我结发游，纳交相砥砺。","去者日以疏，遗我成孤赘。","宵露不及晨，馀霜无久丽。","自非金石心，谁能永匏系。"]},{"t":"拟古诗十九首 其八","f":"五言古诗","c":["梧桐生井干，桐叶落井中。","结缡事君子，飞蓬附秋风。","秋风有息时，飞蓬委荒阡。","间关逐君行，中道悲弃捐。","依君日苦短，别君日苦延。","伤哉惊飙集，吹此雨绝天。","日没群星出，长夜未有端。"]},{"t":"拟古诗十九首 其九","f":"五言律诗","c":["桂树萦晨霜，芳滋久不渝。","采之无所赠，不忍置路隅。","怀袖经岁年，中心良自殊。","殷勤自畴昔，谁为爱斯须。"]},{"t":"拟古诗十九首 其十","f":"五言古诗","c":["涤涤秋宇清，泫泫华露滋。","冉冉弦月微，杳杳双星期。","良辰既不屡，终夕亦有涯。","脉脉相视间，为欢还自疑。","未必经年中，绸缪无转移。"]},{"t":"拟古诗十九首 其十一","f":"五言古诗","c":["日落登崇冈，顾望青天高。","四维何茫茫，浮云但萧骚。","群动既非一，吾身若秋毫。","自非精诚彻，蠕动徒巳劳。","精魄无固存，奄忽成焄蒿。","及今百年内，何者终吾操。"]},{"t":"拟古诗十九首 其十二","f":"五言古诗","c":["所思不可见，所怨不可移。","忽如飘风集，贸贸何所之。","平生交与好，长逝相追随。","中野飞燐光，白日为之迷。","函意以永世，千载将谁知。"]},{"t":"拟古诗十九首 其十三","f":"五言古诗","c":["南山崔以嵬，上与浮云连。","俯视何浩浩，飞鸟翔其间。","延眺须臾中，心目凄以闲。","置身如流波，旦夕空百端。","焉能役心志，随物增忧烦。","畴昔遨大梁，结交多英贤。","千里不相弃，良书托归翰。","宝玦白玉光，系以双金环。","佩之四座惊，旁徨发长叹。","所叹非偶尔，白璧当自完。"]},{"t":"拟古诗十九首 其十四","f":"五言古诗","c":["阳春二三月，缘草被修路。","青林无鲜华，啼鴂亘晨暮。","凄彼泉下人，不知春风度。","驱驱无返辙，谁者为新故。","往古既复然，非我独忧惧。","天物各推迁，胡为滋惊怖。","虑苦不得甘，蚤计良巳误。","灭性以求真，浮光栖月露。","鼎鼎百年中，含情抱贞素。"]},{"t":"拟古诗十九首 其十五","f":"五言古诗","c":["古人不可期，今人当奈何。","对酒乍相忘，援琴发清歌。","适意方在兹，忧患徒相如。","愤世而忘己，吾生亦有涯。","商山采芝人，迹迩心自遐。"]},{"t":"拟古诗十九首 其十六","f":"五言古诗","c":["和月春巳徂，林鸟有馀声。","落英无返顾，流览怛中情。","宝刀垂鞶带，昔我何所营。","中宵不自戢，髣髴感精灵。","邂逅良人姿，执手相徂征。","心好自旖旎，随风飘长缨。","虽非思所臻，乍觏亦不惊。","愿言托白首，畴云中路倾。","绸缪不相释，屡顾念平生。","怀抱申此夕，感之双涕零。"]},{"t":"拟古诗十九首 其十七","f":"五言古诗","c":["白月流素天，微霜满空际。","开轩极远目，清霄何迢递。","仲秋元鸟归，季秋阳雁至。","染丝弄机杼，纵横成锦字。","上有永别离，下有金石誓。","不知将寄谁，绸缪结封识。","经年藏宝箧，置之不忍视。"]},{"t":"拟古诗十九首 其十八","f":"五言古诗","c":["昔我游日南，中道至合浦。","池水碧以寒，叆叇莫能睹。","得此径寸珠，云自鲛人所。","缄以金泥封，藉之龙文组。","中夜投君怀，当知寸心苦。"]},{"t":"拟古诗十九首 其十九","f":"五言古诗","c":["清风吹华镫，明星启东方。","起步中庭间，形影相旁徨。","夙昔志远游，迟暮迷津梁。","灭烛从假寐，欲罢固难忘。","浩叹以彻旦，不知泪沾裳。"]},{"t":"拟阮步兵咏怀二十四首 其一","f":"五言律诗","c":["出门何所适，极目延云容。","白月照广川，绿圳生清风。","飞鸟去天末，萧条无馀踪。","置意良独难，归来扣哀桐。"]},{"t":"拟阮步兵咏怀二十四首 其二","f":"五言古诗","c":["阿环握灵符，翩然降桂宫。","执戟侍清宴，佩玉相从容。","嘉会虽迢递，畜意无终穷。","二八妙娥㜲，筝璈荡虚空。","穆耳注心感，歘焉返阆风。","怀情不再觌，徒乃见狡童。","万年独离伤，精爽谁为通。"]},{"t":"拟阮步兵咏怀二十四首 其三","f":"五言古诗","c":["凉风西南来，吹此浮云兴。","连蜷相异态，奄忽如有凭。","日暮灵雨飞，消释如春冰。","步上商南山，挥手谢太清。","肝胆一胡越，百年非我生。","明灭随须臾，吾心固不能。"]},{"t":"拟阮步兵咏怀二十四首 其四","f":"五言古诗","c":["石陨睢阳都，夙昔为明星。","顷刻不自信，哀乐异其情。","韶风荣腐草，春霰摧初英。","去日亦已往，来日自多惊。","唯有王子乔，淩空吹玉笙。"]},{"t":"拟阮步兵咏怀二十四首 其五","f":"五言古诗","c":["结士苦不早，黄金何足言。","远闻悲歌士，屠狗近居燕。","揽衣欲就之，时命忽我迁。","蟠泥中道困，蛟龙无羽翰。","归休南山下，日月如流丸。","弃置平生心，荒忽如秋烟。"]},{"t":"拟阮步兵咏怀二十四首 其六","f":"五言古诗","c":["鸾鸟栖开明，玕琪映毛羽。","西日不匿晖，永夕炫金缕。","深心非世知，有时戴戈舞。","览德无良期，裴回生愤怒。","慈俭以全身，高深定何补。"]},{"t":"拟阮步兵咏怀二十四首 其七","f":"五言古诗","c":["芳春去我远，九夏行将迁。","靡草阅炎日，鲜蔓无久延。","归禽避飘风，深林相哀喧。","披衣视河汉，恻怆悲高天。","当时非所谋，及今良固然。"]},{"t":"拟阮步兵咏怀二十四首 其八","f":"五言古诗","c":["白日閟寒云，辰夜复阴雨。","夕萤流湿光，因风歘相聚。","奔兽不违林，惊禽亦怀侣。","下士情不深，目迎心己许。","悲歌难自固，上蔡馀酸楚。","失弓原郢客，逐日非夸父。","要领诚不惜，孰为同草腐。"]},{"t":"拟阮步兵咏怀二十四首 其九","f":"五言古诗","c":["汎舟浮湄水，逶迤青枫林。","湄水去不息，言下湘江浔。","停楫长太息，明月照我衿。","天宇羃广野，平原气萧森。","夕鸟瞑不飞，游鱼喧籁阴。","寸心不自得，何况飞与沈。"]},{"t":"拟阮步兵咏怀二十四首 其十","f":"五言古诗","c":["邺台閟新宫，高阳矜广宅。","游冶相纷奔，追欢倒屐舄。","黄雀在枌榆，取之若芥珀。","华山有高士，烧金方结客。","舒卷无浅心，灵蜕托仙迹。"]},{"t":"拟阮步兵咏怀二十四首 其十一","f":"五言古诗","c":["燕台多高风，易水扬洪波。","白日照绮疏，冠盖相经过。","踔厉古今间，感慨何其多。","望诸无返驾，洹上计复讹。","黄金台己芜，北望空山阿。","宋子迹云远，谁为绍悲歌。"]},{"t":"拟阮步兵咏怀二十四首 其十二","f":"五言古诗","c":["蔓草萦咸阳，云是阿房宫。","雏凤复双飞，莫辨雌与雄。","山河既绸缪，宴处时从容。","挟弹鸣金錽，垂杨骄青骢。","意气生豪族，芳尘散春风。","努力拾新翘，无言恤飞蓬。","秉烛继白日，为欢无终穷。"]},{"t":"拟阮步兵咏怀二十四首 其十三","f":"五言古诗","c":["长夏生景风，飘然过我墟。","蓬居困杲日，赪影过桑榆。","延睇望广天，胡为自挛拘。","西台有馀哀，聊城无报书。","生我自有天，憔悴与之俱。"]},{"t":"拟阮步兵咏怀二十四首 其十四","f":"五言古诗","c":["白日回南辕，草木芸以黄。","时改心易惊，哀情随大荒。","远视无所怀，但念有悲凉。","西晖徐以下，微风过墟冈。","庭宇旷萧森，披帷延星光。"]},{"t":"拟阮步兵咏怀二十四首 其十五","f":"五言古诗","c":["早岁好词赋，文酒相追随。","引誉动当时，将为名在兹。","抚剑游广都，悲歌归山涯。","元冥共白日，何者不吾欺。","驱马上高冈，咫尺生崟欹。","乃知杨公叹，非缘道多歧。"]},{"t":"拟阮步兵咏怀二十四首 其十六","f":"五言古诗","c":["湘水千里来，东下巴邱湖。","迢递连广野，青山閟幽墟。","云气浮远白，西南接苍梧。","落日登迥冈，飞鸟去巳孤。","暝色没高树，墟烟下平芜。","俯仰求寸心，不知意所俱。","姣女多情向，烈士无旁趋。","皎日照此怀，行歌一欷歔。"]},{"t":"拟阮步兵咏怀二十四首 其十七","f":"五言古诗","c":["悠悠青天高，不知生所终。","巫咸巳上天，欲诉将奚从。","但见大壑间，日暮生清风。","惊鱼跳渌水，秋蛩吟兰丛。","怀我心所钦，邂逅相迎逢。"]},{"t":"拟阮步兵咏怀二十四首 其十八","f":"五言古诗","c":["浮云起东南，悠然骛西北。","驶影无淹留，凝望滋迷惑。","前者既萧散，后来空闵默。","岂为仰观者，伫迹从察识。","稚鸟空翔飞，冯风鼓羽翼。","达人知其微，驰驱无轨则。","蘋末生轻风，孤心自相得。"]},{"t":"拟阮步兵咏怀二十四首 其十九","f":"五言古诗","c":["念我心所欢，远在玉山岑。","戴胜冠崔嵬，文鸾奏知音。","妙药青麟脂，薰风生瑶琴。","日夕延伫之，绵邈心淫淫。","三五明月满，光晖发云林。","神爽一相接，携手连讴吟。","企望亦不遐，悲哉年岁侵。"]},{"t":"拟阮步兵咏怀二十四首 其二十","f":"五言古诗","c":["楚人得亡弓，塞叟有归驹。","乍尔亦为欢，达人哂其愚。","明月照形影，恻恻夫何如。","回风飏秋毫，宁转造化枢。","囧彼柔曼子，犹知泣前鱼。","元珠握重渊，金石终不渝。"]},{"t":"拟阮步兵咏怀二十四首 其二十一","f":"五言古诗","c":["心颜诚自我，云容悲素苍。","耿耿霜月霁，长啸惊八荒。","青天有鸣鸿，孤飞不成行。","闻其哀噭音，疑尔悲稻粱。","所志在鸴鸠，枋榆亦可翔。"]},{"t":"拟阮步兵咏怀二十四首 其二十二","f":"五言古诗","c":["支祁降横流，十日恣炎焚。","英灵相委顺，千载无秋春。","刀圭讵偶尔，灵液起沈伦。","凤笙非世响，十载将上宾。","自信匪无功，勤立丹台勋。"]},{"t":"拟阮步兵咏怀二十四首 其二十三","f":"五言古诗","c":["方壶与圆峤，相去无黍米。","星河流其间，日月荡其里。","孤游忘岁月，奇璨争纷诡。","调良驾河车，六龙就方轨。","补天西北倾，奠地东南委。","清虚非久居，沈沦安足纪。"]},{"t":"拟阮步兵咏怀二十四首 其二十四","f":"五言古诗","c":["夙昔惊我怀，离合遂无端。","结好在中涂，绸缪苦不安。","飙风吹落叶，夕阴凄以寒。","握手未及终，裴回歧路间。","骇兽啼我前，离怨无与殚。","焉得三青鸟，从之生羽翰。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其一 排子岭","f":"五言绝句","c":["稻亩绿茸茸，平田接回坞。","桥下流水声，龙湫昨夜雨。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二 狮子峰","f":"五言绝句","c":["飞鸟摇岭色，渐与峰顶齐。","凝眸绝涧影，巳转碧潭西。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其三 黑沙潭","f":"五言绝句","c":["苔冷千年绿，春寒一片云。","回襟避疏雨，人语不相闻。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其四 续梦庵","f":"五言绝句","c":["旧梦巳不续，无如新梦惊。","溪云沾竹尾，滴沥过三更。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其五 双髻峰","f":"五言绝句","c":["西峰亘铜梁，北岭矗荆紫。","百里见阴镫，遥知光发此。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其六 黄沙潭","f":"五言绝句","c":["落叶绝行踪，随意披疏筱。","龙气动乔木，空潭无猿鸟。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其七 溪波岩","f":"五言绝句","c":["棕笠溅飞珠，回头不知处。","徙倚望前山，斜阳转高树。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其八 妙高峰","f":"五言绝句","c":["阴光浮石壁，长如春水生。","僧归夕磬后，回首见西清。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其九 车辙亭","f":"五言绝句","c":["偶然成辙迹，古人意何取。","伫立无与言，前峰正疏雨。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十 方广路","f":"五言绝句","c":["未从方广游，知为方广路。","定有夕烟霏，天光露晴树。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十一 啸台","f":"五言绝句","c":["午日尚曈昽，紫光衬元叶。","暄气上台阴，香风吹冻蝶。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十二 补衲台","f":"五言绝句","c":["闻有补衲名，学之跏趺坐。","蒻叶摇森森，竹鼠穿裙过。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十三 洗衲池","f":"五言绝句","c":["瀑布良可观，临之喧不清。","水帘垂一尺，微送佩环声。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十四 青溪石门","f":"五言绝句","c":["欲作飞猱度，不畏苍苔深。","森森开一面，斜日照前林。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十五 西石门","f":"五言绝句","c":["循壁渡泉桥，知有幽人宅。","山气动□馡，香獐夜来迹。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十六 松纹石亭","f":"五言绝句","c":["僧归绕曲涧，回首望林端。","遥知爱啼鸟，也向树梢看。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十七 坞云庵","f":"五言绝句","c":["曲逐峡田上，遥期松径终。","凉风中岭合，西日一尖红。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十八 钓竹源","f":"五言绝句","c":["杉竹迷千嶂，豆苗萦一湾。","麇䴥不相避，肥草隐潺湲。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其十九 云台山","f":"五言绝句","c":["佛宇不可知，云留高树里。","日落钟磬声，随云度溪水。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十 西庄源","f":"五言绝句","c":["古树何年种，归禽来一双。","茅斋读易罢，摇影入閒窗。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十一 小祗园","f":"五言绝句","c":["宛转破千嶂，平畴起绿烟。","自然知兰若，不过鸟飞边。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十二 小云山","f":"五言绝句","c":["夕气澄若浓，星光敛清炯。","林外露悬灯，未知何峰顶。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十三 昭阳庵","f":"五言绝句","c":["归鸦度何所，夕照移西岑。","荫入蔚蓝色，萧萧松桧阴。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十四 馺阁岩","f":"五言绝句","c":["欲以贻来者，锡之馺阁名。","终古知不知，今兹自含情。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十五 桃坞","f":"五言绝句","c":["曳杖行何适，桃花一坞红。","回塘积落英，从君识东风。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十六 雪竹山","f":"五言绝句","c":["杨坟一竿竹，空外影千寻。","六月飞冰雪，埋心直到今。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十七 茱萸塘","f":"五言绝句","c":["绿苞绽绀珠，红泉酝香屑。","采采及清秋，汝南有真诀。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十八 败叶庐","f":"五言绝句","c":["败叶留不扫，鏦铮扣哀弦。","虫吟凄切外，秋色倍清喧。"]},{"t":"怀入山来所栖伏林谷三百里中小有丘壑辄畅然欣感各述以小诗得二十九首 其二十九 观生居","f":"五言绝句","c":["寒月出东岭，流光入浅廊。","万心函片晌，一缕未消香。"]},{"t":"昭山二首 其一","f":"五言绝句","c":["曲曲见昭山，孤青不相舍。","湘水送千帆，凝眸几人也。"]},{"t":"昭山二首 其二","f":"五言绝句","c":["终古石自碧，深春花欲红。","澄潭凝一碧，云末出双虹。"]},{"t":"避乱石鸡村同载谋小憩四首 其一","f":"五言绝句","c":["苍壁不受春，转入溪流曲。","桃花影外天，微波动新绿。"]},{"t":"避乱石鸡村同载谋小憩四首 其二","f":"五言绝句","c":["飞鸟随风叶，梨花漾碧晶。","溪山得圆净，鸡犬亦萧清。"]},{"t":"避乱石鸡村同载谋小憩四首 其三","f":"五言绝句","c":["不知身忽轻，巳度青茸表。","疏雨何妨飞，林端露清晓。"]},{"t":"避乱石鸡村同载谋小憩四首 其四","f":"五言绝句","c":["仇池九十泉，桃源千万树。","古人丧乱中，自选林泉住。"]},{"t":"过芋岩不值","f":"五言律诗","c":["隐几非畴昔，天游各徜徉。","古槐珠蕊熟，曲岸蓼红香。","晴稻收云白，秋瓜切粉黄。","呼炊忘主客，撰屦巳斜阳。"]},{"t":"深秋望欧子直","f":"五言律诗","c":["萧萧夕吹外，云敛一痕青。","杖履随天地，山川见典型。","借棋迟画纸，酿酒巳登瓶。","但觉闲情损，归舟忆洞庭。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其一","f":"五言律诗","c":["营筑非吾道，林塘适物清。","吹瓢疑稍释，逃影妄初成。","无闷炊烟损，多徼曙月晴。","暄风淩小雪，当砌炫冬荣。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其二","f":"五言律诗","c":["七尺一丝存，馀生半席温。","浮沤仍往迹，块土认谁恩。","飞鸟消云际，幽虫蛰草根。","小东皋畔客，今日暂招魂。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其三","f":"五言律诗","c":["一日一生留，无缘谢白头。","天情垂粥饭，家学志春秋。","月影虚窗满，云滋砌草柔。","濂溪香菡萏，孤棹试中流。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其四","f":"五言律诗","c":["耕钓传先志，人知德不堪。","钏声原宿业，崖蜜自先甘。","寓目团栾浅，初心冷暖谙。","鸿踪沙外雪，聊谢盖棺惭。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其五","f":"五言律诗","c":["病畏朔风寒，南窗背岭安。","林风迟九夏，日影梦三竿。","乞种谁家树，旋成几尺阑。","死生还似此，倍觉有心难。"]},{"t":"因林塘小曲筑草庵开南窗不知复几年晏坐漫成六首呈桃坞老人暨家兄石崖先生同作六首 其六","f":"五言律诗","c":["隐几愿经年，垂杨左肘穿。","虚空战雷雨，血骨袅霜烟。","萦蚓通幽迹，惊鱼遣熟眠。","天情随近远，何有息双肩。"]},{"t":"家兄观夫之抄槁云墨迹似先徵君垂示以诗哀定后敬和四韵","f":"五言律诗","c":["鼎鼎孤生在，迢迢百行非。","皋鱼身世恨，鸿雁一双违。","斗气埋长剑，霜风绽葛衣。","惊闻墨影似，还欲惜残晖。"]},{"t":"二中园纪事为懿庵作 其一","f":"五言律诗","c":["入阁几重重，双开曲径通。","穿风分柳径，随藓度兰风。","鱼服双绯盛，花阶九锡崇。","居然成绿野，何必蔡州功。"]},{"t":"二中园纪事为懿庵作 其二","f":"五言律诗","c":["万折历嵯峨，天输小邵窝。","书声花影月，曲尾柳莺歌。","看弈人无倦，临觞政不苛。","清泉四十八，何处着风波。"]},{"t":"即事 其一","f":"五言律诗","c":["暄气熏寒月，微霜不改晴。","光冲西极影，月转北街明。","川泽清难巳，龙蛇蛰不争。","乾坤馀一泪，长对暮烟横。"]},{"t":"即事 其二","f":"五言律诗","c":["仲冬微雨息，霜吹捲空晶。","深紫馀枫在，疏黄片柳轻。","馀年消永夜，寒月约孤清。","自问沧江侣，谁为共濯缨。"]},{"t":"晴步","f":"五言律诗","c":["清韶陶始曙，凉润即新林。","风定叶当影，云开岫出阴。","遥禽如往日，近蝶有营心。","四顾谁天损，行歌复自今。"]},{"t":"上湘旅兴 其一","f":"五言律诗","c":["寒山犹半绿，浅日动浮光。","习习江南暖，淫淫小雪长。","杖藜随鸟度，涉涧有花香。","不信间愁在，千峰一徜徉。"]},{"t":"上湘旅兴 其二","f":"五言律诗","c":["墟烟何处起，渡口己樵歌。","空外篙音发，睛滩柏叶过。","生平还草屦，世事尽藤蓑。","惭愧元真子，清时畏绿波。"]},{"t":"上湘旅兴 其三","f":"五言律诗","c":["一巘复千峰，参差万壑松。","夕烟飞不定，落叶转相逢。","古砦传银穴，仙坛记石封。","金丹及铁马，吾意定奚从。"]},{"t":"上湘旅兴 其四","f":"五言律诗","c":["柳阴谁竹外，几叶带疏黄。","浴鹜动金绮，夕阳生暗塘。","归人欢妇子，明发有风霜。","居者忘情甚，萧条客感长。"]},{"t":"上湘旅兴 其五","f":"五言律诗","c":["山城犹百里，战伐不相知。","禾黍经时毕，冠裳入望疑。","微霜开驿路，落日返樵吹。","回念巴邱北，银涛捲绣旗。"]},{"t":"舟中上巳同须竹","f":"五言律诗","c":["客思荡如何，心知令序过。","韶吹先闰□，花信绪风和。","瑶草从谁拾，落英念已多。","盈盈双白鸟，著意浴清波。"]},{"t":"伊山 其一","f":"五言律诗","c":["心识回峦外，沿溪曲径深。","云烟开绿亩，金碧动青林。","香篆迎风入，钟声过鸟寻。","萧清初觉好，风雨更幽岑。"]},{"t":"伊山 其二","f":"五言律诗","c":["读书云外迹，梵刹劫前宫。","蕴藉清歌日，萧条夕磬中。","古今藏客泪，勋业寄真空。","牛首虚天阙，何因卧懒融。"]},{"t":"衡山晓发 其一","f":"五言律诗","c":["击汰迟枫浦，归心就翠微。","江空双古岸，天小一双围。","岳气云侵县，墟烟月掩扉。","松杉回望里，一谷曙光飞。"]},{"t":"衡山晓发 其二","f":"五言律诗","c":["绿润不知冬，岳云第几峰。","身轻随白鸟，裾冷夹青松。","江近前时棹，碑留故国封。","渔樵知近远，目赏己从容。"]},{"t":"陈耳臣老矣新诗犹丽远寄题雪诸咏随意和之得四首 其一 初雪","f":"五言律诗","c":["居然穿雨际，的的炫轻盈。","高阁今相望，遥心一倍生。","元云光渐曙，浅水影微萦。","经岁含情待，天涯已赠琼。"]},{"t":"陈耳臣老矣新诗犹丽远寄题雪诸咏随意和之得四首 其二 映雪","f":"五言律诗","c":["息心寒夜永，无奈小窗何。","恻恻情还定，胧胧影未讹。","空涵西照合，月转北林多。","坠玉惊幽响，知谁度薜萝。"]},{"t":"陈耳臣老矣新诗犹丽远寄题雪诸咏随意和之得四首 其三 欲雪","f":"五言律诗","c":["稍稍墟烟度，归禽尚一双。","喧风柔落木，珠雨缓流淙。","夕气先孤幌，云阴上半窗。","县心清赏极，酒力未须降。"]},{"t":"陈耳臣老矣新诗犹丽远寄题雪诸咏随意和之得四首 其四 访雪","f":"五言律诗","c":["弥望盈清回，还疑溪外踪。","鸿飞昨日影，龙蛰几株松。","曲曲忘前径，山山遂一容。","扶筇谁早过，麇迹恰迎逢。"]},{"t":"东台山","f":"五言律诗","c":["百里初见山，西晖客望闲。","半峰明紫树，群岫倒苍湾。","仙馆箫声歇，渔舟隔浦还。","祝融知近远，清梦骛云间。"]},{"t":"草堂成","f":"五言律诗","c":["归舟湘水北，伐木逮秋清。","鹤馆松云剪，萍踪雪径成。","南窗仍夕㬉，东岭迓春晴。","萧瑟乾坤里，蓬茅亦太荣。"]},{"t":"早起草堂寓目篱间牵牛花追忆懿庵","f":"五言律诗","c":["秋色生空外，微晴始素晖。","篱花深碧紫，风蔓小霏微。","酒坐怀迎目，林轩怅启扉。","故心犹宛尔，何事岁华违。"]},{"t":"新秋望章载谋二首 其一","f":"五言律诗","c":["湘山犹曲曲，畴昔故天涯。","偶合添离恨，轻分有后期。","镫残知弈误，月上尽诗迟。","芳草王孙在，闲愁付杖藜。"]},{"t":"新秋望章载谋二首 其二","f":"五言律诗","c":["干戈方万里，摇落又三秋。","霜鬓久无据，云踪幸缓愁。","周秦焚后字，荆楚赋中楼。","郑重清波意，君无忘野谋。"]},{"t":"寄徐蔚子","f":"五言律诗","c":["黄鹄一癯仙，重逢腹巳便。","檄从邛部草，诗授郑公笺。","柯雨先徵梦，樵风恰满船。","褚公池上月，珍重到秋圆。"]},{"t":"送载谋归吴淞二首 其一","f":"五言律诗","c":["相逢及送别，都在落花时。","霜雪添双鬓，兵戈共一枝。","江湖空在望，天地尽堪疑。","顾陆烦凭吊，吾生未有期。"]},{"t":"送载谋归吴淞二首 其二","f":"五言律诗","c":["马当湖水北，南望杳潇湘。","陆海英雄踬，船山烟草荒。","客台留蠹简，谒者恋幽芳。","片石延陵字，他年待报章。"]},{"t":"闻圣功讣遽赋","f":"五言律诗","c":["闲愁生死外，回首故人无。","南望墟烟迥，西飞片鸟孤。","藤花开独坐，萝月照霜须。","泉下□□泪，艰难付钓徒。"]},{"t":"咏菊答须竹","f":"五言古诗","c":["选芳宜隐秀，经岁得秋情。","苗浅春滋弱，心微露贮轻。","啼莺无醒梦，飞絮谢思萦。","雨浃浮光上，吹暄逸态呈。","蠹憎痕屡剔，丝繫玉防倾。","爱惜消长日，从容养静萌。","荷风熏晚绿，蕉雾洒孤荣。","叶叶容迟上，亭亭有独擎。","艰难出畏景，珍重享西清。","紫葆光初透，珠胎润巳滢。","竹枝留上番，梅影剪疏横。","专气邀金液，丰仁长玉婴。","星榆方历历，云朵遂盈盈。","土德先推王，冰心亦保贞。","有时浴紫水，终不炫丹猩。","香外幽难似，薰馀静不撄。","肃然登鼻观，嗒尔偃心旌。","龙腊痴谁妒，薝葡逸未平。","霄空霜一色，天迥月三更。","倦赏愁寒夕，邀欢暂晚晴。","袂辞歧路把，目厌满堂成。","桂酿聊孤酌，莼丝小佐羹。","催开辞羯鼓，过访待缑笙。","巳事开三径，端居爱九名。","同床犹各梦，顾影易魂惊。","身后从冰雪，魂归返日精。","摧芳宁问落，涤月不辞烹。","君意如相念，殷勤访夕英。"]},{"t":"青草湖风泊同须竹与黄生看远汀落雁","f":"五言古诗","c":["荻芽沉绿影，汀际合晶光。","摇识归鸿集，从知梦泽长。","云移千点曙，风转一行将。","凝立迷烟树，轻迁动夕阳。","参差香尾乱，珍重羽衣凉。","陈列龙沙白，书成太古苍。","修眉涵镜曲，仙桂缀蟾光。","沙起帘钩荡，洲平瑟柱张。","涛惊聊静婉，野旷恣疏狂。","酣寝云田腻，栖心蕙圃香。","气矜三楚国，神带九秋霜。","整翮聊烟水，回翔岂稻粱。","浣纱人伫久，垂钓客情忘。","悽怨依筠泪，闲愁托杜芳。","经寒知柳色，访旧忆莲房。","北望关云紫，西清落照黄。","息机非倦止，清警正遥望。","平展纹波縠，轻浮玉照肪。","遥天开画苑，活谱写潇湘。"]},{"t":"同唐须竹游馺阁岩","f":"七言律诗","c":["昨日初收梅雨天，青空四幕碧光圆。","微风引袂分溪草，断嶂当眉露岳莲。","片石偶然留太古，同心无待问他年。","斜晖已长青松影，尚惜苔茸映绿烟。"]},{"t":"昭阳庵同须竹夜话云乘木叶秋波探五老之胜因便送之","f":"七言律诗","c":["尽觉当年不易谈，披云蹑石意犹贪。","袖图有迹传河画，血字无心锢井函。","白日只今原不损，青山向后定谁堪。","知君欲访匡庐瀑，摘去莲花池上参。"]},{"t":"不揆五十齿满懿庵见过留同芋岩小酌","f":"七言律诗","c":["枫阴荻岸晚烟开，鹤膝逡巡践碧苔。","隔岁相看颜似旧，衰年无据漏仍催。","清宵疏雨喧梧叶，草阁归云腻竹胎。","薄遣新欢消夙昔，临觞聊罢筑声哀。"]},{"t":"偶望","f":"七言律诗","c":["平田无那素光何，稻叶娟娟浸碧波。","白鸟试飞疑远浦，元云微断影高柯。","墟烟小困双湾树，砌叶全低一径莎。","不碍小窗消午睡，炉烟孤袅绪风和。"]},{"t":"极丸老人书所示刘安礼诗垂寄情见乎词愚一往呐吃无以奉答聊次其韵述怀","f":"七言律诗","c":["洪炉滴水试烹煎，穷措生涯有火传。","哀雁频分弦上怨，冻蜂长惜纸中天。","知恩不浅难忘此，别调相看更冁然。","旧识五湖霜月好，寒梅春在野塘边。"]},{"t":"宿雪竹山同茹蘖大师夜话","f":"七言律诗","c":["不知情在与无情，丈室挑灯魄自惊。","海溅云飞千嶂断，烟笼雪压一枝轻。","破船载月浮寒水，别路寻芳驻晚晴。","自擭杨坟茎草绿，春归闲唱踏莎行。"]},{"t":"刘庶仙五十初度即席同唐须竹 其一","f":"七言律诗","c":["未解平生因底事，华筵诗思不相通。","逢君县弧聊莞笑，垂老临觞偶自容。","竹塾午窗双总丱，梅花小阁一春风。","童心几皱恒河水，何必襄城问小童。"]},{"t":"刘庶仙五十初度即席同唐须竹 其二","f":"七言律诗","c":["半语逢人吞不得，于君烧烛耐春寒。","年华毂运有如此，谱样翻新孰与看。","但祝羲和留万转，长披黄袄到三竿。","华山呼取坠驴客，共说当年行路难。"]},{"t":"闻极丸翁凶问不禁狂哭痛定辄吟二章 其一","f":"七言律诗","c":["长夜悠悠二十年，流萤死焰烛高天。","春浮梦里迷归鹤，败叶云中哭杜鹃。","一线不留夕照影，孤虹应绕点苍烟。","何人抱器归张楚，馀有南华内七篇。"]},{"t":"闻极丸翁凶问不禁狂哭痛定辄吟二章 其二","f":"七言律诗","c":["三年怀袖尺书深，文水东流隔楚浔。","半岭斜阳双雪鬓，五湖烟水一霜林。","远游留作他生赋，土室聊安后死心。","恰恐相逢难下口，灵旗不杳寄空音。"]},{"t":"冬夕 其一","f":"七言律诗","c":["夕风楮叶有清喧，片紫西收碧未圆。","河汉依微倾北户，流霜容与润高天。","寥寥空界魂孤往，鼎鼎长宵梦小年。","欲与禁寒邀白鹤，齐州不耐暝横烟。"]},{"t":"冬夕 其二","f":"七言律诗","c":["天物何归剩碧虚，霜飙难挽日南车。","哀弦短剑留魂梦，雪鬓雾花空赘馀。","蚕妾报收双瓮酒，故人诺借满床书。","不知哀乐将谁得，恻恻寒心逼岁除。"]},{"t":"咏雪 其一","f":"七言律诗","c":["素绡幂岫浅黄通，倒影青冥一片浓。","雁背皴含天阙景，鱼鳞云烈晚檐风。","乾坤回合摇山泽，形魄孤清接混濛。","回首少年心绪回，冲寒狂折野梅红。"]},{"t":"咏雪 其二","f":"七言律诗","c":["霰外闲飞几片轻，回瞻平甸巳盈盈。","梅趺出色翻红栗，草甲栖心映绿晶。","云幕空轮千影转，风回池縠万双迎。","南塘曲岸谁相待，不惜明珠百斛倾。"]},{"t":"咏雪 其三","f":"七言律诗","c":["皑光晨射凝脂肥，海日轮孤腻不飞。","红药隐尖疑月冷，梨花摇梦想春晖。","池云压顶团鱼阵，松粉铺翎散鹤衣。","遥想玉峰辰似此，清寒应悔学仙飞。"]},{"t":"咏雪 其四","f":"七言律诗","c":["清空无际奈寒何，万岫参差捲白波。","人在冰轮迷海岸，天回平野倒云窝。","松风吹咽笙三叠，槠叶微留碧半柯。","不信人间有春日，桃花红雨点青莎。"]},{"t":"送蒙圣功暂还故山","f":"七言律诗","c":["秋风淫淫吹我衣，送君言归君欲归。","不知天地消偪侧，已觉江山忘是非。","疏星照水方昨夜，凉日当襟返翠微。","青山料理勿取次，留之待我慰调饥。"]},{"t":"残雪 其一","f":"七言律诗","c":["寒心肃肃拥孤清，断岸无心弄晚晴。","旧恨半消随去雁，新欢难待到流莺。","莎丛绿浅愁轻护，藓砌痕欹感易倾。","夙昔南枝曾有约，不贪春早逐初英。"]},{"t":"残雪 其二","f":"七言律诗","c":["珍重凋零劫后身，人间还遇可怜春。","和霜和月犹前日，争柳争花非此辰。","睥睨青天悲寂历，淹留丹巘赏嶙峋。","双飞燕子来何暮，不见琼田万顷新。"]},{"t":"残雪 其三","f":"七言律诗","c":["苍烟黄日久迷离，犹有墙东片月窥。","身外江山还似旧，梦中蜂蝶尽相疑。","东流彻夜银涛急，平甸矜春碧草欺。","不识瑞香花落后，几人还赋玉楼诗。"]},{"t":"残雪 其四","f":"七言律诗","c":["回塘曲径偶相依，不拟春归尚未归。","向后生缘随旦暮，当时心绪在霏微。","珠胎含泪禁疏雨，玉骨凝寒傲夕晖。","子夜轻冰聊邂逅，素心元不藉霜肥。"]},{"t":"长沙旅兴","f":"七言律诗","c":["江上红芽始试春，乳莺调语正迎人。","人閒韶日还相识，花下喧风已试新。","鹤杖恰逢苔径软，渔舟初绕碧波匀。","乘乘生事馀年在，随处桃花可问津。"]},{"t":"郡归书怀寄懿庵","f":"七言律诗","c":["雨滞花残不解飞，此身无主更无依。","乾坤何梦到清昼，生死难忘只翠微。","捲幕棋终归燕缓，敲尊歌阕荐鱼肥。","如君贫病真天上，莫惜清秋共钓矶。"]},{"t":"出郭赴李缓山之约桓伊山下遇雨","f":"七言律诗","c":["葛衣疏透雨珠閒，习习轻风宿暑阑。","白练半飞分木末，丹虹双绾擭云关。","笛声恰在桓伊步，饭颗初逢杜甫山。","珍重碧烟开玉镜，明宵何夕照双颜。"]},{"t":"萍乡中秋同圣功对月","f":"七言律诗","c":["白头还作他乡客，不负青天只月明。","自笑渔樵非泛宅，聊听鸿雁有新声。","晶瓶浸魄一双影，玉镜当心无限情。","莫为银蟾增怅恨，孤清直上即瑶京。"]},{"t":"春夕同章载谋看月","f":"七言律诗","c":["草堂新筑延新月，夕望春烟散夕清。","天地空轮原自昔，莺花流目不须惊。","东风摇柳拖柔影，绿晕莎肥炫露明。","莫拟华亭归鹤怨，湘山布谷未催耕。"]},{"t":"先秋一日作","f":"七言律诗","c":["西峰半影逼天青，闪闪斜阳紫焰明。","木末一丝云影渡，稻畦千绿水痕平。","麟洲梦觉馀香雪，鹤发身轻忆凤笙。","菡萏梧桐双在眼，他时摇落不须惊。"]},{"t":"重登回雁峰","f":"七言律诗","c":["碧树江烟小散愁，青鞋雪鬓又重游。","朱甍如梦迷双岸，绿草当春覆一邱。","纵酒华年凌石级，题诗夕雨认高楼。","渔舟战鼓皆今日，惭愧乾坤一影浮。"]},{"t":"遣怀","f":"七言律诗","c":["求仙无诀问蓬壸，缥渺神山一片孤。","溪水冰融随岸阔，天风霜起任桑枯。","田畴死记庐龙塞，司马生惭瑞兽符。","为问今宵寒夜月，照来还似旧时无。"]},{"t":"乾坤极目不消愁生事峥嵘祗敝裘渔艇可容人钓雪故乡还似客登楼探梅的皪丹砂蒂问月殷勤白玉钩尽有风光相假借无妨孤棹试中流 其一","f":"七言律诗","c":["青箬笠还在短墙，渔汀樵径尽披霜。","明年春在柳仍絮，前夜雪深梅自香。","天地龙蛇消一泪，河山乌鹊且孤翔。","情知华顶酣眠客，蜕骨难留笑汴梁。"]},{"t":"乾坤极目不消愁生事峥嵘祗敝裘渔艇可容人钓雪故乡还似客登楼探梅的皪丹砂蒂问月殷勤白玉钩尽有风光相假借无妨孤棹试中流 其二","f":"七言律诗","c":["人间口耳总无权，对影忘言且问天。","刘宋科名原荏苒，苏张车马自喧阗。","水沈香篆青烟细，海雾空轮赤日悬。","匣有宝刀随老病，无劳堇土淬龙渊。"]},{"t":"桐城余兼尊昔为青原侍者归素以来崎岖岭外相值见访为录前寄极丸老人诗仍次原韵赠之","f":"七言律诗","c":["沙上鸿踪昔岁心，堞楼鹤语旧时林。","已知罢钓能忘饵，何必登床更碎琴。","月影偶留传雁字，秋声不断有蝉吟。","閒愁杜口从君语，为受青原记莂深。"]},{"t":"小楼雨枕 其一","f":"七言律诗","c":["江城二月催寒雨，山客三更萝岭云。","青镜分明知鹤发，宝刀畴昔掩龙文。","援毫犹记趋南史，誓墓还谁起右军。","飞鸟云边随去住，清猿无事忆离群。"]},{"t":"小楼雨枕 其二","f":"七言律诗","c":["长镵斸术自生涯，短棹衡萍有独知。","偶测天心容杖屦，不从人事整须眉。","孤情琴外传昭氏，病眼花前待子规。","閒坐小楼清澈极，垣衣绿润带烟垂。"]},{"t":"小楼雨枕 其三","f":"七言律诗","c":["小圃桃花发几株，暂时潇洒且江湖。","柳风乍得吹乌帽，燕垒莫惊长绿芜。","符玺可容徐广泪，山河难授马融图。","千秋历历凭青史，不信兵戈有腐儒。"]},{"t":"小楼雨枕 其四","f":"七言律诗","c":["客窗倦雨晓朦胧，乍有晨光半纸红。","江岸夜喧春水长，沙汀波漾燕泥融。","乾坤即事容心广，老病随缘自德充。","莫问渔津知处否，绿杨绕屋已阴浓。"]},{"t":"春山漫兴七首 其一","f":"七言律诗","c":["青山一曲古今谁，曾向藤萝挂接䍦。","古树几逢新藓长，落花聊遣晓莺知。","乾坤旧日容双鬓，战伐随时老一枝。","拟上悬崖寻片石，苔函无字禹功碑。"]},{"t":"春山漫兴七首 其二","f":"七言律诗","c":["碧磴朱樱始试花，定知红药孕丹芽。","晶含斜日摇馀雪，縠长轻风皱浅沙。","游屐未抛资药力，渔蓑欲捲过霜华。","堂堂永昼相容得，卧看窗西映绮霞。"]},{"t":"春山漫兴七首 其三","f":"七言律诗","c":["雨敛平田一鹭轻，西峰新展半围晴。","叶光浮上通云绿，天影低沈透水清。","柔草待收园客茧，泠风欲和子乔笙。","百年俄顷春情极，未羡商山摘紫英。"]},{"t":"春山漫兴七首 其四","f":"七言律诗","c":["东海无能钓玉璜，岳阴从昔咀金姜。","刀圭鼎鼎千春臼，蓑笠悠悠一雨航。","棋劫屡翻怜日永，琴心自寡到春忘。","东方笑尔诙谐甚，滥借金门作隐乡。"]},{"t":"春山漫兴七首 其五","f":"七言律诗","c":["丹霞白雨夹分霄，浴鹭栖鸦各自饶。","夕爽清吹生水影，晴光片碧动山椒。","青鞋蹑迹违珠露，紫笋依痕剥玉苗。","假借春光安病客，天年恰恰在今朝。"]},{"t":"春山漫兴七首 其六","f":"七言律诗","c":["南国春从积雨过，西清云柰夕先何。","褰帷阴壁生青藓，倚杖空阶土绿莎。","肺病久拚临下湿，心期不但畏风波。","晴丝曙月容他日，几厌落英覆碧窝。"]},{"t":"春山漫兴七首 其七","f":"七言律诗","c":["馀春春闰太从容，即次莺花老渐慵。","送夕柳边斜照浅，留寒雨外湿云重。","烹龟自惜千年表，放鹤先栽九里松。","人事天情宜痼疾，草堂曲曲暮烟封。"]},{"t":"同须竹送芋岩归窆竟心艇溯湘转郡城有作二首 其一","f":"七言律诗","c":["谁将今古作浮烟，人各为心亦自怜。","饮泣当年闻国变，埋心遥夜但天全。","青编无字酬双泪，赤县何时慰九泉。","千计不如归尺土，飘零人在钓鱼船。"]},{"t":"同须竹送芋岩归窆竟心艇溯湘转郡城有作二首 其二","f":"七言律诗","c":["断云影里溯湘隈，回首荒阡半亩才。","纵使君还生几岁，可容春去有重来。","寒灰堕地皆千载，老病逢人但一哀。","不是躬园相识久，孤山错拟万株梅。"]},{"t":"咏木鱼二首 其一","f":"七言律诗","c":["绀宇虚堂敞肃阴，莲趺直下启孤音。","霏微乐句香烟合，萧飒清喧坠叶侵。","梦觉乍如星漏永，帘垂閒遣梵筵深。","初机涂毒难酬得，定借惊鱼警夙心。"]},{"t":"咏木鱼二首 其二","f":"七言律诗","c":["崔嵬忘情受众吹，息机何用作鳞而。","敲空别證生公义，弹指还拈宝月诗。","驯鸽依檐春雨静，蒲牢息杵晓空知。","新翻罢钓离钩句，从遣楗槌客尽疑。"]},{"t":"蚤春 其一","f":"七言绝句","c":["侧砌新苔透暖融，回波摇影碧痕通。","东风向晚吹疏雨，却送归云上浅红。"]},{"t":"蚤春 其二","f":"七言绝句","c":["小窗春浅不中春，径次啼莺煞恼人。","忘尽故心消不得，夕烟约莫柳条新。"]},{"t":"得须竹鄂渚信知李雨苍长逝遥望鱼山哭之五首 其一","f":"七言绝句","c":["孤雁哀吟带泪飞，南询雁岫钓鱼矶。","寻常雁塔称兄弟，鱼稻汀洲各捒肥。"]},{"t":"得须竹鄂渚信知李雨苍长逝遥望鱼山哭之五首 其二","f":"七言绝句","c":["一期生死有千秋，欲语逢人剪舌休。","刚遣西风吹片叶，黑云栖断洞庭舟。"]},{"t":"得须竹鄂渚信知李雨苍长逝遥望鱼山哭之五首 其三","f":"七言绝句","c":["青原罢棹石门寒，柳岸霜风月巳残。","欲转金轮须换面，红垆别铸紫金丹。"]},{"t":"得须竹鄂渚信知李雨苍长逝遥望鱼山哭之五首 其四","f":"七言绝句","c":["赤壁雄风百战酣，新安碧血洒江南。","大观绰板先君歇，凄绝吴江老蘖庵。"]},{"t":"得须竹鄂渚信知李雨苍长逝遥望鱼山哭之五首 其五","f":"七言绝句","c":["白杨衰草楚云天，孺子生刍奠暝烟。","忍泪欲弹须剪烛，霜风偏缓上滩船。"]},{"t":"新秋同唐古遗须竹游钟武故城归坐小轩夜语四首 其一","f":"七言绝句","c":["岳阴万片惹云肥，暑气犹留凝不飞。","野径偶然成远望，江湖何地卜渔矶。"]},{"t":"新秋同唐古遗须竹游钟武故城归坐小轩夜语四首 其二","f":"七言绝句","c":["荆榛苍浅古城秋，脉脉蒸江碧玉钩。","野旷天低飞鸟度，不知何处吊孙刘。"]},{"t":"新秋同唐古遗须竹游钟武故城归坐小轩夜语四首 其三","f":"七言绝句","c":["野人爱菊亦偶尔，种菊满阑秋已清。","但为爱君兄弟好，欹眠闲看绿光晴。"]},{"t":"新秋同唐古遗须竹游钟武故城归坐小轩夜语四首 其四","f":"七言绝句","c":["閒堂剪烛夜如何，银汉疏风古树多。","便把一竿随尔住，江门原有旧藤蓑。"]},{"t":"水口道中","f":"七言绝句","c":["丛竹低垂过雪斜，森寒绿气透青霞。","乳莺啼处春无几，才见樱桃一树花。"]},{"t":"走笔赠刘生思肯三首 其一","f":"七言绝句","c":["故园枝叶记君家，兄弟风流竞笔花。","汎宅五湖君自远，相逢犹幸在长沙。"]},{"t":"走笔赠刘生思肯三首 其二","f":"七言绝句","c":["水绿洲前鱼艇多，也来相伴晒渔蓑。","逢君剪烛当深夜，奈此干戈满地何。"]},{"t":"走笔赠刘生思肯三首 其三","f":"七言绝句","c":["老觉形容渐不真，镜中身似梦中身。","凭君写取千茎雪，犹是先朝未死人。"]},{"t":"题林良枯木寒鸦图图有李宾之题句四首 其一","f":"七言绝句","c":["未辨斜阳与暮烟，枝枝不堕早春前。","此中无放莺啼处，留待桃花二月天。"]},{"t":"题林良枯木寒鸦图图有李宾之题句四首 其二","f":"七言绝句","c":["便得春风也是枯，藤萝不挂尽萧疏。","遥知练鹊过新绿，只似河阳掷果图。"]},{"t":"题林良枯木寒鸦图图有李宾之题句四首 其三","f":"七言绝句","c":["内苑春风万树皆，文鹓掠彩艳心谐。","寒山古木啼清怨，只有梅斋与木斋。"]},{"t":"题林良枯木寒鸦图图有李宾之题句四首 其四","f":"七言绝句","c":["三十年来认得真，吉凶无据自无情。","鹊声纵好非归计，塞耳春风第一声。"]},{"t":"戏作七夕词三首 其一","f":"七言绝句","c":["甲子须臾一局棋，人间荏苒岁华迟。","经年莫为添惆怅，离别曾无片晌时。"]},{"t":"戏作七夕词三首 其二","f":"七言绝句","c":["晶轮不惹少商风，银汉无波一派通。","博望仙槎容易度，何须乌鹊掠清空。"]},{"t":"戏作七夕词三首 其三","f":"七言绝句","c":["织锦无成上帝嗔，憨慵长夜望河津。","何从更得蛛丝里，剩巧年年乞与人。"]},{"t":"梅花 其一","f":"七言绝句","c":["墟里寒烟罩断桥，年来春色最萧条。","船山半曲清溪里，霜日黄曛一树遥。"]},{"t":"梅花 其二","f":"七言绝句","c":["不知浅素更轻红，遥望长疑烟霭中。","除取梅花心自省，看花人隔小桥东。"]},{"t":"梅花 其三","f":"七言绝句","c":["老眼看花似隔纱，临风偶爱一枝斜。","香生微晕初轮月，紫透轻魂破体砂。"]},{"t":"梅花 其四","f":"七言绝句","c":["开从小雪入新年，雪妒霜侵不损妍。","珍重深寒禁冻蝶，低飞不过浅阑边。"]},{"t":"石流篇","f":"古风","c":["石上流水，渐彼蒲英。","涤根孤弱，植芳不倾。","抚我平昔，居然既往。","揽景无及，何用追赏。","水无旋流，卉木有方。","冬春屡易，天故不常。","一善可师，万端方迷。","授我坎坷，天故不齐。","浩浩方隅，茫茫圆轨。","有命艰贞，繄惟今始。","愠不可长，逸不可终。","含默难言，孤置我躬。","乌元鹤白，其辨易知。","分芒析微，何者忌疑。"]},{"t":"雉子游原泽篇","f":"五言古诗","c":["雉子游原泽，芒芒非故林。","寒秋草叶短，离离露华襟。","念昔志节士，抱道阅飞沈。","龙争而蠖屈，华屋若邱岑。","辗转万变内，崎岖北与南。","若辱全大白，蛟日破重阴。","寤寐岂不思，力弱无能任。","申旦劳太息，悠悠但长吟。"]},{"t":"门有车马客","f":"五言古诗","c":["林径晴风生，鸟雀喧夕树。","策马何方来，遥遥驻光度。","依依相慰深，转转将情愫。","繇言既不轻，珍重托微谕。","仰睇青云飞，光采殊新故。","各有怀心端，孰为目击遇。","耿耿非自韬，殷勤慎维擭。"]},{"t":"夜坐吟","f":"古风","c":["长莫长，冬夜寒，明霜流空天宇宽。","朱镫明，思未阑，昔日之日未足叹，今日之日百忧攒。","古人不可问，流俗空漫漫，吾何归，归何叹。","明星烂，晨鸡喧，抱孤心，临万端。"]},{"t":"豫章行","f":"五言古诗","c":["遵涂出郭门，待远有来期。","新欢寡所谐，旧好良多违。","分手亦己薄，弹冠安足希。","洪流从问津，危岑将共之。","商山非孤云，海滨有双仪。","夔旷诚不作，吾生将见欺。"]},{"t":"顺东西门行","f":"古风","c":["良夜徂，皑光盈，东方历历白日生。","酌醇酒，吹华笙，阅世迢迢心不惊。","发清讴，荡閒情，九州万年谁相撄。","乘逍遥，归太宁，驰骋无羁驱空□。"]},{"t":"猛虎行","f":"古风","c":["涂长不息空舍亭，道迷不随飞蓬征。","飞蓬无去心，空亭多夕惊。","寸心有端绪，歧路劳屏营。","衔忧非死亡，膺福非华荣。","危涂厉修筛，游衍悲俜零。"]},{"t":"短歌行","f":"古风","c":["临觞不辞，当歌不悲。","明月迟空，天汉离离。","南有玉衡，北有营室。","明明两间，达者自逸。","鸿雁惊霜，飞必有乡。","鴳雀栖迟，东西回翔。","登山善疑，临水善忆。","古人有心，千秋不测。","东望碣石，大海环之。","横波施楫，谁能代持。","陈馀绝交，冯衍悲老。","佩玦千金，轻丧其宝。","剖臆出心，与天而游。","回风在御，何用繁忧。"]},{"t":"箜篌引 其二","f":"古风","c":["河水流，蛟龙游，我闻昔夹神禹舟。","斥以蝘蜓爪角弭，后启云维神禹子。","驾之骖驔渡河水，非不欲公效其美。","公非夏后与子孙，胡为与之争吸吞。","天风有静波有驯，公虽欲渡姑逡巡。"]},{"t":"寄和些翁补山堂诗己就闻翁返石门复次元韵寄意","f":"古风","c":["无字之碑谁帝虎，无弦之琴谁宫羽。","角尖不挂羚羊痕，随意天花散春雨。","我公昔浮玉沙湖，湖上突出孤山孤。","补山未了公南返，螺髻修眉半有无。","下士之见不越咫，谓公勤勤补山耳。","支祈平吞江南之云江北梦，息壤欲堙何处起。","公笑捲山山为藏，青苍缩入柳杯里。","折脚铛中冰不腐，煮烂须弥将芥补。","湖南空有青莲七十二万茎，总不入公补处数。","无土不现补山堂，峥嵘日月开幽荒。","飞来之峰弹指已过洞庭水，北山愚公嗟徬徨。"]},{"t":"粤奴初识雪歌","f":"七言古诗","c":["剪发粤雏年十四，闻人说有霜雪字。","正月梅残度岭来，桃花郴水春流腻。","经年绝望望南天，落叶黄云栖瞑烟。","飘空冉冉光摇目，疑絮疑花两不然。","心知是雪情难决，借问方知寒雨结。","此生今日乍相逢，掬玉寻香向谁说。","可怜觌面未相亲，故是阳台梦里云。","垂杨风细梧桐月，总道龟毛重九斤。"]},{"t":"孤雁行和李雨苍","f":"七言古诗","c":["当年回雁峰头住，雁影云开天际路。","夫君缥渺雁峰心，遥寄湖南烟雨渡。","谁知白雁杳寒沙，断使青峰遮日暮。","日暮云迷雁阵哀，逢君千里雁书来。","欲分宝瑟银筝怨，似向沙明水碧回。","一水盈盈乌石戍，千秋渺渺楚云台。","楚云台高芳草齐，湘干北望鹧鸪啼。","虞卿著书亦何有，建阳卖卜还自迷。","瘦影难双矰缴满，寒更欲警露霜凄。","清霜白露飞不前，亭亭片月当高天。","前身忆住青龙寺，血迹还埋古井边。","遥飞尺帛君边去，沙上鸿踪隔暝烟。"]},{"t":"读泾阳先生虞山书院语录示唐须竹","f":"古风","c":["泾阳先生不复作，泾阳遗编县高阁。","彩虹垂天漫璀璨，大造徒尔鼓空橐。","永陵之季狂澜惊，倒吹枯瓠为玉笙。","平地跃起攫光影，失足犹漫誇轻清。","先生两足不妄插，矗立欲撑银汉倾。","鸟舌无从说鸟梦，人头定可作人鸣。","毫发析作千万片，一丝独飞挂匹练。","亭亭万岁终不欹，世人皆见莫能见。","呜呼乎吾不知麟衰凤去将谁传，区区下界萦寒烟。","秉烛对读过深夜，诘旦赤日生高天。"]},{"t":"听月楼倦客归山留别翠涛王孙","f":"七言古诗","c":["我梦听月楼巳久，不意今生登此楼。","楼前湘水腻碧玉，细细纹波送远秋。","我有狂歌知者谁，古人不作今人疑。","夜阑酒熟相对笑，男儿不受双眸欺。","我今归卧蒸南谷，黄菊将开酒将熟。","烂醉三万六千年，柳生左肘石穿肩。","君勿疑我不相就，听月无声月自圆。"]},{"t":"效柏梁体寿王恺六","f":"七言古诗","c":["铁墙拗头绿凤栖，就君踏花蹂香泥。","君今僦宇当湘西，阳禽回翼空悽迷。","人生即久如蹑梯，骎骎不舍相攀携。","我旬过五君始跻，欲呼苍天问端倪。","谁为龙翁配虎妻，活汞煎之如婴啼。","东兔藏金西木鸡，战酣四壁休鼓鼙。","得之圜中一刀圭，与君分吞如糖䬾。","倒骑白卫驰丹霓，俯听蟪蛄声益低。","长笑尔曹延蝤蛴，睨高欲就终无稽。","我摘月华沁心脐，君胸洞开消日镌。","斫麟为脯尧非臡，团星作饼甘露醯。","命鸾歌啭如黄鹂，羿妻婉娈出金闺。","疑贞疑谑相嘲诋，然后与君归湘溪。","岳为部娄湘成蹊，三皇五帝重摄提。","如此与君终不睽，乃称丈夫心交缔。","非炎索箑寒就烓，短歌隆隆苍虬嘶。","千春万朔留品题。"]},{"t":"风泊中湘访张永明老将吊孙吕二姬烈死读辛卯以来诸公奖贞之篇放歌以言情孙吕事详故中舍管公记","f":"古风","c":["昭潭万波叠霜縠，南望漓江暮云绿。","惊鸿叫云天不开，秋夕孤飞遥痛哭。","二十六年春蔓长，我与张君四鬓霜。","衰颜不死犹前日，湘女空灵郁杳茫。","茫茫峒云结烟草，贞魂不舍苍梧道。","哀歌血泪洒青天，管子嗣裘金郎堡。","而我悲吟独待今，二十六年愁埋心。","左掖蒙生俱未死，军中弹泪秋阴深。","呜呼乎往恨迷离无再说，一死人间万事决。","君不见张君二妇漓江滨，俄顷千秋如截铁。"]},{"t":"梅阴冢","f":"古风","c":["秋露漙，梅叶丹，莎根草虫吟初寒。","梅根千年荫野土，鹤发衰翁泪如雨。","梅叶落，梅花开，棠杜无人斸径苔，寸肠矗立望思台。"]},{"t":"翠涛携诸子游瞻云阁有作见寄遥荅","f":"五言古诗","c":["嘉游成畴昔，企叹奄方今。","金闺郁龙种，玉山宛鸾吟。","迟向深秋兴，摇荡先春心。","足知襟带敞，遂及松桧阴。","大云峙霜萼，虚室函霄岑。","缅彼鹤上客，所怀玉浆斟。","声息坠人间，羁绁逮幽林。","无乃大还诀，犹为陆海沈。","宁含衣中珠，抚兹弦外琴。","天问固难酬，孤心还自谌。","愿言云关闭，勿惊雪发侵。"]},{"t":"春尽有会而作","f":"五言古诗","c":["春生情未极，序改心难为。","俯仰各有会，踟蹰良在兹。","初暾耀幽砌，夕风鸣远枝。","清畅遥天感，迟回碧云期。","胡然屡天损，耿尔视星移。","逝川非昔叹，岐道有馀悲。","空霄难仰问，圆规无返曦。","雄剑不偶合，雍琴长自疑。","怀袖有瑶草，将为赠者谁。"]},{"t":"始冬寓目","f":"五言古诗","c":["东峰展苍翠，夕阳散平川。","天容函空谧，阐缓飞孤烟。","寒日将易暝，秋心仍未捐。","忼慨寄寥廓，通幽无绪言。","霜气警归息，坠叶飘阴喧。","迢递伫清梦，远游惊八埏。"]},{"t":"和周履道对春雪","f":"五言古诗","c":["灵雨从云崖，回风结寒霙。","萧条韶年始，摇荡芳春情。","惊珠无留缀，碎玉有馀声。","遥天益以邈，空宇含微晶。","镫夕滞九微，梅月延孤清。","缅彼苍江钓，应同瑶圃征。"]},{"t":"和高季迪风雨","f":"五言古诗","c":["风雨适在兹，歌叹无与言。","人事杳无绪，天情亦易迁。","怀抱终古间，曲折固勿谖。","腰镰入深云，荷薪续午烟。","聊尔为晨夕，不知经岁年。","思彼信陵客，曾为陈监门。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其一","f":"五言律诗","c":["怀聚亘昏夜，恻然华发惊。","零雨迷昏旦，修涂阻远营。","惠风启夕光，欣绪慰良征。","披榛幸不违，悲喜交含情。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其二","f":"五言律诗","c":["含情夫如何，忘言自闵伤。","视彼双飞鸟，日暮亦得将。","摘草勿绝心，渡水勿绝梁。","居然成迢递，惭尔随颉颃。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其三","f":"五言律诗","c":["颉颃悲以鸣，岁序无更待。","鼎鼎怀昔欢，悠悠有馀悔。","采彼灵药非，匪值青镜改。","曷谷念鸠飞，无枝念木坏。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其四","f":"五言律诗","c":["坏木无再荣，令绪唯须臾。","如彼虞渊日，即次非东隅。","百里望岳阡，将为茂草墟。","良惟身事闇，岂云天运殊。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其五","f":"五言律诗","c":["运殊不自今，物理难前测。","陵谷生人心，波流骛凉德。","琴书素业移，孝友先声息。","白发对怀忧，中夜长闵默。"]},{"t":"春初雨歇省家兄长夏庵□□□□□中惘然有作 其六","f":"五言律诗","c":["闵默复将离，行行度陌阡。","冈花自藿靡，溪流祇回旋。","天舒望益促，形远情未迁。","胡能返昨日，扃意共林泉。"]},{"t":"熊男公过访","f":"五言古诗","c":["遥山清露条，木末素月上。","佳人不违此，适尔成元奖。","先彼凉云阴，心知畏景往。","静气欣相移，天机继以长。","夙昔扶清刚，独唱閟幽响。","周道信逶迤，睘行生惚恍。","炯炯河鼓星，迢迢天汉广。","津梁诚有待，良会仍多爽。","云何衰景及，遘此西清朗。","百年如九秋，一意谐双赏。","我闻绥山桃，酝彼灵胎养。","餐之踰万春，握之在孤掌。","下士原大笑，上士成独享。","君其遂方今，缥渺慰云想。"]},{"t":"寒雨归自别峰庵寄同游诸子","f":"五言古诗","c":["晨光留宿温，山霭动云叶。","遥遥相送情，悢悢念寒涉。","怜无金母术，为返桃花靥。","弥天存鹤发，馀冬酬素业。","壮心巳分属，微绪望孤接。","清欢唯夕镫，高论寄灵笈。","四海目可营，千秋志何摄。","旋归亘不忘，物役情难协。","温伯道默存，苏门啸双惬。","梦聚相频仍，心旌固洽浃。","旷怀杳涯际，冥合无钝捷。","霜磬警昨清，缄之以重叠。"]},{"t":"瓜圃夕凉 其一","f":"五言古诗","c":["微月流西岑，初萤明青圳。","夕雨一以息，樾径珠露泫。","窅尔释烦疴，泠然得静善。","吾生岂不夙，物役固未浅。","往昔从弃捐，今怀何缱绻。","精灵寓天宇，昭涤随游衍。","所思来者遥，孰俟心期展。","脉脉霄汉閒，悠悠寄孤撰。"]},{"t":"瓜圃夕凉 其二","f":"五言古诗","c":["清士抱夕心，畸人含夜悲。","幽羁怨难巳，涤览情自微。","雨端趣有定，一致交易亏。","今兹何惝恍，摇清慑分歧。","绪风惬凉襟，宛转动素帷。","披衣视霄汉，弦月流半规。","居然无外撄，亘尔捐中疑。","还睇天宇高，今兹素节非。","万族同毂转，吾生宁依违。","戢志受天损，非云怀坐驰。"]},{"t":"冬日晚照书怀","f":"五言古诗","c":["山涤净西清，层云仍南飞。","夕光相宛约，霜气乍依违。","深紫明峰色，馀绿滋垣衣。","仰瞻零叶坠，时有寒禽归。","绪心同群动，敛息无馀机。","收照光自炯，敷荣道巳非。","晴日容相借，行将陟翠微。"]},{"t":"西冈望南岳","f":"五言古诗","c":["山行径云摇，遥山隐绝巘。","巘绝群岫分，旷览得平善。","云阴逐参差，鸟没迷近远。","微睇望巳盈，延观秀自衍。","登陟俨昔游，契阔仍今展。","今昔无合离，流峙终缱绻。","长毂轨不迁，贞观阅巳万。","天宇信若玆，子怀何歆羡。"]},{"t":"秋雨延旦晓起有作","f":"五言古诗","c":["夕星炫西宇，山影分空界。","清气俨流沐，薄吹振幽籁。","息疴方及晨，窥牖惊巳暧。","物故天所凭，轴转无相逮。","秋荑或暗滋，归鳦巳前迈。","孤碧尚流连，逝羽无芥蒂。","翮翩海岸心，惓惓寒畦态。","荣谢在斯须，动植有昭昧。","所以天阅情，临之发深慨。"]},{"t":"雨夕梦觉就枕戏效昌黎体近梦","f":"五言古诗","c":["沈阴夕巳长，噩梦魂相挠。","霜鬓失其真，童心来愈巧。","身轻月离云，心闲日出卯。","斗草康乐须，撒米麻姑爪。","狂歌演末泥，舞袖试郭鲍。","云冠莲叶捲，綵杖柳枝拗。","寻花鼻巳醒，溯风咽屡饱。","攓菱忘水溅，拾豆就烓煼。","倏忽揽孤衾，凉飙袭双骹。","故情虽不永，清欢幸巳稍。","笼鸡既争聒，被虱复群咬。","梦醒夫何为，无妨恣狂狡。"]},{"t":"吟巳犹不得曙再次前韵广之","f":"五言古诗","c":["生气纷去来，屈伸无能挠。","腐儒分梦醒，离析恣智巧。","画鸡厌元旦，冶铜铸刚卯。","辟火养鸊鹈，驱疟挂蟹爪。","庚申囚彭倨，己丑讣陈鲍。","趁火萤尻张，垂涎瓠项拗。","染指易为瞋，老拳竞相饱。","疗妒仓庚烹，咒鬼鸺留煼。","唾星酿流光，占吉灼羊骹。","渐老尝已熟，观物觉已稍。","石女孕自生，铁牛蚊漫咬。","因之参寥游，不畏苍天狡。"]},{"t":"翠涛喜雨见怀病枕赋答","f":"五言律诗","c":["灵雨自南来，飞集东皋野。","伊人遂欣畅，良怀寄遥写。","群岫翳回风，垂虹散清洒。","朱光萦药烟，念此拘拘者。"]},{"t":"冬日杂兴二首 其一","f":"五言古诗","c":["旦气息微霜，流云起相聚。","暄风动林叶，疏雨鸣高树。","夕宇还昭鲜，物变何匆遽。","寥寥下土人，邈彼高冥路。","终始阅迁流，孰能测其故。","今古归有涯，云何永依据。"]},{"t":"冬日杂兴二首 其二","f":"五言古诗","c":["零露润枯桑，运回辞故枝。","栖禽深婉昵，欲与终因依。","竟夕不相保，何况延晨吹。","晶宇垂玉绳，瑶光空陆离。","幂历千万里，含心当语谁。","顾影追畴昔，韶风漾芳时。","下映清江渌，上承灵雨飞。","时哉不再觌，群情自纷疑。","讵知幽悄怀，时为梦中期。","佳序还在目，荣光亘葳蕤。"]},{"t":"始夏","f":"五言古诗","c":["午睡过微雨，西清引凉吹。","云光逗新叶，浮绿起新媚。","文禽时一飞，水影摇丹翠。","物故有今昔，化理无荣悴。","遥知薪指穷，未始天容替。","阅变递纷扰，损悲任流逝。","嗣者无适期，遐哉惘高寄。"]},{"t":"咏归燕","f":"五言古诗","c":["凉叶飞不息，凋荷尚孤擎。","海天杳何许，层递秋云生。","栖鸟鸣高树，焉知归燕情。"]},{"t":"庶仙片纸见讯云年过七十未为非幸无容局促萦心既佩良规因之自广","f":"五言古诗","c":["素云方西飞，归鸟仍南征。","迁流无止势，蠕动况有情。","天宇敞寥廓，虚牖延孤清。","竹素涵前古，静对终吾生。","故交惠尺书，整襟拜投琼。","奖以息吹万，因之返素精。","寓形良有涯，勿为化所惊。"]},{"t":"春月歌","f":"七言古诗","c":["睛风初暖溪光紫，杨柳风轻吹不起。","迢迢璧月背云飞，摇荡春云映春水。","春水涵空倒碧天，金波微定影初圆。","花趺红敛垂珠露，叶底苔平缀玉钱。","可怜月落留难住，可惜春光来复去。","昨日梨花巳起风，何时柳絮还粘树。","柳絮梨花早岁春，芳郊草软素光匀。","绿窗竹叶飘鸾尾，白袷落英照锦鳞。","当时不解留春在，月落月生春易改。","胡蝶香迷梦不成，碧桃花褪芳谁采。","采芳踏月当年客，双鬓银丝欺素魄。","婵娟不解古今愁，斜转空山荡轻碧。"]},{"t":"来者之日歌","f":"古风","c":["来者之日还如昨，今我云胡而不乐。","去者之日一如今，徘徊今昔伤忧心。","东风吹柳鹅黄垂，千条映水摇修眉。","一片轻飘坠秋水，叶叶零零飞不起。","还丹空炼素银芽，老聃西度函关?。","?生倏忽如朝霜，春日不长冬夜长。","行人攀折莫长叹，豹?留皮王彦章。"]},{"t":"寄题翠涛新斋","f":"古风","c":["湘西开竹馆，绿净清溪源。","垂钓不在鱼，读书欲忘言。","欲从不能心自飞，白云奈尔轻霏微。"]},{"t":"仿李邺侯天覆吾歌广其意示于礼","f":"楚辞体","c":["天覆吾，地载吾，元气纷纷屑万族，灵蓍茂草争昭苏。","栖鸟在林鱼在水，而复生我何为乎。","绝粒升天等龟鹤，灵椿五百还凋落。","鸣珂帝都亦莺燕，金衣元佩喧清甸。","邺侯以此为丈夫，漠漠天心谁许见。","丈夫昂藏自有真，父兮生我天之仁。","一针义利分子午，万国胞与谁主宾。","蜗涎篆壁勿轻惹，螳臂当车莫浪嗔。","丈夫爱嗔复爱喜，落花笑看随流水。","孤月离云雪练飞，渺渺寒辉千万里。","静如池影涵青天，动则春风迸花蕊。","君不见邺侯晚节知前非，岳顶读书云满衣。","晶冰彻底纤尘净，玉魄当头素影肥。","青莲七二堆螺髻，万轴当年金简字。","千年欲识丈夫心，独上危峰揽苍翠。"]},{"t":"过李为好山居信宿 其一","f":"五言律诗","c":["紫雪桐花落，绿烟莎草凝。","闲阶斜日转，薄箑绪风胜。","消息中宵酒，过从大古僧。","淹留春病减，君似一条冰。"]},{"t":"过李为好山居信宿 其二","f":"五言律诗","c":["忘物仍忧乱，孤游托耦耕。","年华皆昨梦，风俗到今惊。","闭户生涯得，挑灯笑语清。","欹眠安枕簟，恰有曙光晴。"]},{"t":"伏日","f":"五言律诗","c":["朱火弥清昼，凉宵候久晴。","光摇千嶂迥，风定片云轻。","老病从欹枕，交游忆耦耕。","东方何意绪，割肉傲公卿。"]},{"t":"腊月一日寒雪有作","f":"五言律诗","c":["前夕雪花飞，晶光飐素晖。","半峰黄叶小，孤树暗禽归。","生理随霜鬓，寒更梦舞衣。","庚申慈氏说，寿酒素瓷肥。"]},{"t":"将夕","f":"五言律诗","c":["馀春矜断雨，将夕敛重阴。","谷口延西爽，云光敞半林。","樵归依曲曲，鸟宿渐深深。","药市虚城郭，归人阻碧岑。"]},{"t":"复病","f":"五言律诗","c":["消病一春长，藤蓑挂草堂。","亲知劳送蜜，蔬笋慰休粮。","剑鼻苔侵涩，书函燕坠香。","侵凌看柳絮，乱扑一襟霜。"]},{"t":"示刘李二生","f":"五言律诗","c":["不作少年心，凭消白昼阴。","黄梅何日熟，橄榄再来寻。","追蠡县无几，龙渊老易沈。","他时闻吹笛，莫遣忆孤音。"]},{"t":"得嘉鱼李西华兄弟书追忆雨苍","f":"五言律诗","c":["湖水阻青鞋，南游吊大崖。","探书苍水绝，藏史血函埋。","遗怨留鸿字，孤吟闭鹿柴。","郎君勤慰藉，难遣老夫怀。"]},{"t":"中秋向夕自观生居同刘生小步归草堂月上二首 其一","f":"五言律诗","c":["返照一轮微，行行望不违。","疏林迎缓步，薄影上轻衣。","雪练空初合，云波静尚肥。","閒心谋斗酒，未数草堂归。"]},{"t":"中秋向夕自观生居同刘生小步归草堂月上二首 其二","f":"五言律诗","c":["秋清犹往昔，老去得从容。","檐影分仙桂，珠光浥瓦松。","葛巾飞鸟度，霜鬓玉蟾逢。","他日酬今夕，云签在别峰。"]},{"t":"偶题","f":"五言律诗","c":["禾稻频相望，莺黄几日深。","人间又秋色，垂老足閒心。","夕照明归鸟，高林接暮阴。","前峰初上月，约略半林侵。"]},{"t":"人日 其二","f":"五言律诗","c":["夏历留人日，春深净晓天。","池冰轻破绿，初树浅含烟。","百福宜他岁，孤心惜暮年。","迢迢春赏意，还看野梅边。"]},{"t":"初秋 其一","f":"五言律诗","c":["通闰秋期早，馀蒸宿雨停。","流萤孤一照，乌鹊缓双星。","蘋叶风初定，藤花露巳零。","青蓑仍夙昔，萧瑟渐渔汀。"]},{"t":"初秋 其二","f":"五言律诗","c":["夕绮摇虹影，疏云上碧波。","中宵动雷雨，斜月半星河。","世事残书耐，吾生睡眼过。","青枫无限叶，珍重响危柯。"]},{"t":"初秋 其三","f":"五言律诗","c":["昔昔秋犹在，劳劳老易侵。","宝刀蚀虎气，孤镜吼龙吟。","凉梦惊难续，閒愁病不任。","江山留九辨，未许怨登临。"]},{"t":"岁早","f":"五言律诗","c":["雪际带春生，池冰几夕轻。","寒心犹缱绻，雨气半萧清。","客至拈桃笑，禽归试柳晴。","衰年宜缓缓，岁早自含惊。"]},{"t":"客至","f":"五言律诗","c":["病眼忘春赏，芳辰竞客游。","折腰原早岁，欹枕自前秋。","宿菜冰芽尽，寒膏炷影幽。","歌声金石发，莫为子桑愁。"]},{"t":"初夏 其一","f":"五言律诗","c":["微雨收难定，孤云远自归。","晴丝轻相逐，燕子不停飞。","回岭通群绿，清光绕四围。","天情随意缓，珍重径莎肥。"]},{"t":"初夏 其二","f":"五言律诗","c":["裛裛消春尽，匀匀看暑生。","花期随梦往，病骨喜衣轻。","药裹虫丝剔，茶烟柳絮迎。","故人缣素在，装裹趁初晴。"]},{"t":"待于礼","f":"五言律诗","c":["望望还相待，悠悠问此心。","禽归孤树夕，月上半峰阴。","稻径迷迂折，荷香送浅深。","琅然琴韵在，莫只动游鲟。"]},{"t":"先开过问病赠之","f":"五言律诗","c":["迫迫寒威甚，惺惺久病如。","纸窗明半榻，炉火拥残书。","法相沙踪雁，交情静夜鱼。","天花飞万片，祗愧净名居。"]},{"t":"冬夕","f":"五言律诗","c":["南天元气合，始夜素烟围。","薄霭孤星出，林风几叶飞。","古今销永夕，书卷掩空扉。","此夕关河迥，残镫一影微。"]},{"t":"红叶 其一","f":"五言律诗","c":["寒光烟际迥，极目乍相迎。","落日殷勤照，霜空妩媚生。","清波凝水碧，白影衬云轻。","红豆谁持赠，南枝未早荣。"]},{"t":"红叶 其二","f":"五言律诗","c":["幅幅江南画，苍山点绛纱。","桃波疑候雁，鹦觜咒寒鸦。","垂笑风难定，轻飞日易斜。","朱颜矜老寿，谁是白云家。"]},{"t":"早春馀雪属目偶成","f":"五言律诗","c":["湿云飞不起，一半雪光欺。","药裹犹畴昔，莺花笑几时。","乌藤苔露坠，白袷柳风吹。","知否韶华借，閒心早自疑。"]},{"t":"夏夕 其一","f":"五言律诗","c":["西清开一曲，明绿半溪深。","白鸟回峰碧，青林渡水阴。","荷轻初露坠，风定暗香侵。","隐几吾生事，萧然不自今。"]},{"t":"为家兄作传略巳示从子敞","f":"五言律诗","c":["无穷消一泪，墨外渍痕汪。","故国人今尽，先君道巳亡。","蒙头降吏走，抱哭老兵狂。","正可忘言说，将心告烈皇。"]},{"t":"元夕独坐","f":"五言律诗","c":["深碧绕峰峰，寒云酿自冬。","草心栖宿雪，山溜隐宵钟。","双泪初春尽，孤镫丈室封。","梅花凭笑问，莫不许从容。"]},{"t":"晦夕","f":"五言律诗","c":["初暄留宿雨，向夕尽归云。","远树山镫晕，流萤湿雾熏。","天情馀叆叇，春赏忆殷勤。","莲叶无情甚，波光一半分。"]},{"t":"四月一日","f":"五言律诗","c":["莫更惜春光，条条爱景长。","楝花三日雨，燕子一襟凉。","鱼影深摇绿，梅腮巳上黄。","韶华读史过，天地尽清狂。"]},{"t":"秋日杂咏六首 其一","f":"五言律诗","c":["夕风吹不彻，斜月数峰阴。","云晕孤轮影，珠圆曲港音。","凉云馀一照，碧汉巳双沈。","历历秋光在，当时忆此心。"]},{"t":"秋日杂咏六首 其二","f":"五言律诗","c":["疏雨定池光，荷风一袂凉。","云峰双岫合，虹影半轮藏。","日落风无定，天空望愈长。","欲归双燕子，不肯睨横塘。"]},{"t":"秋日杂咏六首 其三","f":"五言律诗","c":["清赏閒心即，馀年一日赊。","稻收寻曲草，水落理鱼叉。","选径违晨露，除棚看晚霞。","木樨香近远，初试半林花。"]},{"t":"秋日杂咏六首 其四","f":"五言律诗","c":["物候天涯改，秋心闭户知。","露垂窗影乱，云薄曙光欺。","密字微吟缓，疏藤上纸迟。","蘋风相假借，小住得支頣。"]},{"t":"秋日杂咏六首 其五","f":"五言律诗","c":["曲沼依樾径，乌藤试往回。","黄花钗股荇，文石锦钱苔。","藕叶擎孤翠，榴珠启半腮。","天情物未损，莫遣早霜催。"]},{"t":"秋日杂咏六首 其六","f":"五言律诗","c":["平湖知落雁，曲砌巳吟蛩。","短棹清波梦，幽窗坠叶风。","生存今日事，秋老一林中。","天问凭谁答，溪云掩断虹。"]},{"t":"遣闷 其一","f":"五言律诗","c":["宇旷清空回，残辉杖影斜。","林疏云度曲，水释水澄沙。","风绽丹砂子，霜滋锦缬芽。","水仙香孕绿，珍重试初花。"]},{"t":"遣闷 其二","f":"五言律诗","c":["朔吹喧平野，微暄酿一坳。","晴光分竹晕，霜液坠藤梢。","地锦颠当网，云帷巧妇巢。","无人从载酒，不受草元嘲。"]},{"t":"小步 其二","f":"五言律诗","c":["林塘春雨夙，小步爱微温。","风定开池影，云收齐烧痕。","青珠垂日给，绿绶绾天虋。","慰藉韶光甚，新愁未许存。"]},{"t":"燕","f":"五言律诗","c":["燕燕过春久，遥遥几日归。","斜临波影转，閒啅柳花飞。","小住游丝弱，横陈蛱蝶依。","春光随缱绻，清赏入霏微。"]},{"t":"夏夕 其二","f":"五言律诗","c":["试暑方前日，重阴疑凛秋。","云封双岭合，萤乱一星流。","阅化知无尽，为生果似浮。","不须多病后，始拟访丹邱。"]},{"t":"落日","f":"五言律诗","c":["落日隐归樵，回峰骋望遥。","平波云影静，素练晚烟飘。","春气惊先入，年华果易消。","溪梅无意绪，绿润上新条。"]},{"t":"见诸生咏瓶中勺药聊为俪句示之","f":"五言古诗","c":["二十四桥春，何年度楚滨。","感君垂采折，芳意在横陈。","露琲留珠个，云屑起绛鳞。","弱茎擎亦定，细缬展初匀。","縠罩茶烟浅，暄迎酒晕新。","旁侵炉气合，斜倚画图真。","飞阁高承幕，垂璎近拂巾。","绮霞叠一色，香月上重轮。","帘蝶魂如梦，笼鹦咒似瞋。","留熏十日永，惊艳满堂均。","碧叶凝云绿，珊枝带海津。","县愁倾白醉，莫遣聚朱茵。","爱惜终香阁，飘零远陌尘。","冰纹簇紫雪，芝彩涌黄银。","锦字啼鸦就，清尊倒蚁倾。","韶光易消谢，持慰撷芳人。"]},{"t":"先开移丹桂一株于窗下作供为赋十六韵","f":"五言古诗","c":["静馆香成界，空林影结邻。","道心难举似，清供不馀尘。","仙种遥移月，浓芳偶借春。","雨轻虹一色，霞近日重轮。","偷药朱颜驻，凌云紫气臻。","灵砂初破体，金粟化生身。","南国霜殷橘，江皋日射蘋。","忘忧添妙蔼，晚醉厌工颦。","落照疏林映，彤云细缬匀。","深沾湘瑟甲，乍启散花唇。","宿火沈膏灺，兰镫锦罩新。","珊枝撑玉魄，丹蕊炼金神。","莲坠留房露，榴函尽妒津。","商芝分煜煜，琴鲤想鳞鳞。","彩雾通炉篆，幽芬上氎巾。","赤旃檀荫合，谁道苾刍贫。"]},{"t":"咏风戏作艳体","f":"五言古诗","c":["约约轻云敛，匀匀晚气凉。","不教留鸟梦，何处有花香。","绣幕鸳回翼，莲镫叶坠黄。","窗摇三叠水，帘荡一波湘。","宝鸭纤丝乱，笺鸾密宇藏。","低回穿药槛，幽悄度兰房。","结束舒袿带，萦纡绕紩囊。","佩交情未许，芳袭妒何妨。","却扇从花笑，飘裾趁草长。","微温聊竹坞，无影到银塘。","系臂蛛丝缠，当钗粉絮镶。","蝶双愁易失，燕冷怯归忙。","匀汗乾珠琲，回襟漾水光。","停凝怜瀫浪，端重笑垂杨。","暖阁扃金钥，鞦韆赛锦裳。","暗尘禁冉冉，檐马错琅琅。","藤合摇阴碧，菱开漏镜霜。","迟归贪柳影，密语间松簧。","绒缕穿针乱，花须斗草忘。","闲情迷蕴藉，春思尽清狂。","卯酒消微醉，云鬟乱夕妆。","知谁千里怨，帆影望归航。"]},{"t":"玩月","f":"五言古诗","c":["云际徘徊月，高天不损寒。","三秋今夕未，万里几人看。","霄碧双摇浅，金晶倒晕乾。","平开千顷合，孤涌一轮安。","台玉擎菱镜，胎银炼雪丹。","珠津方妩媚，金蕊尽阑干。","阴木飞镫暗，轻柯弄影难。","浮浮蒸宝阁，粟粟润珠团。","碧瓦匀匹练，筠帘透素纨。","微阴知潋滟，深绿隐檀栾。","天水双轮浃，空明万染刊。","停凝聊旖旎，清绝且磐桓。","荡白生虚室，回光转曲栏。","酒魂双颊褪，潮血半丝湍。","稍觉流霜腻，无妨晓吹酸。","悬愁枫岸侧，明夜半规残。"]},{"t":"唐如心见过 其一","f":"七言律诗","c":["春草初生雪霰零，山山曾踏几茎青。","居然天地成今古，何必云岚不典型。","执戟汉亡谁载酒，尚书秦暴有传经。","怜君问礼当深夜，急难原头念鹡鸰。"]},{"t":"唐如心见过 其二","f":"七言律诗","c":["酌酒无多剪烛长，凌侵冰玉蹙寒塘。","赠云有意寻宏景，赋雪无心付谢庄。","玳瑁云痕开远碧，流莺柳色竞新黄。","晴光倩送青鞋去，分取狂夫一半狂。"]},{"t":"元夕","f":"七言律诗","c":["望月竛竮出浅霞，背人约莫数年华。","垂杨向夕惊新绿，蜡炬停风结小花。","寂历影堂香篆静，萧清春径藓纹遮。","南瞻欲问平安竹，好护刘瓛处士家。"]},{"t":"春兴 其一","f":"七言律诗","c":["嬉春迟暮老廉夫，长卧归休旧酒徒。","不分传家三传在，从来亡国一身孤。","玉钱月影窥双鬓，碧海云波认五湖。","一尽龙钟供世笑，苍天还识老狂无。"]},{"t":"春兴 其二","f":"七言律诗","c":["楼空山远湿烟蒸，返景长天暝色仍。","千里湘皋归雁雨，九江春水钩鱼镫。","马殷冢在生新草，陆逊营荒挂古藤。","梦里白蘋洲上月，遥遥北渚接黄陵。"]},{"t":"春兴 其三","f":"七言律诗","c":["春风仍上柳丝边，烂漫生涯醉暖烟。","垂老田光无酒客，相知宁朔有龙渊。","平皋漠漠飞新燕，涧道阴阴响细泉。","荏苒栖心讯芳草，剧将嫩绿逞华年。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其一","f":"七言律诗","c":["空明片纸涵晶瑩，微惹惊蛇一线灰。","白社原同匡岭寺，青山不染米家堆。","偶移浅碧腾腾合，小试光风灼灼来。","疑是清江霜月好，孤山斜惹水边梅。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其二","f":"七言律诗","c":["月华欲上不得上，晴光一倍偿今朝。","轻云疑尔还相掩，宿雾初蠲忽巳飘。","低亚殢人相绰约，回波响远试逍遥。","翻然欲把浮邱袂，冉冉云轻隔海潮。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其三","f":"七言律诗","c":["心通无地更询他，隔院风生乍染魔。","垂手舞因轻带鸟，扶头醉且厌堆螺。","微凉羽扇频摇曳，半睡仙裾自沓拖。","安得千寻看月落，凭将澹远问东坡。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其四","f":"七言律诗","c":["几枝略点红垆雪，片晌聊依篆尾香。","稍惜晴风吹不定，还愁落日去偏忙。","露珠暗坠惊魂起，㬉晕斜轮数叶凉。","清瘦自憎临绣幕，湘纹巧映竹方床。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其五","f":"七言律诗","c":["凭阑觌面不相知，邂逅晴窗瞥见时。","浅黛斜分临晓镜，落花轻惹上蛛丝。","萍开绿水鱼情得，叶坠幽光鸟梦奇。","活色暗香难举似，浮沤目醉共清嬉。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其六","f":"七言律诗","c":["色借明缘还似幻，白生虚室不曾遮。","老夫偶梦看成蝶，诸子忘弓莫问蛇。","月满桂难亏玉魄，雷惊春已长花芽。","何须玉版参离合，丈室天空散碧霞。"]},{"t":"南天窝授竹影题用徐天池香烟韵七首 其七","f":"七言律诗","c":["根窠休访午阴圆，斜上幽窗倍可怜。","映字不妨遮粉本，谈经适尔点青毡。","高秋巳瘦馀清泚，积雨欲消待往旋。","晚照乍移莫怅望，还将凤尾舞婵娟。"]},{"t":"徐合素自南来抵郡城远讯船山代书答之尊世父闇公从海上卒于岭表廿馀年矣因寓我尚为人之叹","f":"七言律诗","c":["梅霪风困药垆烟，乳燕衔书坠枕前。","梦里短衣看射虎，重来高柳怨鸣蝉。","归舟知汛桃花水，荒径将寻箭筈天。","莫问霜髭今几许，君家松柏五云边。"]},{"t":"五日前一夕唐如心以近诗见问病废夜读久矣即夕口占寄意","f":"七言律诗","c":["榴花困雨不得红，溪荪浃露青烟丛。","明朝谁续五丝缕，新月初弯一线弓。","楚国神弦惜往誓，山中桂树思悲翁。","纸窗晴日能相借，锦字凭开雾眼空。"]},{"t":"寄周令公","f":"七言律诗","c":["湘波一尺阻东西，湘草湘烟入望迷。","碧海相看消镜雪，丹经何术炼银泥。","归舟吴越迎歌扇，潭水沧浪废杖藜。","问讯绥山桃几熟，飞花好寄五陵溪。"]},{"t":"病起连雨四首 其一","f":"七言律诗","c":["炉烟平敛晚天清，病起閒愁也自轻。","风定小容秋叶缓，月生微放雨窗明。","江山他日仍如此，河汉经时巳早倾。","荏苒嵯峨留瘦骨，黄橙丹柏看冬荣。"]},{"t":"病起连雨四首 其二","f":"七言律诗","c":["荻花风乱扑人飞，夕鸟双峰一线归。","暑病乍清怜雨气，寒衣姑缓待霜威。","龙腥秋涩云藏岫，鹭影光寒水上矶。","幸不登临悲往昔，遥天白霭翠微微。"]},{"t":"病起连雨四首 其三","f":"七言律诗","c":["白发重梳落万茎，镫花镜影两湛惊。","水金丹诀闻方士，土木蔘膏累友生。","故国馀魂长缥渺，残镫绝笔尚峥嵘。","悬知药力消冰雪，未拟垂杨听早莺。"]},{"t":"病起连雨四首 其四","f":"七言律诗","c":["潜圣峰云碧万层，萧萧杉竹托山僧。","辜恩垂死馀双泪，扶病今生梦一登。","多日六经藏孔壁，何人十字志延陵。","湖天秋水鱼书绝，寂寞孤阡挂古藤。"]},{"t":"代书答舌剑韬","f":"七言律诗","c":["洣水东流岳阜西，鱼书摇问浣花溪。","千峰旧访孤轮月，双脚难拚一寸泥。","大誓馀生闻虎啸，衰年独坐弄驴蹄。","东山只履归何日，草软烟柔一杖藜。"]},{"t":"宿明溪寺山僧导游珍珠岩","f":"七言律诗","c":["苍崖乳溜渍苔乾，阴壑埋光生夏寒。","殷孽可怜添石㾦，飞鼯亡赖扑镫阑。","何如藻井铺霞绮，自敞珠宫迓日丹。","读易幽篁双径锁，当时悔不访仙坛。"]},{"t":"秋兴","f":"七言律诗","c":["秋藕缫丝缀冷香，蓼花靺鞨染轻霜。","月津巳转从云妒，星渚初离更夜长。","临水登山悲郢客，守庚炼己老丹房。","白蘋一罅清泉镜，风飐霜髭照影凉。"]},{"t":"昔梦","f":"七言律诗","c":["昔梦閒情一枕蠲，閒愁过眼万心镌。","湿云叶叶垂虹外，归鸟泠泠晚照边。","涧草自分寻药径，湖天谁汛钓鱼船。","西清斜月能消得，片玉轻松半影县。"]},{"t":"雨馀小步","f":"七言律诗","c":["莲花莲叶柳塘西，疏雨疏风斜照低。","竹箨冠轻容雪鬓，桃枝杖滑困春泥。","垂虹疑饮双溪水，砌草新添一寸荑。","不拟孤山閒放鹤，鹁鸠恰恰向人啼。"]},{"t":"初月","f":"七言律诗","c":["六月四日收夕雨，一弯初上划西清。","冰纨小蹙添纹皱，青镜斜临上粉轻。","垂柳千眉争宛宛，流萤半影怯盈盈。","新秋通闰知何日，巳映银河一道明。"]},{"t":"冬日书怀","f":"七言律诗","c":["木落山空朔气吹，云消星白曙光疑。","曈昽烟海天无际，天袅霜华月半规。","今古闲愁孤枕尽，渔樵残梦晓钟知。","春心他日将谁赠，辜负寒梅折几枝。"]},{"t":"翠涛过草堂问病 其一","f":"七言律诗","c":["稻露垂珠远望平，疏风疏雨葛衣轻。","枫林摄摄消残暑，禅室登登待早晴。","话到閒愁无一字，棋终残局笑双征。","因君莞尔加餐饭，不问参苓托死生。"]},{"t":"翠涛过草堂问病 其二","f":"七言律诗","c":["江楼十载故心违，池影相看上雪肥。","银汉未倾怜酒尽，金风欲避倩云围。","尊生为嘱悲欢损，惜别县知伴侣稀。","观穫送君归下噀，西清一雁贴天飞。"]},{"t":"夏日喜何诣得见过","f":"七言律诗","c":["苗叶梳风暑乍消，归禽掠日影逍遥。","闲披绿草依孤树，喜看青衫渡小桥。","密语偶窥康节梦，清狂未觉步兵骄。","剪灯坐叹流光回，他日何方觅老樵。"]},{"t":"侄敏五十 其一","f":"七言律诗","c":["邗沟棨戟插湘滨，骁骑云仍到尔身。","戍削月垂千丈影，团圞松偃一庭春。","青毡未损传家物，黄菊相期漉酒巾。","好理残书贻子弟，乌衣燕识画梁新。"]},{"t":"侄敏五十 其二","f":"七言律诗","c":["吾方授室尔悬弧，一幅当年燕喜图。","脉脉回头成梦鹿，悠悠屈指数金乌。","黄云初捲收香粒，赪枣重蒸酿软酥。","幸有老夫霜鬓在，东皋遥劝倒村酤。"]},{"t":"重过三座山与故人罗君遇赠之","f":"七言律诗","c":["三十九年弹指閒，居然无恙只青山。","一双镜影髭凝雪，九月枫林叶坠斑。","旧恨冰轮消兔阙，故交雪涕吊渔湾。","爱君步履轻如鹤，独向苍天乞老閒。"]},{"t":"宿别峰庵庶仙策杖来慰时方从哭送先兄归垄返","f":"七言律诗","c":["幂幂苍烟护小桥，回峰斜引上方遥。","归禽邀日沈平楚，宿露泠风润绿蕉。","白发共怜镫影瘦，青山未遣泪痕消。","凭君昨日山阳笛，吹彻寒冰慰柳条。"]},{"t":"社前一日雪","f":"七言律诗","c":["社日花朝总令辰，柳丝萍叶总宜人。","巳催莺燕迎初日，未许风光试一春。","紫电暗窥珠佩笑，轻雷不惜玉衡嗔。","还思残腊新暄早，勾引江梅万树匀。"]},{"t":"二十四日又雪","f":"七言律诗","c":["云鏬斜晖剧可怜，惊飙一夕万峰喧。","瓦松邂逅含晶密，水碧依微困影圆。","销铄风光仍夜永，淹留寒色更春前。","药畦红茁抽三寸，他日欲寻更惘然。"]},{"t":"罗桐侯受业先兄存没依轸倍于馀子春初过慰衰老怆然酬赠","f":"七言律诗","c":["纸窗竹屋俯寒泉，总角相看巳冁然。","莎径情深寻带草，芦中恩重覆渔船。","重来棠杜初悲雨，老去桃花不记年。","一卷申公诗说在，凭君珍重护秦烟。"]},{"t":"寄题先兄祠屋 其一","f":"七言律诗","c":["寒泉古木问何年，鹤羽归来一哂然。","沧海能消衔土怨，沃州不待买山钱。","谁投粔籹酬江水，为饵饧香禁冷烟。","留语乌衣诸子弟，应知头上有青天。"]},{"t":"寄题先兄祠屋 其二","f":"七言律诗","c":["白发青林一径悭，羊裘不拣钓鱼湾。","当年有誓潭龙窟，身后还悲吊鸟山。","目送斜阳沈海岸，手栽修竹染霜斑。","致身录在凭谁读，垆冷香消亦等閒。"]},{"t":"崇祯癸未贼购捕峻亟先母舅玉卿谭翁以死誓脱某兄弟于虎吻谢世以来仰怀悲哽者三十馀年翁孙以扇索敏侄书字缀为哀吟代书苦不能请先兄俯和益以老泪淫淫承睫不止","f":"七言律诗","c":["枫林落叶岳云寒，兄弟披离片影单。","九族凭谁容破壁，寸心巳许付危湍。","恩深草屩随拖杖，命续霜刀惜刈兰。","今日渭阳回首处，萧条白发泪痕乾。"]},{"t":"别峰庵二如表长老类知子者对众大言天下无和峤之癖者唯船山一汉愧不克任而表师志趣于此徵矣就彼法中得坐脱其宜也诗以吊之","f":"七言律诗","c":["延陵未识披裘客，杨亿还疑转盼僧。","银地界中金屑眼，热油铛里雪山冰。","相逢歧路双趺印，顾笑县崖一杖登。","今日重拈唯荐泪，秋山叶落冷孤藤。"]},{"t":"冬山即事 其一","f":"七言律诗","c":["萝阴曲曲謢迥塘，亭午初消子夜霜。","小藻分波还浸碧，閒花似菊未凋黄。","游鱼带影双遮水，孤蝶迎晴倍惜香。","天物殷勤相假借，凋零不遣恼疏狂。"]},{"t":"冬山即事 其二","f":"七言律诗","c":["元绡垂幕黛烟流，略挂西峰玉一钩。","萧散云还沈碧海，清空人欲访琼楼。","匀匀广野疏星度，恻恻寒心片影浮。","取次閒愁栖泊尽，更谁笙鹤梦丹邱。"]},{"t":"冬山即事 其三","f":"七言律诗","c":["小雪无云宿暧赊，东窗日转半棂斜。","清泉砚滴含馀绿，活火汤瓶涌细花。","歌哭古今归午枕，江湖图画泛星槎。","堂堂日月容相问，书卷留人几岁华。"]},{"t":"冬山即事 其四","f":"七言律诗","c":["墙阴小步试欹危，未厌晴风袅鬓丝。","槠实乍惊飞鸟过，苔阴渐放素光移。","绀珠千颗垂藤子，丹叶孤飘绕故枝。","寂历经过聊缓颊，重来千载更伊谁。"]},{"t":"野史刘生惜十年之别来访山中为写衰容赋赠二首 其一","f":"七言律诗","c":["重逢无暇问前游，老去并刀割旧愁。","风定鳞鳞萍在水，云横脉脉雁当楼。","频年苦觅蔘苓倦，俭岁无多芋栗收。","良夜对君霜月迥，还教飞梦泛沧洲。"]},{"t":"野史刘生惜十年之别来访山中为写衰容赋赠二首 其二","f":"七言律诗","c":["弥天无处着衰颜，映水愁窥彻骨寒。","雁影自宜霜月暗，镜光知向暮春残。","江门蓑冷添藤笠，易水歌阑尚白冠。","惭愧云林幽兴绝，还留画里一人看。"]},{"t":"辛酉日遣怀 其一","f":"五言绝句","c":["短烛空烧柏，浊醪不荐椒。","岁华知几日，人道是今朝。"]},{"t":"辛酉日遣怀 其二","f":"五言绝句","c":["东峰忽散云，飞光射檐端。","未解消冰雪，晶荧一倍寒。"]},{"t":"辛酉日遣怀 其三","f":"五言绝句","c":["㬉气幸霜馀，留寒酿春雪。","药力不峥嵘，眉间蹙千缬。"]},{"t":"辛酉日遣怀 其四","f":"五言绝句","c":["手折琼瑶枝，欲以赠远者。","姑射冰雪姿，乘云不来下。"]},{"t":"罂粟","f":"五言绝句","c":["娇小垂头立，丰盈出面来。","花王休相妒，侬不向春开。"]},{"t":"相思子","f":"五言绝句","c":["无识自有情，咫尺银河渡。","不问许多时，渠还在何处。"]},{"t":"绝句八首 其一","f":"五言绝句","c":["黄鸟衔青虫，径飞入深箐。","蛱蝶绕墙飞，相逢不相见。"]},{"t":"绝句八首 其二","f":"五言绝句","c":["伏日人间暑，西风天际阴。","秦坑从烈火，鲁壁自清琴。"]},{"t":"绝句八首 其三","f":"五言绝句","c":["莲叶千茎乱，因风捲翠烟。","飞来双白鸟，不省在谁边。"]},{"t":"绝句八首 其四","f":"五言绝句","c":["瓜架穿萤白，藤梢点露青。","牵牛花巳发，天上候双星。"]},{"t":"绝句八首 其五","f":"五言绝句","c":["稻花垂金丝，弱如红蓝蕊。","风起飏蜻蜓，含香点溪水。"]},{"t":"绝句八首 其六","f":"五言绝句","c":["宿鸟波流影，孤萤冷度溪。","云留分一半，月在柳塘西。"]},{"t":"绝句八首 其七","f":"古风","c":["韎?穿窗人，钱钱缩影高。","人间酣睡客，几处梦樱桃。"]},{"t":"绝句八首 其八","f":"五言绝句","c":["閒简蝇头字，芭蕉雪里心。","青青河畔草，自有鬼能吟。"]},{"t":"敔筑土室授童子读题曰蕉畦口占示之四首 其一","f":"五言绝句","c":["治畦当种竹，种蕉为近之。","虚中同一致，密叶胜疏枝。"]},{"t":"敔筑土室授童子读题曰蕉畦口占示之四首 其二","f":"五言绝句","c":["脆绿怜弱干，勿为霜雪侵。","春风动雷雨，须长一千寻。"]},{"t":"敔筑土室授童子读题曰蕉畦口占示之四首 其三","f":"五言绝句","c":["莫剪当檐叶，凭传萧瑟音。","岳峰窗外雨，滴碎汝翁心。"]},{"t":"敔筑土室授童子读题曰蕉畦口占示之四首 其四","f":"五言绝句","c":["题字成元草，绿天幻绛纱。","勿容贪载酒，何客可名芭。"]},{"t":"水仙","f":"七言绝句","c":["乱拥绿云可奈何，不知人世有春波。","凡心洗尽留香影，娇小冰肌玉一梭。"]},{"t":"代书寄衡山戴晋元 其一","f":"七言绝句","c":["松梢浅着馀冬雪，兰若閒烧丙夜镫。","一枕梦回衾似水，不知仙洞隔朱陵。"]},{"t":"代书寄衡山戴晋元 其二","f":"七言绝句","c":["寒山不稳归飞鸟，锦字难传夜静鱼。","闻说茂陵方病渴，莫修封禅数行书。"]},{"t":"山月歌","f":"七言绝句","c":["船山山半月垂湾，太白光连夕照间。","白发故人愁不见，天西无数五溪山。"]},{"t":"白云歌 其一","f":"七言绝句","c":["无数閒云出翠微，和风和雨夹山飞。","孤烟一片如轻絮，自绕疏林款夕晖。"]},{"t":"白云歌 其二","f":"七言绝句","c":["一片轻飞岭上分，当时犹自惜离群。","飞来飞去秋风里，今日青山无片云。"]},{"t":"白云歌 其三","f":"七言绝句","c":["白云飞也自寻常，不道青山不久长。","看尽云飞天阙迥，清空一碧映潇湘。"]},{"t":"白云歌 其四","f":"七言绝句","c":["前日浮云飞出山，山前为雨不曾还。","云收雨散无消息，何似青山一碧閒。"]},{"t":"白云歌 其五","f":"七言绝句","c":["浮云本不恋山巅，木叶随风更可怜。","欲得归林归不得，蛛丝县挂矮檐边。"]},{"t":"杂咏 其一","f":"七言绝句","c":["曲岸平塘小径通，山坳倚杖避回风。","知谁扑速林间响，雀啄霜馀数子红。"]},{"t":"杂咏 其二","f":"七言绝句","c":["暝烟欲捲任栖迟，断嶂云光射岭西。","恰似半晴三月雨，林梢只少子规啼。"]},{"t":"杂咏 其三","f":"七言绝句","c":["罂粟苗轻翠瓣娇，水仙胎满暗香飘。","丁宁雪霰休凌藉，任打窗前败叶蕉。"]},{"t":"杂咏 其四","f":"七言绝句","c":["问病人稀樾径閒，朝飞孤鸟暮飞还。","麇䴥避虎昨宵过，乱蹴泥黏碧藓斑。"]},{"t":"又雪","f":"七言绝句","c":["一雪才消一雪飞，不留馀白映霏微。","何当贳与严陵寿，建武初年守钓矶。"]},{"t":"送刘生辑夏归省重庆","f":"七言绝句","c":["蒸江漱玉绕苍汀，玳瑁霜云拥翠屏。","归向湘山高顶望，应曕南极老人星。"]},{"t":"和龟山此日不再得","f":"古风","c":["我生秉孱弱，不能任耕桑。","居然消秫稻，何以酬旻苍。","星尽晨鸡鸣，东方生炯光。","良阴无踟踌，俄顷收斜阳。","行行天地间，南北各有方。","步履无定审，宇宙空茫茫。","忮求但自辑，尚未足以臧。","百端苟遏绝，暗触还自?。","身心取轻安，未免等秕糠。","良珠固在握，胡乃忘吾藏。","春暄熏百草，随类发芬芳。","秋气净四极，一碧涵清刚。","春秋皆在斯，何为空徬徨。","积粟太仓盈，积步万里长。","踸踔而凌越，竺氏与蒙庄。","如彼鸟篆空，漫尔矜文章。","辨说及组绣，慷慨登词场。","如彼挟策子，与博偕亡羊。","砭心不知痛，支体皆隳忘。","何忍蹈此蹊，而更诧豪彊。","关闽有津济，但自理舟航。","鼓勇未为殊，绵绵功在常。","一息不相续，前勤皆巳亡。","与俗俱汨没，徒为造物伤。","返念诚自惊，斯须分圣狂。"]},{"t":"溪上晚步次閒来无日不从容韵","f":"七言律诗","c":["溪光空碧净秋容，灼灼斜阳蓼岸红。","风日不欺樵径好，江山未换钓竿同。","难分忧乐双行里，谁道穷通一梦中。","不遣希夷酬上古，乾初一画海天雄。"]},{"t":"和白沙 其一","f":"七言律诗","c":["胡不思身巳有身，桃花柳絮各当春。","归除共算三辰日，截续无差上古人。","拔地雷声惊笋梦，弥天雨色养花神。","他时午夜青天月，恰好金波片影真。"]},{"t":"和白沙 其二","f":"七言律诗","c":["粥饭终朝剧可怜，无心丛里有心天。","髑髅不爽元生意，枯槁翻新看火然。","莫撇孤清求鸟径，已知实际历长年。","分明饶有中和用，不但虚悬未发前。"]},{"t":"为躬园题用念庵韵 其一","f":"五言绝句","c":["历历有此躬，何求而不得。","即此欲得心，分明无疑惑。"]},{"t":"为躬园题用念庵韵 其二","f":"五言绝句","c":["受来非彼来，应去亦不去。","云行而雨施，皆予措躬处。"]},{"t":"读念庵诗次之 其一","f":"七言绝句","c":["真静应知动不消，冰霜雷雨总清霄。","吹镫灭影形还在，炯炯三更伴寂寥。"]},{"t":"读念庵诗次之 其二","f":"七言绝句","c":["碧笋惊雷拔地长，绿筠玉粉土膏香。","连踵彻顶无涯畔，谁是胞胎秘息方。"]},{"t":"和白沙 其三","f":"七言律诗","c":["问天无意更枯蓍，不道忘情胜马龟。","蒙叟梦中真蛱蝶，柴桑枕上自轩羲。","汀洲杜若香原在，海上蓬莱路不疑。","欲起江门向今日，藤蓑珍重钓珊枝。"]},{"t":"和白沙 其四","f":"七言律诗","c":["百尺峰头泛铁船，情知到我却无缘。","遥飞青鸟知难致，当顶金乌不易迁。","一线自循芳草路，双趺直上蜃楼巅。","劳劳终日心閒极，池上琴尊笑乐天。"]},{"t":"鼾睡 其一","f":"七言绝句","c":["拂拭南窗小榻空，绿阴鏬里纸光红。","昨朝狼籍今朝在，花自轻飞柳自浓。"]},{"t":"鼾睡 其二","f":"七言绝句","c":["劈破须眉剩脊梁，閒心不耐更商量。","朦胧稍见东峰上，一片云飞暮雨香。"]},{"t":"鼾睡 其三","f":"七言绝句","c":["薝葡胎玉破新函，白发簪花老自惭。","冲雨摘来安枕上，香熏华顶老图南。"]},{"t":"鼾睡 其四","f":"七言绝句","c":["挍书如萚埽难穷，且自埋心白昼中。","为报泉台旧知己，侬非刘向与扬雄。"]},{"t":"鼾睡 其五","f":"七言绝句","c":["春鸟过春不肯鸣，雨中仍听两三声。","绿光影里还飞去，惊落残红一片轻。"]},{"t":"鼾睡 其六","f":"七言绝句","c":["诗书放下千端在，王霸拈来一点无。","消受三竿红日影，生成一幅后天图。"]},{"t":"鼾睡 其七","f":"七言绝句","c":["白日惺忪卖影新，人间原有黑甜春。","梦中不识邯郸道，记得诚斋煞认真。"]},{"t":"咏怀次韵 其一","f":"七言律诗","c":["洪炉片雪陈公甫，独棹中流罗一峰。","玉露金茎撑九陌，桃花流水度三冬。","江门孤月元无影，太极丸春自有容。","传与铁船凭泛海，棹歌声里尽相逢。"]},{"t":"咏怀次韵 其二","f":"七言律诗","c":["不问青天拟问谁，孤琴摇曳动清脾。","雷声偶逐片云起，轻碧无劳过雨疑。","几有一沤生旧处，笑看新叶发残枝。","逢人持此閒供具，啼笑当前换两眉。"]},{"t":"咏怀次韵 其三","f":"七言律诗","c":["纸窗无缝看青山，也觉秋容不放閒。","瓶水影中莎草岸，菱花曲里白蘋湾。","他时摇落含春思，昨夜萧清启月颜。","识得金风消息好，逢场抖擞试痴顽。"]},{"t":"次定山三首 其一","f":"七言律诗","c":["野马从来未受羁，寒原衰草不须辞。","残山残水谁相问，独笑独歌且浪为。","日午睡连清旦睡，白沙诗更定山诗。","青霄明月容迟上，一卷残书了更迟。"]},{"t":"次定山三首 其二","f":"七言律诗","c":["摊书腹内破彭亨，不忆愁从何处生。","天地病深宜我病，须眉睁后更谁睁。","醇醪聊借风光酿，仙药无劳雨露耕。","正自坦然人尽觉，敢矜天马蹑空行。"]},{"t":"次定山三首 其三","f":"七言律诗","c":["溪月溪风太有情，不容尘土得分争。","乾坤消受无多子，今古萧条第一名。","梦里青山留我住，镜中白发为谁生。","炉烟销尽空香满，脉脉幽心只自评。"]},{"t":"和白沙钓濑与湛民泽收管诗示唐须竹","f":"七言绝句","c":["遥山写出虚无画，孤笛吹来雪月吟。","不是逢人难口说，湘流清浅祝融深。"]},{"t":"三门滩感兴三首 其一","f":"五言古诗","c":["古今皆效动，欲静势不遣。","古今皆效静，欲动功不展。","乘之有顺逆，用之有深浅。","无心即无知，有心智复蹇。","脉脉以持危，非言能宣显。"]},{"t":"三门滩感兴三首 其二","f":"五言古诗","c":["置身云际观，何为而栖栖。","延目千秋视，所据皆粉齑。","目力既有穷，生年不久稽。","吾心固可引，遥与霄汉齐。","苟守规中见，安能无笑啼。"]},{"t":"三门滩感兴三首 其三","f":"五言古诗","c":["鸣鸢为风徵，鸣鹳为雨徵。","畏风或苦雨，勃然而怒兴。","天适欲风雨，吾力亦奚能。","吾适患风雨，天心亦奚凭。","况彼区区者，俄然为化乘。","不知方寸内，风雨皆渊冰。"]},{"t":"露坐和白沙","f":"五言律诗","c":["不辨香何际，回塘有芰荷。","风来巳良久，月上见微波。","草气从凉净，星光在宇多。","韶英吾识汝，枯竹有鸾歌。"]},{"t":"月坐和白沙","f":"五言律诗","c":["幽筱晚风迟，披襟待月痴。","亭亭有独坐，夕夕得清嬉。","休夏闻西竺，衰周栖仲尼。","藕丝非系缚，灰槁亦奚为。"]},{"t":"和白沙中秋","f":"五言律诗","c":["片叶听萧然，何妨素影翩。","东窗千嶂外，玉镜一轮圆。","空界原非妄，天心巳尽传。","明宵随显晦，墟里上孤烟。"]},{"t":"和白沙真乐吟效康节体","f":"五言律诗","c":["真乐夫如何，我生天地间。","言言而行行，无非体清元。","春鸟鸣华林，秋水清寒渊。","无功之功微，乘龙而御乾。"]},{"t":"和白沙八首 其一","f":"五言律诗","c":["耳目忻浮光，不自知其性。","砂中原含金，非天有殊命。","外取亦甚晰，内视还成瞑。","如彼夜行人，思与骐骥竞。"]},{"t":"和白沙八首 其二","f":"五言律诗","c":["天下自閒閒，人心长戚戚。","身为物所持，骑虎不得息。","息之在先几，几先人不识。","适燕而南辕，终身无返迹。"]},{"t":"和白沙八首 其三","f":"五言律诗","c":["我闻庄定山，其心如寒铁。","去我二百载，清琴音已绝。","船山半亩池，一泓贮香雪。","濯发夕风微，长歌弄明月。"]},{"t":"和白沙八首 其四","f":"五言律诗","c":["迢迢开一径，双足尽登临。","密至云无际，明生月有心。","当前霜岸直，彻底碧潭深。","神禹留金简，居然在岳岑。"]},{"t":"和白沙八首 其五","f":"五言律诗","c":["蠕息皆吾侣，鲲鹏固不交。","有时冰串释，歘尔泪珠浇。","酬物唯三径，从天付一瓢。","空林桂花发，何有小山招。"]},{"t":"和白沙八首 其六","f":"五言律诗","c":["此心昼夜至，此生天地生。","云先肤寸合，月到上弦明。","自昔知无畏，随方受一清。","白沙潇洒处，步步踏莎行。"]},{"t":"和白沙八首 其七","f":"五言律诗","c":["无云天自碧，有云天亦清。","在天原不损，因尔有云名。","一极情无妄，六爻变遂成。","千秋尽合辙，莫笑造车轻。"]},{"t":"和白沙八首 其八","f":"五言律诗","c":["江门一空际，万卷且幽寻。","龙马谁之迹，星河尽此心。","萍月开池影，松风合涧音。","万端无彼是，中有指南针。"]},{"t":"旅警五首 其一","f":"五言律诗","c":["此曰良可惜，纯熟尚不舍。","断续有异心，况我悠悠者。","巨浪而停舟，将为千里泻。","恻恻生内惭，红轮西坠也。"]},{"t":"旅警五首 其二","f":"五言律诗","c":["恻恻保此名，踧踧擭此生。","此生何以重，此名何以荣。","无乃随影动，其根若浮萍。","安得良宵中，齁睡而不惊。"]},{"t":"旅警五首 其三","f":"五言律诗","c":["幸天与我知，幸世与我忧。","知知而忧忧，人将为我忧。","不知而不忧，吾将为我愁。","岂不有我哉，云胡不自求。"]},{"t":"旅警五首 其四","f":"五言律诗","c":["闭户读残书，居然有户牖。","出门对群动，未必免濡首。","无曰无知音，日月皆针灸。","彻骨疗沈疴，焉得辞老丑。"]},{"t":"旅警五首 其五","f":"五言律诗","c":["辨言终自贼，寸心若电耀。","使自溯源流，多端堪内笑。","请即所笑端，捩转其枢要。","孤月游霜空，寒林清猿叫。"]},{"t":"元日折梅次定山韵","f":"五言律诗","c":["随折一枝好，清香破雾新。","盈盈此天地，恰恰正芳春。","白发不相负，青阳始试旬。","殷勤明看汝，朵朵玉华真。"]},{"t":"和白沙梅花 其一","f":"七言绝句","c":["梅花欲发雪撩之，不损清香一万枝。","半点千钧春气力，看花人似海谁知。"]},{"t":"和白沙梅花 其二","f":"七言绝句","c":["花外春光有此梅，江城断岸尽催开。","寒蜂冻蝶谁驱汝，度叶穿花得得来。"]},{"t":"和白沙桃花","f":"七言绝句","c":["花到灵云只一开，桃根桃叶隔天台。","刘郎前度人无恙，日日看花不厌来。"]},{"t":"和白沙 其五","f":"七言绝句","c":["影从虚出无生响，两段分开觉后迷。","但识太空都扑满，不容风雨弄天机。"]},{"t":"和白沙 其六","f":"七言绝句","c":["云移隔岭摇绿草，雨过横塘绽白莲。","大造无心谁解此，庄生浪说欲忘言。"]},{"t":"为白沙六经总在虚无里解嘲","f":"七言绝句","c":["晓日上窗红影转，暝烟透岭碧烟孤。","六经总在虚无里，始信虚无不是无。"]},{"t":"和一峰虚中是神主五首 其一","f":"五言绝句","c":["神者天之妙，心者人之主。","去人而用天，我生如鳞羽。"]},{"t":"和一峰虚中是神主五首 其二","f":"五言绝句","c":["神静物不撄，神动心以靡。","不复知其他，禅元但测此。"]},{"t":"和一峰虚中是神主五首 其三","f":"五言绝句","c":["天地既设位，人微何以参。","分明有人主，天地不能堪。"]},{"t":"和一峰虚中是神主五首 其四","f":"五言绝句","c":["人心天之仁，道心人之仁。","造物自大德，奈何迷我真。"]},{"t":"和一峰虚中是神主五首 其五","f":"五言绝句","c":["不但尘非我，光昭亦是天。","实中是人主，珍重一峰传。"]},{"t":"示两子 其一","f":"七言绝句","c":["一年不遣病躯安，此事分明汝辈看。","不为菜羹须汝出，人间第一菜羹难。"]},{"t":"示两子 其二","f":"七言绝句","c":["领我清狂累几分，旁人指摘更深文。","回眸但顾身边影，即尔依依望白云。"]},{"t":"暑过友人新斋六首 其一","f":"五言绝句","c":["烧灯照双影，两心在影中。","影随灯去留，此心满虚空。"]},{"t":"暑过友人新斋六首 其二","f":"五言绝句","c":["骎骎行稻田，薰风为谁发。","知君开轩望，县愁凉吹歇。"]},{"t":"暑过友人新斋六首 其三","f":"五言绝句","c":["古人不可知，今人我对君。","有时发狂嗔，太和自氤氲。"]},{"t":"暑过友人新斋六首 其四","f":"五言绝句","c":["萧斋临古甸，绿香飞几席。","一峰太极丸，居然自畴昔。"]},{"t":"暑过友人新斋六首 其五","f":"五言绝句","c":["飞雨白四峰，人如云中坐。","此势不可忘，当眉起顽懦。"]},{"t":"暑过友人新斋六首 其六","f":"五言绝句","c":["就子请一言，珍重言复止。","如彼冰上行，厚薄自知耳。"]},{"t":"读文中子 其一","f":"七言绝句","c":["乐天知命夫何忧，不道身如不系舟。","万折山随平野尽，一轮月涌大江流。"]},{"t":"读文中子 其二","f":"七言绝句","c":["天下皆忧得不忧，梧桐暗认一痕秋。","历历四更山吐月，悠悠残夜水明楼。"]},{"t":"书陈罗二先生诗后 其一","f":"古风","c":["白沙飞舞茅龙，一瓠埋头蝇迹。","莫道我狷彼狂，共弄暮天空碧。"]},{"t":"书陈罗二先生诗后 其二","f":"古风","c":["金牛洞口春色，观生居畔秋声。","彻底与君拈出，前山雨过云生。"]},{"t":"和一峰入道门","f":"五言律诗","c":["道牖无开阖，天阊在寸心。","琅然丝竹启，不但有清琴。","孝友春云沃，中和海岳深。","金枢才一转，九折任幽寻。"]},{"t":"和一峰读书楼","f":"五言律诗","c":["竹户绿光迥，疏窗素影幽。","曲通邀月径，直上摘星楼。","片字非虚设，孤心自泳流。","陈言皆此日，无往不天休。"]},{"t":"和一峰扇和岩","f":"五言律诗","c":["世故争欲暮，吾生始试春。","居然从古哲，莞尔笑时人。","月转群山曙，莺啼一苑新。","老来知此意，即次认天真。"]},{"t":"和一峰一览亭","f":"五言律诗","c":["生余当此日，涤目埽昏烟。","掘幸前贤在，高居未有边。","道香原在鼻，银气漫熏天。","颜孔乐何事，閒游岂自然。"]},{"t":"和白沙梅花 其三","f":"五言律诗","c":["天地机方息，此花不暂閒。","斜阳熏橤破，冻蝶饱香还。","浅水寻犹远，高枝折未难。","壸天麟髓浃，何必问神山。"]},{"t":"和白沙怀古","f":"五言律诗","c":["伏羲枕上皇，靖节不荒唐。","浇酒巾犹湿，当篱菊巳香。","云飞从鸟倦，苗长记农祥。","天地悠悠里，春风正未央。"]},{"t":"和白沙 其七","f":"七言绝句","c":["五位一丝七日复，六爻全用九三乾。","江门不卖閒风月，月白风清总未然。"]},{"t":"次康节韵质之","f":"五言律诗","c":["俄顷仍千岁，天心常转移。","六龙飞不息，三极各乘时。","有画皆成象，无声不是希。","谁将华顶睡，迢递赠庖羲。"]},{"t":"见狂生诋康斋白沙者漫题","f":"古风","c":["任尔舌尖学语，谁知趺下生根。","一线经分子午，双钩画破乾坤。","逼窄墨台狭路，萧条原宪柴门。","天下古今几许，梨花春雨黄昏。"]},{"t":"读易赠熊体贞孙倩 其一","f":"古风","c":["澄宇既涤，清霜欲飞。","天地居然，云胡以窥。","勿庸遐瞩，道岂远而。","物生必偶，心动则奇。","物无不应，心无不几。","遇成秩叙，否必参差。","雷风日月，载此为仪。","孰敢自康，吉凶不违。"]},{"t":"读易赠熊体贞孙倩 其二","f":"古风","c":["油云在天，舒卷不齐。","随风而东，歘尔还西。","或飞甘雨，或散虹霓。","君子攸行，不害先迷。","经历纷纠，如取如携。","比干殉殷，夷吾相齐。","昏旦殊星，燕粤殊蹊。","移之分寸，徙宅忘妻。","哀哉群动，莫之能稽。","百草陨芳，鶗鴂先啼。","所以灵氛，告尔天倪。"]},{"t":"读易赠熊体贞孙倩 其三","f":"古风","c":["自我徂冬，元夜其修。","晨光警曙，肃肃衾裯。","我身则痡，我心则悠。","潜与化寻，敢侈天游。","遂历韶春，言迄凛秋。","物不我遐，化不我浮。","俄顷有枢，谁云迁流。","六龙之辔，遍乎九州。","因之致远，抑又何求。"]},{"t":"读易赠熊体贞孙倩 其四","f":"古风","c":["大圜如规，旦昏各半。","道枢不留，气毂时转。","理随象宣，通于一贯。","如镜取影，但窥其面。","坤不外生，乾非中窜。","其去非亡，其来非幻。","屯隐四阳，鼎阴未现。","非有有无，唯徵舒卷。","静言念之，即经为变。","险易盈虚，穷通萃涣。","岂不我繇，何为外眩。"]},{"t":"读易赠熊体贞孙倩 其五","f":"古风","c":["文王既没，文其在兹。","赫赫明明，有彖有辞。","志非所问，义著于蓍。","日不可炀，天不可帷。","宵人窃烛，不照须眉。","周道茂草，别趋路歧。","弄方如砌，画圆如规。","星历相窜，巫觋是师。","天化地产，玩如行棋。","以谋羹炙，以询淫嬉。","神所不告，覆讥其违。","修吉悖凶，天鉴在斯。","皇天弗尚，吾为尔危。"]},{"t":"读易赠熊体贞孙倩 其六","f":"古风","c":["昨日之日，为今日先。","荏苒来兹，仰今为缘。","有象皆后，理亦无前。","华山有叟，胎息密传。","谓天为后，别有先天。","秘相授受，玩弄清元。","划破乾坤，符火争权。","我无羽翰，乘风而仙。","居天之后，奚用此焉。","雒阳看花，天津闻鹃。","归之气数，莫匪自然。","人用以废，天枢不圆。","采苓首阳，其尚舍旃。"]},{"t":"读易赠熊体贞孙倩 其七","f":"古风","c":["脂我神舆，游于太虚。","太虚匪虚，充塞无馀。","火来阳燧，水赴方诸。","水火无间，况道之储。","荠麦夏成，款冬冻舒。","摩荡无方，各含道腴。","匪车何轴，匪户何枢。","六龙并辔，互惜其珠。","行地无疆，良哉骏驹。","哂彼曲学，谓之乘除。","心不可游，道不可拘。","庶几夙夜，警我顽愚。"]},{"t":"读易赠熊体贞孙倩 其八","f":"楚辞体","c":["悠悠我生，去日巳长。","怀我友朋，墓草芸黄。","父兮生我，罔极昊苍。","莫宝匪命，含柔含刚。","乾龙坤马，历历肾肠。","日用不知，虽哲而狂。","不耕之农，蚀彼稻粱。","崦嵫既迫，朽骨空藏。","亦既邂逅，矧敢斁忘。","荆棘是芟，庶显康庄。","多言为尤，自疚不臧。","惟抒我忱，荐其悚惶。"]},{"t":"示从游诸子三首 其一","f":"七言律诗","c":["七载相怜巳久如，寸心未展祗相于。","诸君怀玉空弹鹊，老汉直钩尽钓鱼。","大易圈叉唯父母，上天时物在诗书。","勿劳载酒询奇字，便草元文亦子虚。"]},{"t":"示从游诸子三首 其二","f":"七言律诗","c":["千林潇洒试金风，万里秋清一夕中。","正好腰镰收玉粒，不妨停辔看霜红。","层层剥笋方逢肉，缕缕穿针未损绒。","欲遣平皋新雨透，先将利剑断雌虹。"]},{"t":"示从游诸子三首 其三","f":"七言律诗","c":["今人笑古古笑今，笑将在口或在心。","携杖穿云云不惹，褰衣涉水水何深。","他人有梦难代说，夜半索枕自幽寻。","莫拟船山如布谷，斜阳高树认归禽。"]},{"t":"正落花诗十首 其一","f":"七言律诗","c":["弱羽殷勤亢谷风，息肩迟暮委墙东。","销魂万里生前果，化血三年死后功。","香老但邀南国颂，青留长伴小山丛。","堂堂背我随馀子，微许知音一叶桐。"]},{"t":"正落花诗十首 其二","f":"七言律诗","c":["锦阵风雌夺葆幢，万群茶火怯宵摐。","烧残梁殿缃千帙，击碎鸿门玉一双。","十里荷香消汴梦，三山芳草送吴降。","扬州婪尾春犹在，小住何妨眷此邦。"]},{"t":"正落花诗十首 其三","f":"七言律诗","c":["蒸云暄日尽淫威，小槛低檐判不肥。","丰草但荣时则可，啼禽空絮是耶非。","枝枝叶叶苏君在，燕燕飞飞戴女归。","昨梦不成仙径杳，盈盈一曲问津稀。"]},{"t":"正落花诗十首 其四","f":"七言律诗","c":["游魂化密故饶甘，怕扇蜂潮闹不堪。","忧寄上天埋下地，云迷泽北梦江南。","吾何随尔累累子，我醉欲眠栩栩酣。","时向天台亲报佛，春愁痴在早除贪。"]},{"t":"正落花诗十首 其五","f":"七言律诗","c":["昔昔回头艳已轻，苔情欲薄藓相迎。","香遮蚁径迷柯郡，雨浥莺声唱渭城。","旁砌可能别有主，依萍取次但怀清。","陌桑曲柳空相识，我自非卿卿自卿。"]},{"t":"正落花诗十首 其六","f":"七言律诗","c":["捲得垂帘试捲帘，元来犹剩一枝尖。","逗红髣髴回塘远，坠玉参差曲岸添。","泯泯春流愁画鹢，娟娟疏影妒银蟾。","悬铃买槛皆畴昔，好擭香须远蝶嫌。"]},{"t":"正落花诗十首 其七","f":"七言律诗","c":["赌命奔尘掷一绯，千秋何有大椿围。","争天晴雨邯郸帜，死地合离玉帐机。","周易击蒙凶不吝，春秋雠战义无讥。","朱殷十步秦台血，耻向青阳赋式微。"]},{"t":"正落花诗十首 其八","f":"七言律诗","c":["飘零无意反离骚，谱牒宜收倩谢翱。","意北意南心自得，如鸥如鹜卜何劳。","三更露冷清同滴，片月天低影倍高。","寂寞琴心传止息，花奴莫弄小儿豪。"]},{"t":"正落花诗十首 其九","f":"楚辞体","c":["歌亦无声哭亦狂，魂兮毋北夏飞霜。","蛛丝罥迹迷千目，燕啄香消冷一房。","世少杜陵怜李白，卬须唐珏葬姚黄。","蓉城倘有华胥国，半枕留仙我欲杭。"]},{"t":"正落花诗十首 其十","f":"七言律诗","c":["高枝第一惹春寒，低亚密藏了不安。","作色瞋风凭血勇，消心经雨梦形残。","三分国破楝心苦，六尺孤存梅豆酸。","薄命无愁聊妩媚，东君别铸铁为肝。"]},{"t":"续落花诗三十首 其一","f":"七言律诗","c":["映水低垂带影双，情来奔影委流淙。","浮浮终隔相思浦，去去空沿解佩江。","轻薄自矜云想袂，閒愁无那客临窗。","怀贞唯忆东篱伴，青女相邀死不降。"]},{"t":"续落花诗三十首 其二","f":"七言律诗","c":["青门祖帐太荒淫，春已迷阳可陆沈。","蹑险拟看没字碣，涉园聊对无弦琴。","梅知解绂宜名福，华不挥金旧是歆。","风御泠然踪迹远，但凭罔象试追寻。"]},{"t":"续落花诗三十首 其三","f":"七言律诗","c":["啼禽屡说不如归，占取三休第一机。","莫管柳枝穿鼠臂，但随陵舄化蛙衣。","幔亭锦绣仙何有，宝塔珠璎佛亦非。","流水还沾馀粉在，迷香仍使寸丹违。"]},{"t":"续落花诗三十首 其四","f":"七言律诗","c":["春老谁生此宁馨，流霞妒色月争衡。","无愁綵仗迷天子，不夜春城背日兄。","泉涌珠玑供涕唾，河倾金桂事煎烹。","临风一笑酸寒叟，酷爱秋英得久名。"]},{"t":"续落花诗三十首 其五","f":"七言律诗","c":["雌黄削迹罢参订，几问姚皇判尹邢。","炎德已成编腐史，白华无字上葩经。","春光漫数六身亥，月影无疑有尾丁。","偷眼蜻蜓今远害，人寥天一学鸿冥。"]},{"t":"续落花诗三十首 其六","f":"古风","c":["轻盈无问少年时，脱卸?珑老更奇。","鹅鹳鱼丽随羽扇，朱干玉戚转旌麾。","惭惶剪綵寻行墨，杜撰空花拟合离。","无数春风拘不得，掀翻萟圃更凭谁。"]},{"t":"续落花诗三十首 其七","f":"七言律诗","c":["将军畦下久归来，狄相门前有未开。","吾与尔夫分用舍，公无困我试风雷。","黄冠紫陌千株菜，赵女南山一顷萁。","拾取残英能几客，杏坛凋谢赴王骀。"]},{"t":"续落花诗三十首 其八","f":"七言律诗","c":["宿莽馀芳总一邱，安能郁郁望山头。","人分南北朕焉往，目异关河我始愁。","谁与虫尸忙万蚁，聊拚颈血跃双钩。","到来瓜蔓残枝在，花雨台前粉黛秋。"]},{"t":"续落花诗三十首 其九","f":"七言律诗","c":["有时寂寞坠閒云，忽尔如惊舞鹤群。","陆海潘江皆锦浪，易奇诗正各丹坟。","无劳粉本摹春雪，一尽零香酿夕醺。","肉眼不知看活色，寻苔捕草漫纷纭。"]},{"t":"续落花诗三十首 其十","f":"七言律诗","c":["蝶懒莺慵燕自谙，怪来春睡付朝酣。","香烟专宠今无敌，屐齿欺红了不惭。","九转丹飞殷七七，再来果莂后三三。","含情留得真真影，蹑上吴王八茧蚕。"]},{"t":"续落花诗三十首 其十一","f":"七言律诗","c":["滥试东君清夜游，曼延初罢进藏钩。","摇槌急点黄幡绰，面具妖装圣兽头。","金豆纷纭抛玉甃，银船历乱倒香帱。","双鬟何似吟秋水，云汉胭脂浣腻流。"]},{"t":"续落花诗三十首 其十二","f":"七言律诗","c":["彩云歘倏散还休，款款萦萦倍惹愁。","嫩蝶攀援疑借蔻，狂蜂轻薄讵安榴。","徒钻故纸唯糟粕，欲埽讹书苦挍雠。","一洗青林烦夜雨，白蘋碧杜亦芳洲。"]},{"t":"续落花诗三十首 其十三","f":"七言律诗","c":["道傍荷锸笑劳劳，使速营邱泥似糟。","身世无馀鸿过雪，人天莫问雨成刀。","偶来震旦何人国，漫展云衣某甫皋。","一笑自将船子棹，曲终不见杳春涛。"]},{"t":"续落花诗三十首 其十四","f":"七言律诗","c":["情与非情法喜图，清欢禅悦有中无。","不容迦叶称初祖，微许林逋作故夫。","春有秋心消蚁梦，跃含潜理戏骊珠。","知音近托虞僧孺，溪上閒吟影共癯。"]},{"t":"续落花诗三十首 其十五","f":"七言律诗","c":["为欢凡几恨偏长，九夏三秋未遽忘。","萤作流人悲故苑，燕如归妾忆新妆。","鹊桥难乞春留巧，蟾魄空圆影失香。","桃李明年知别用，一匙社饭好思量。"]},{"t":"续落花诗三十首 其十六","f":"七言律诗","c":["崛起争寒寒不胜，春风得意忍凭陵。","三分无德依残萼，一木空扶笑古藤。","香埽归涂偷日射，魂随云路梦天登。","青阳王气今阳九，花史新书上坠崩。"]},{"t":"续落花诗三十首 其十七","f":"七言律诗","c":["迟暮閒情看一围，衿沾疏雨晾斜晖。","聊过柳径邀轻絮，共趁鞦韆竞舞衣。","芡叶几留耽宛转，桃饧欲惹滞霏微。","相逢歧路莫相妒，曾共西园听秭归。"]},{"t":"续落花诗三十首 其十八","f":"七言律诗","c":["珊珊欲下故来迟，卖眼惊飙万片齐。","绛雪回风依树急，繁星陨雨贴天低。","三春捲土终无计，尽日何心独向西。","恋萼黏须无限恨，悬知此去隔云泥。"]},{"t":"续落花诗三十首 其十九","f":"七言律诗","c":["狡狯苍天可谥荒，抛红日掷万钱忙。","小儿强汰閒情赋，颠史痴湔藻火裳。","甲煎香倾熏夜帐，鱼镫蕊灺閟阴房。","勾芒倘课春功最，罪过风流故态狂。"]},{"t":"续落花诗三十首 其二十","f":"七言律诗","c":["车笠公欺竹柏盟，翩翩故学魏收惊。","雕虫投阁羞童子，傅粉全躯愧老生。","竞赛新缣愁旧素，欲芟白俗奈元轻。","纷纷半入江云去，别搆人閒一锦城。"]},{"t":"续落花诗三十首 其二十一","f":"七言律诗","c":["剩粉莫矜夙习妍，段师弃尽旧鹍弦。","秾华制改西昆体，老大名留南部烟。","旧爱新愁分一艳，身前影后得多怜。","愁予眇眇云中子，卸取徐妃半面钿。"]},{"t":"续落花诗三十首 其二十二","f":"七言律诗","c":["黄紬晨放锦官衙，队仗来回静不哗。","开阁朱殷添画棨，拥堤香软擭平沙。","双緌蝉翼飘轻带，百首鸡胸吐绶緺。","蛱蝶胡孙劳庆吊，香车明日过谁家。"]},{"t":"续落花诗三十首 其二十三","f":"七言律诗","c":["漫天撇地莫相嘲，谁向春风得系匏。","入幕髡留依画烛，同尘颐指听吟鞘。","梅交隙末损三友，果筮离群剥上爻。","和露倚云争早晚，芳兰何事把琼茅。"]},{"t":"续落花诗三十首 其二十四","f":"七言律诗","c":["旁午争迎社燕斜，参差月影乱啼鸦。","新虹滥赐缠头锦，蛛网曾封系臂纱。","自捉狂夫誇拂舞，不知迁客怨琵琶。","定谁解作微尘观，细看双鱼蹴浪花。"]},{"t":"续落花诗三十首 其二十五","f":"七言律诗","c":["煽艳三风如此膴，濡轮曳尾胡为乎。","三英秀岂留朝菌，十里山聊远蟪蛄。","天已丧文悲凤凤，人皆集菀忍乌乌。","浮湘特吊蓉裳客，鶗鴂先鸣鵩止隅。"]},{"t":"续落花诗三十首 其二十六","f":"七言律诗","c":["老饕排设待煎酥，铁脚生吞气愈粗。","白小祸枢延草木，飞鸿生趣在江湖。","脱离蛛网文亡害，徼幸蜂王税可逋。","犹有馀香飘一缕，怕留踪迹索倪迂。"]},{"t":"续落花诗三十首 其二十七","f":"七言律诗","c":["载美千秋让子皮，锦泾娃馆亦奚为。","杜陵赤甲诗偏苦，挍尉燕支数屡奇。","椒殿恩轻除阁画，鸡坊人老忆园梨。","流莺唤醒樱桃梦，高座谈经香雨垂。"]},{"t":"续落花诗三十首 其二十八","f":"七言律诗","c":["云裾雪袂故心空，剪綵镂金莫恼公。","瓦雀学成双影转，来禽分得半腮红。","夜深镫谢收兰烬，曙月光残捲桂丛。","留取扶疏邀沆瀣，胶青一色写春融。"]},{"t":"续落花诗三十首 其二十九","f":"七言律诗","c":["莲冠何碍切云游，鸠眼无端侧目愁。","绣口久知压沈宋，梅羹向后任孙刘。","白荼红蓼今承乏，燕麦龙葵旧有秋。","乞我逍遥名亦辱，桑条裾惹断云羞。"]},{"t":"续落花诗三十首 其三十","f":"七言律诗","c":["攀条不耐冶游馋，绝世幽情早自缄。","莺绿尊前除卯酒，猩红桥上谢春衫。","南枝先挂西归履，一叶轻飞万里帆。","闭死玉棺嗤叶令，蜕香何似碧天函。"]},{"t":"广落花诗三十首 其一","f":"七言律诗","c":["惠风习习柳阴阴，只此閒愁警客心。","昔以视今悲曲水，物犹如是奈江浔。","素筝如怨歌珠断，玉斝疑催烛泪深。","乱扑红颜都不省，待沾华发可知音。"]},{"t":"广落花诗三十首 其二","f":"古风","c":["万斛春膏烂似糜，镇将黄叶恼婴儿。","吴王洲上英雄泪，工部潭前客子悲。","隙影早知同塞马，锦衣何用慕文牺。","平泉过眼空苔石，竹?还堪乐凤饥。"]},{"t":"广落花诗三十首 其三","f":"七言律诗","c":["情知不住若为留，顾我嫣然笑上头。","春老无人随少府，风欺一倍感商州。","寒禁荇藻凭鱼计，傲寄茱萸缓客愁。","祖绿帝青添几色，新阴还得醉双眸。"]},{"t":"广落花诗三十首 其四","f":"楚辞体","c":["我所思兮在桂林，征鸿回翼杜鹃瘖。","荔丹谁遣霜风吹，珊紫长依海水深。","言鸟娇能怜蔻孕，舶香妒不损檀心。","从过庾岭闻羌管，雨替风凌直到今。"]},{"t":"广落花诗三十首 其五","f":"七言律诗","c":["踏草情阑长绿苔，南园近日赏心灰。","红牙倦理迎头拍，绿髓唯倾婪尾杯。","茵聚凭将挥蜀锦，蜡封留取贮商罍。","典刑犹在谁堪托，玉茗聊看隔岁胎。"]},{"t":"广落花诗三十首 其六","f":"七言律诗","c":["春王推戴诧魁功，生杀乘权速转蓬。","落魄早知亏月满，取精应悔竭春忠。","杨梅孔雀丹心别，金谷河阳白首同。","新绿可知霜刃在，尽情还与逼残红。"]},{"t":"广落花诗三十首 其七","f":"七言律诗","c":["等是殉春亦待勘，摽梅难比二桃甘。","风流有主堪捐佩，雨涕无从得解骖。","蓂荚两阶辞舜殿，芳兰九畹萎江潭。","汤阴衣溅丹痕苦，僵李徒劳代亦惭。"]},{"t":"广落花诗三十首 其八","f":"七言律诗","c":["桃蹊莫但惜春过，任遣馀芳恨亦多。","月白风清秋不浅，参横斗转夜如何。","丹枫万点飘霜紫，残雪千峰消素螺。","临水登山皆荐泪，定情意不在双蛾。"]},{"t":"广落花诗三十首 其九","f":"七言律诗","c":["并门闭目奈愁生，幔捲帘垂两不平。","百岁回头三月雨，万端到耳一声莺。","贯休死爱香风吹，和靖难忘疏影横。","删抹艳根须有此，荷丝虽铩也相萦。"]},{"t":"广落花诗三十首 其十","f":"楚辞体","c":["飞光煎寿簸英雄，鬼艳仙才委巷风。","白也魂归关塞黑，虞兮骓泣固陵红。","玉楼赋笔还天上，铁束经函锢井中。","多幸天年樗眼白，微眠长日据毡绒。"]},{"t":"广落花诗三十首 其十一","f":"古风","c":["蜀国海棠七宝妆，扬州红药一楼香。","阿?夜葬雷塘曲，花蕊春望玉垒长。","雨意迷留争冷㬉，云鬟消受到兴亡。","阅人多矣青青树，猎取秦封偃盖凉。"]},{"t":"广落花诗三十首 其十二","f":"七言律诗","c":["万重妒垒逼斯文，大野天穷吐玉麇。","谁解喟然叹点尔，但逢兴也即笺云。","狂歌唯哭支离叟，酹酒相邀冥漠君。","寂寂仲华应笑我，云台春老不书勋。"]},{"t":"广落花诗三十首 其十三","f":"七言律诗","c":["乾净青莎一片阴，君无去此豢饥禽。","人生自古皆惶恐，天下如今半绿林。","曀日终风舟汛汛，水深河大雨淫淫。","旧家枝叶同乡土，好听黄鹂作羽吟。"]},{"t":"广落花诗三十首 其十四","f":"七言律诗","c":["止竟须飞悟得无，荣期春去亦童乌。","寒催直北沙如雪，㬉浥江南雨似酥。","画槛铪流讥乳鸟，青坰金涩恣骄驹。","零红堆绣双寂寞，张单何为各守株。"]},{"t":"广落花诗三十首 其十五","f":"七言律诗","c":["寻向水边山外山，轻烟羃䍥有无閒。","才过杨柳阴阴岸，又度茱萸曲曲湾。","小憩愈愁前路杳，向来悔不隔墙攀。","归迟怕被游人笑，摘得青条带叶还。"]},{"t":"广落花诗三十首 其十六","f":"七言律诗","c":["棘罥苔缄蟢网封，还披密筱问遗踪。","三山空在云千里，九处堪疑翠几重。","菡萏魂留霜粉腻，蔷薇髓滴露香浓。","楚宫梦巳无寻处，祇对巫阳暮雨峰。"]},{"t":"广落花诗三十首 其十七","f":"七言律诗","c":["色香之外有谁能，妙影轻姿记得曾。","几点烟横吹雁字，一江风起乱渔镫。","云根无托依贫士，软触难忘恼定僧。","世出世中俱不受，六铢衣界自飞腾。"]},{"t":"广落花诗三十首 其十八","f":"七言律诗","c":["消心独有艳难删，游戏无端偶破颜。","莲社带醺逃梵网，华阳掞藻耻仙顽。","挥弦送目随归雁，见月开笼放白鹇。","此意非然非有自，鸿沙羚角故相关。"]},{"t":"广落花诗三十首 其十九","f":"七言律诗","c":["岸移月驶定谁真，花住花飞臂屈伸。","奔马难追昨日影，神舆早属后车尘。","霎时雨警三更梦，大力舟藏万壑春。","认得白沙诗句好，刘郎莫问旧渔津。"]},{"t":"广落花诗三十首 其二十","f":"七言律诗","c":["款款分明下砌除，燕捎风起漾池墟。","参差难采中流荇，游泳空邀静夜鱼。","柳缆无因维野马，蛙吹何当享爰居。","同心唯有青天月，到处相逢影一如。"]},{"t":"广落花诗三十首 其二十一","f":"七言律诗","c":["今夕何夕春云徂，子规啼月宵欲孤。","银烛一夜烧易尽，珊鞭诘旦踏巳无。","后日青枝献生子，当时綵胜浇屠苏。","榆钱虹锦买不住，何况十万铜青蚨。"]},{"t":"广落花诗三十首 其二十二","f":"七言律诗","c":["杜陵颠狂恼不休，涪翁含笑增春羞。","他春未必如此日，枝上而今已陌头。","青山一静似太古，黄葛虽鲜难顺流。","韶光转毂无终极，辨此何为不散愁。"]},{"t":"广落花诗三十首 其二十三","f":"七言律诗","c":["天涯天涯予安归，金门绣岭春事非。","元鹤毳羽昔君子，班管晕痕旧帝妃。","弥天无土葬香骨，过雨有人拾象玑。","浪游沧海意不息，为倩东风击蝶衣。"]},{"t":"广落花诗三十首 其二十四","f":"七言律诗","c":["鸣鸠乳燕欢晴酣，清晓蹑屐补春探。","半塘影失谓萍乱，曲岸香添疑鸟含。","回头冷蕊开无赖，拂袖狂红委不堪。","小阁莞尔语蚕妾，唯汝柔桑独蔚蓝。"]},{"t":"广落花诗三十首 其二十五","f":"七言律诗","c":["息夫人看终不言，黄四娘家扑满轩。","柳绵团马㬉如意，梅影啼禽冷彻魂。","云中任逐淮南犬，腐草宁归浈峡猿。","百舌珊瑚不称意，凋伤浪为呼烦冤。"]},{"t":"广落花诗三十首 其二十六","f":"七言律诗","c":["江渚山椒洽比邻，分飞接迹劳逡巡。","关河万里戎王子，楚汉千年虞美人。","沈炯自泣茂陵树，庾信长哀江南春。","人间有恨皆摇落，那向西园泪眼频。"]},{"t":"广落花诗三十首 其二十七","f":"古风","c":["高田小麦凋穗黄，君胡?蹀理征裳。","春江劳劳客易散，秋渚迢迢夜未央。","绠断银瓶空井底，瑟分玉柱愁高张。","海山家在莺啼处，无计日归空黯伤。"]},{"t":"广落花诗三十首 其二十八","f":"七言律诗","c":["风末雨馀悄欲停，须臾如慕诉春听。","白日不肯香流水，黄昏取次乱飞萤。","舜华得计避霜色，汉柏偶尔逃天刑。","三归台上荡舟相，旖旎居然天性灵。"]},{"t":"广落花诗三十首 其二十九","f":"七言律诗","c":["嬴皇兀山辇金埋，千春粉黛消秦淮。","芙蓉无数蚀宝剑，鸳鸯岂但坼金钗。","三月通闰只紫莽，五色欲补谁皇娲。","一声举棹唱年少，玉树歌终泣越娃。"]},{"t":"广落花诗三十首 其三十","f":"七言律诗","c":["昔日家园春始阑，祫衣爱点丹鳞蜿。","软尘从踏青门道，绀雪频侵霜剑寒。","渐老巳拚消槁木，送愁无那翻红湍。","寒潮暄晕青皋路，干梦如泥不耐看。"]},{"t":"寄咏落花十首 其一 元理","f":"楚辞体","c":["听之无闻杳希夷，可左泛兮可右移。","丹灶烟轻飞武火，明窗尘细弄婴儿。","动而愈出弱频用，失亦若惊辱较宜。","气母欲抟抟不得，流珠常惜去人时。"]},{"t":"寄咏落花十首 其二 元理","f":"七言律诗","c":["或奔月窟或天根，云鬓晨晞玉女盆。","榆筴含刑月在卯，黄芽出险卦临屯。","流乌亭午无留影，顾兔中宵失暗痕。","一笑三峰痴姹女，残脂断粉弄精魂。"]},{"t":"寄咏落花十首 其三 禅宗","f":"七言律诗","c":["藤倚芦交两不关，星星石火迸斑斓。","一时齐现∴三点，诸品无馀道入还。","枯木何妨春色㬉，絮泥却遣柳枝鳏。","牛头鸟散无消息，柏子庭前翠色閒。"]},{"t":"寄咏落花十首 其四 禅宗","f":"七言律诗","c":["若人以色以声求，捏目空中乐主楼。","安养霎时清旦雨，双林依旧夜星流。","狮王乱击红颜定，鹙子难忘芳饵钩。","为问灵云能再见，刹竿正倒不须愁。"]},{"t":"寄咏落花十首 其五 书品","f":"七言律诗","c":["下帷空闭仲舒园，入幔偏依写韵轩。","硬拓云麾蝉翅薄，偷临天马袅蹄翻。","回波斜展侵飞白，钗脚低垂带漏痕。","闪霍纤腰频敛锷，祇应浑脱学公孙。"]},{"t":"寄咏落花十首 其六 绘事","f":"七言律诗","c":["连枝多事笑边鸾，蛇足黄荃夹羽翰。","巧染一红修竹倚，閒添数蝶马蹄安。","赤龙睛点欲飞去，并剪霜裁得半看。","可是所南悲地坼，空中幻出国香残。"]},{"t":"寄咏落花十首 其七 坐隐","f":"七言律诗","c":["疏从掠势密侵边，一道斜飞绰欲仙。","小径贪肥成聚五，南枝得意占长先。","倾筐七子垂能几，买槛千金坠可怜。","桐井正翻辘轳影，猧儿蹴损不成妍。"]},{"t":"寄咏落花十首 其八 觞政","f":"七言律诗","c":["㬉酿云封香不扃，半拖帘影出郊亭。","一江酣熟宜中圣，万岁春阑且劝星。","病叶懒飞相枕藉，晕潮新上舞娉婷。","梅霪消尽石榴后，罍耻还倾酢百瓶。"]},{"t":"寄咏落花十首 其九 剑技","f":"七言律诗","c":["峭寒生倚老拳狂，残月如探赤弹忙。","白打翻腾矜鹞翅，红妆绰约罩梨鎗。","排场别样飞绳技，黄阁微酡效拍张。","朱影半星挥雪练，一丝血缕染轻霜。"]},{"t":"寄咏落花十首 其十 货殖","f":"七言律诗","c":["步障雄誇十里图，销镕日夜费洪垆。","绛缠秦树王元宝，黄泻河流冯子都。","罂粟红陈身化蝶，榆钱贯朽血归蚨。","锦官辇载劳春驾，未必千金不死涂。"]},{"t":"落花诨体十首 其一","f":"七言律诗","c":["游蜂大嚼过屠门，又顾他家郭外墦。","唐突西施从喝道，诙谐南阮任摊裈。","摧香麝父同羌管，杀景酪奴傲酒尊。","生遣红裙嗤白苧，莲芳何在枣甜存。"]},{"t":"落花诨体十首 其二","f":"七言律诗","c":["隔院投梭作意憨，当筵脱裤太无惭。","中流惊剪支腮赤，黄阁愁逢满颊蓝。","棠棣有兄皆四海，金钱疑鬼耗双南。","堪哀堪笑都如此，谱入悲田细与勘。"]},{"t":"落花诨体十首 其三","f":"七言律诗","c":["将谓抛馒接建章，糖毬团粉两郎当。","低棋子下千林雨，趁韵诗成夏日霜。","酒伴赏阑秦客逐，园丁趋视宋人芒。","狂奔一夜投夭棘，七子空怀黄鸟伤。"]},{"t":"落花诨体十首 其四","f":"七言律诗","c":["苍跸将旋趱急差，程程透夜走金牌。","夕飙苦奏三声角，雨点先催两部蛙。","棘矢桃弧争荜路，丁香豆蔻总琼厓。","溪流难润追阳渴，驿路春风轮可埋。"]},{"t":"落花诨体十首 其五","f":"七言律诗","c":["一片青郊战马悲，牧童难认酒家旗。","衣裳云想俄苍狗，剑佩星迎总雪狮。","花史拟修濡秃笔，骊歌欲唱咏删诗。","待拚烂醉忘离苦，乌有青州一漏卮。"]},{"t":"落花诨体十首 其六","f":"七言律诗","c":["艳籍黄消饱白蟫，文章水面付浮沈。","风狂矮李思扪汉，雨苦寒荠学捧心。","锦缕毒逢骄妇笑，娇英嫩死屠门瘖。","莫誇黑牡丹无恙，斛角还逢鼷鼠侵。"]},{"t":"落花诨体十首 其七","f":"七言律诗","c":["戏来真不惜惊鸳，浪打飞丸恼鸭魂。","风箔一天金世界，藕丝几孔鬼乾坤。","无端破瑟分清怨，未必闻琴亦夜奔。","见说武皇春阵别，红裙撩乱蹴狂髡。"]},{"t":"落花诨体十首 其八","f":"七言律诗","c":["禁得寒暄几度移，热时且趁笑垂垂。","真成草偃迷南北，浪借风吹莽唱随。","病里观涛为客起，酒醒谢妓怕天知。","芙蓉漫道真君子，只恐奔车无伯夷。"]},{"t":"落花诨体十首 其九","f":"七言律诗","c":["金钱且卖晓来红，笑杀优昙老冻脓。","葵足偶然逃羿彀，蜂脾宁我负彭虫。","河豚拚得杨花命，磨蝎生逢驿马宫。","莫为舜华悲寿夭，草间活者白头翁。"]},{"t":"落花诨体十首 其十","f":"七言律诗","c":["司春眯目脑冬烘，曳白教飞十里红。","三五阿婆曾莽撞，八千泪眼尽寒穷。","昌图驴弱宫袍涴，贾岛坟乾金粟空。","毷□曲江聊一打，韶光落魄意偏雄。"]},{"t":"补落花诗九首 其一","f":"七言律诗","c":["乘春春去去何方，水曲山隈白昼长。","绝代风流三峡水，旧家亭榭半斜阳。","轻阴犹护当时蒂，细雨旋催别树芳。","唯有幽魂消不得，破寒深醴土膏香。"]},{"t":"补落花诗九首 其二","f":"七言律诗","c":["棋声院静缀苔匀，柳色楼高点幕频。","开径雨馀遮草嫩，捲帘寒浅送香新。","重拈欲辨开时树，细数凭占几日春。","直待深阴藏宿鸟，循蹊犹觅锦鳞鳞。"]},{"t":"补落花诗九首 其三","f":"七言律诗","c":["生不辜春死亦香，飞蓬坠箨漫轻狂。","笑人云袂仍泥滓，奈此瑶肌夹雨凉。","樾馆无心随上甃，仙舟有约屡依樯。","江干鹤瘗千秋伴，共怨人间甲子忙。"]},{"t":"补落花诗九首 其四","f":"七言律诗","c":["又见扶桑一度凋，閒愁无奈只春宵。","珊枝沈海初无叶，梦草游仙旧有苗。","敲髓何方寻白獭，留香不久驻虹桥。","似闻旌节开天上，望里云关谢豹骄。"]},{"t":"补落花诗九首 其五","f":"七言律诗","c":["记得开时事已非，迷香逞艳衒春肥。","尽情扑翅欺蝴蝶，塞耳当头叫姊归。","桃李畦争分咫尺，松杉云冷避芳菲。","留春不稳销尘土，今日空沾客子衣。"]},{"t":"补落花诗九首 其六","f":"七言律诗","c":["情到苍天了不关，酸风铅泪射朱颜。","荒邱自古为华藏，白骨从今改翠鬟。","铜雀香分尊酒帐，锦帆枫冷苧萝山。","东飞燕子成何事，长日犹营旧垒间。"]},{"t":"补落花诗九首 其七","f":"七言律诗","c":["莫将旧价问千金，下砌萧萧败叶侵。","万紫向来空识面，寸丹何地觅知音。","梅魂不分春霪苦，荷怨难平晓露深。","脉脉菱花别有意，青铜留照阅来今。"]},{"t":"补落花诗九首 其八","f":"七言律诗","c":["应迹秾华早出泥，知音丈室净名妻。","宝簪不上团花髻，锦片长随采药溪。","凤翥有心依竹叶，蝶飞无色上棠梨。","逸情交臂多相失，求兔何劳问旧蹄。"]},{"t":"补落花诗九首 其九","f":"七言律诗","c":["来何所见去何闻，侬自珊珊岂为君。","南北东西谁国土，青黄赤白旧斯文。","静怜彩色惊朝日，远引閒情入晓云。","掷与馀芳遮世眼，逐香劳尔嗅氤氲。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其一","f":"七言律诗","c":["儿戏抟沙造化工，杨花飞雪舞来同。","东晴西雨双虹断，海鲞江鲥四月通。","有兴但抛棋一劫，无情凭唱曲三终。","清风半港留难住，笑尔诙谐柰尔穷。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二","f":"七言律诗","c":["情丝未剪不嫌痴，槌板留歌薤露辞。","针劄古锥深见血，线分绒缕细成丝。","踏残马足霜寒后，叫到鹃瘖月落时。","元是百花尖上雨，春归凭此泫青枝。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三","f":"七言律诗","c":["龟蒙未畜解言鸡，仲子难栽旁井薇。","莫向楚秦伸屈指，繇来籧戚冒妍皮。","纵横诸界天皆窄，抹直前头路不疑。","腊月南窗西涧菊，何须粉本拓皇羲。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四","f":"七言律诗","c":["南郭有心非槁木，东方果腹亦侏儒。","金篦不刮鸬鹚眼，砮矢还留鸿雁书。","临济老拳石勒饱，沩山苗稼宋人愚。","鸥生鹜死区区外，别灼龟毛问卜居。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五","f":"七言律诗","c":["不是好山看不得，西湖游只许白苏。","出缁人素人惊犬，洗髓伐毛我丧吾。","雪色一天屯冻猬，秋声万顷讯寒蛄。","谁知落月金风里，荡漾予魂脱影逋。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六","f":"七言律诗","c":["生缚奉先双腕急，曹瞒未是出群才。","已知辖凤妖翎幻，难割泥龙左耳乖。","覆醢铜青蚀铁骨，无盐水墨写桃腮。","千寻偃盖秦封树，总给寒垆一夜柴。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七","f":"七言律诗","c":["千顷玻瓈玉一堆，今年穷得立无锥。","鸿飞沙远微遮月，笋怨春归已厌雷。","梦里关山酸结果，醉中日月大钳锤。","一茎齑在教人吃，角徵宫商听者谁。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其八","f":"楚辞体","c":["绀发金毫此是真，父兮生我大年椿。","胞胎十月从盘古，弧矢当年射戊申。","瑶柱肌清存海蛤，肉尖软触笑麒麟。","江梅饶有千钧力，截取霜华作小春。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其九","f":"七言律诗","c":["断臂教心何处安，佛头正好与簪冠。","世人不信扳龙髯，吾道偏须食马肝。","梦蝶偶然传锦瑟，弹莺消得与金丸。","大分八字亭亭立，擎出秋香散菊团。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十","f":"七言律诗","c":["采苓竞上采薇山，周士不顽殷士顽。","苏峻有名诛庾亮，桓侯无义谢严颜。","齐纨莽戏花间蝶，铁网深笼海底珊。","莫怪史迁轻节义，苍天双立斗鸡幡。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十一","f":"七言律诗","c":["酣睡陈抟之华岳，昌黎雪涕强攀援。","人间死尽因巀嶪，平地春谁埽墓田。","蛾命随缘镫后夜，豹皮留取雾先鞭。","婷婷袅袅三尸队，且啖鸿门一彘肩。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十二","f":"七言律诗","c":["奇章梦异淳于梦，王播寮非周朴寮。","痁冷痎寒俱是疟，初三十八各乘潮。","宋齐邱卖谭升药，沈亚之欺弄王箫。","消受馀鲭有楼护，隔筵中垒漫劳招。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十三","f":"七言律诗","c":["石头路滑跌千交，蹑险刚餐度索桃。","珍重智镫逢室暗，凄凉愚鼓背人敲。","雷龙百部丹田火，风雨三茎赤胆毛。","淡月疏星生死径，北邙现在有东皋。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十四","f":"七言律诗","c":["冷眼越裳觑海波，横江津吏奈公何。","人归洪皓传边怨，客散田横阕挽歌。","绛蜡无光依鬼火，宝刀失计漏天魔。","参差记得前春梦，绣壁红丝系女萝。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十五","f":"七言律诗","c":["高纬暂时称狗脚，刘聪依额派官蛙。","啄来鹦鹉无香粒，舞彻垂杨有白华。","女颔带髭疑燕国，细腰无牝乱蜂衙。","苍天幻出非奇特，走尽银魂剩得砂。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十六","f":"七言律诗","c":["唐宋以前无辙迹，龙头删角未为蛇。","邻人乞醋兼输瓮，客鬼移头已载车。","埋到九泉同蚁语，悭留一范禁蝉赊。","儿童自笑乡音改，除取机心听尔揶。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十七","f":"七言律诗","c":["三头九头志古皇，可容稳梦北窗凉。","一百六日寒禁火，七十二丝悲动商。","李微呜咽羞作虎，左慈长跽乐为羊。","也知秋叶如鹃血，爱此枫林一夜霜。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十八","f":"七言律诗","c":["已闻嘉鱼诗作佛，还见仁和今为僧。","公今堕地吼狮子，我亦延客吊青蝇。","使君有蜀孤有魏，离娄无耳旷无睛。","夜半失枕明失火，眠食两废莫相矜。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其十九","f":"七言律诗","c":["狐皮织葛苧编裘，莫笑狂夫计不稠。","采蕺馀香熏茂苑，裂缯全锦付河洲。","醉眠芳草还沽酒，险摘星辰更上楼。","大扺乾坤消一拗，达多死认镜巾头。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十","f":"七言律诗","c":["夜阑风雨搅离心，啼鸟荒鸡梦可寻。","春草漫生莺不醒，碧天无际月空沈。","刘晨再到难求药，扁鹊当时忆下针。","镫火楼台三妇艳，棠梨邱垄二桃吟。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十一","f":"七言律诗","c":["焦先空爇马昭庵，朱泚全添卢杞蓝。","崔允下风输柳璨，刘歆上策笑周堪。","宜中宋瑞眉高下，黄皓姜维意北南。","张角巳消曹节恨，夏姬难饱孔宁馋。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十二","f":"七言律诗","c":["锋端有蜜也争甜，淡菜生忘彻骨盐。","鲎壳作帆迷缆索，蛛丝为线腻针尖。","近阑萤过皆疑月，邻院花开只下帘。","野老向人求骨董，平词匾鼓泪中拈。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十三","f":"七言律诗","c":["人间幻出墨胎廉，左右方圆画可兼。","莺啭九歌娇屈子，绿肥五柳富陶潜。","雪中但窖丰年蟘，汗后全忘隔日痁。","百尺竿头须痛劄，泥封汞鼎更添盐。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十四","f":"七言律诗","c":["反走无心怖季咸，还郴有客傲苏耽。","排场队里供千笑，折脚铛前老一庵。","五百僧唯推北秀，三秦人旧狎章邯。","潇湘春水如天上，白鸟高飞我自惭。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十五","f":"七言律诗","c":["鱼子鳖裙终岁事，蜂腰鹤膝暂时心。","蠹除恣我横吞墨，弦断知谁窃听琴。","洗面清晨知鼻孔，浇花昨日趁天阴。","劫灰揉得如泥烂，砌向雕梁燕垒深。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十六","f":"七言律诗","c":["少卿得意鱼烧尾，崔浩多才鳖出头。","魏绛巧穷工买绽，杜钦智尽漫藏钩。","扬雄须死元空草，徐铉无情水自流。","张伟醉中悲破甑，蒙恬悟后骂虚舟。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十七","f":"七言律诗","c":["病趣新来肝化越，壮心当日酒如渑。","流离少好今衰丑，追蠡年深旧款铭。","甜苦连根都是瓠，肉鱼杂煮别为鲭。","直方莫打龟山谱，西席逢迎只蔡京。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十八","f":"七言律诗","c":["燕反自嗔薪木毁，鼠归空汛月明航。","宝璎无力供诸佛，巾帼何辞诮女郎。","食豕食人颜不泚，于羊于蚁智双降。","冰蚕浴火如霜雪，劳尔添柴沸镬汤。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其二十九","f":"七言律诗","c":["婵娟侵夜片云遮，逗漏三星影但赊。","陇上健儿呜咽水，原头和尚武刚车。","凭医死马兜铃草，好上危墙吉莫靴。","鸟径关心如缕血，殷勤目送雁行斜。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十","f":"七言律诗","c":["张超用得迷离雾，殷七须开顷刻花。","棋馆儿孙千亿劫，渔村镫火两三家。","拨残冷灶应逢豆，击碎油瓶且拾麻。","旁午杏坛偷玉璧，殷勤鸡足擭袈裟。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十一","f":"楚辞体","c":["归来魂些元蜂塞，若有人兮白马河。","半笑半啼分咫尺，八寒八热一蹉跎。","从无猎者嫌猩骂，除是周南伏鼠魔。","摘出心肝人不买，摇槌徒唱望乡歌。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十二","f":"七言律诗","c":["一瓠被嗔五鹿角，卫公吃打大臣袍。","新寒改样酸垂足，宿痞生根病在膏。","六鹢退飞争熠耀，孤禽重过酷啁嘲。","藕丝大展脩罗殿，款款蜻蜓旁叶逃。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十三","f":"七言律诗","c":["清霜坠叶月当宵，似我风流不易描。","相好装成活卦影，文章哭杀死神尧。","黄金肘露衾前雪，生铁牙消饭底焦。","十里花飞千步锦，兰巢香满闹䳂鹩。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十四","f":"七言律诗","c":["匡人向后师阳虎，伍员先时笑白猿。","冷㬉饮鱼心不昧，淄渑别水舌难言。","楼台云闪还成市，头脑冬烘况是天。","煞认颖师诗上字，琵琶殊胜七条弦。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十五","f":"七言律诗","c":["郑伯区区惜佩兰，尔朱莽莽刈霜菅。","咒人大费铜铃语，点鬼多于玉笋班。","傀儡一丝牵白发，馒头半馅缺青山。","千秋眨眼萤光里，双脊撑腰碧落閒。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十六","f":"七言律诗","c":["李斯犬在难成虎，宾孟鸡全岂似鸾。","此处古人目不瞬，谁家田地足能安。","梁鸿妻偶容眉寿，文举儿宁问卵完。","犹得棠梨浇一饭，双眸莫受泪珠瞒。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十七","f":"七言律诗","c":["梁燕先秋向海门，梨花欲落正黄昏。","天心放我三竿睡，月晕偷谁五色文。","扪颈连头疑赘肉，拦腮掴掌认精魂。","相逢歧路鸱夷子，落魄须臾冥漠君。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十八","f":"七言律诗","c":["九锡逢人借羽麾，冰山斜倚玉山颓。","金针偏瞎重瞳眼，斧柄难施没孔槌。","铜雀春深埋铁锁，纸鸢风吹哭重围。","夜来魑魅天南路，黑塞魂随骤雨归。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其三十九","f":"七言律诗","c":["缓缓花随陌上去，娟娟月过故乡来。","无人解识娘生面，外道疑怀圣者胎。","活路无踪寻九折，死灰有燄射三能。","天吴紫凤饶璀璨，剪取或堪供袜材。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十","f":"七言律诗","c":["竹篦夺却拳堪用，皓齿凋残舌在无。","肉骨分离天不管，龟龙埋没地皆图。","雨云有梦虚神女，香火无郎是小姑。","一任东邻烹大武，但除白牯与狸奴。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十一","f":"七言律诗","c":["梅花撩乱莺先后，魔力争天挽日车。","俗客晒裈聊尔尔，比邱休夏自如如。","春醪唯滴陈咸土，月令閒修守敬书。","七夕金乌深妩媚，临河为赠夜光珠。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十二","f":"七言律诗","c":["情关稳塞一丸泥，谁许东风浪解凘。","李耳老才知守兑，幼安筮不待占离。","风流女国真孤寡，晴雨儿天莽笑啼。","寂寞刹竿双树倒，长江芦叶正当机。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十三","f":"七言律诗","c":["乾坤簿上终双济，甲子旬中剩两支。","卖水定逢眢井怒，移山好耐巨灵嗤。","平明乞火知镫灭，春尽编裘恐雪迟。","三寸离钩鳞鱍鱍，从来此曲少人知。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十四","f":"古风","c":["鸣鸠报雨当农急，蟋蟀吟秋听暑迟。","郑綮登庸佥侧陋，东施许嫁不嫌?。","当头一棒毒涂鼓，婪尾三台突厥词。","饶舌新莺催柳色，从来此曲尽人知。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十五","f":"七言律诗","c":["我不敢轻于汝等，啼鹃血亦写春融。","花留鹙子俄天女，剑在胡孙幻老公。","形似舜瞳犹项籍，巧逃羿彀更逢蒙。","也从金界亲阿逸，为赐铜山馁邓通。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十六","f":"七言律诗","c":["黳元珀赤旧来松，轸玉徽金半死桐。","向夕星稀飞顾兔，随时霜降葬丰隆。","刚吹楚水三生笛，谁打姑苏半夜钟。","一缕炊烟横晚照，下方人说白云封。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十七","f":"七言律诗","c":["天尊菩萨共胎泥，蔡瑁刘琦枉掇梯。","楚峡黄牛迷象马，华清苍鼠诉狐狸。","狂风那判樵风径，黑月谁分半月溪。","一枕草茵吾自适，千枫万柏染霜齐。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十八","f":"七言律诗","c":["豫且举网但张鱼，勃贺翻身早类猪。","嚬笑随时多失计，威灵到手又何需。","佛头鸽粪添鹰画，仙字蝌文死蠹书。","岸屋水舟无住处，鸟巢窠畔筑幽居。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其四十九","f":"七言律诗","c":["松岚浓染黛横涂，一点当梢玉魄孤。","细剖香魂邀篆尾，幽寻艳迹记花趺。","晴云山色微分派，春水池痕巧合符。","留境夺人充供养，云林先我写含糊。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十","f":"七言律诗","c":["六尺茅檐浅覆阶，就中矗立九成台。","袁安卧处雪偏埽，弥勒来时阁不开。","康节推成亥子际，荆卿让与艮坤埋。","笙簧哑尽乾婆殿，绺绺松风隔涧来。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十一","f":"七言律诗","c":["孟德何知泣穗帏，张巡差可听横吹。","无情有恨莲终落，百啭千回燕怕归。","鸩步偶同神禹迹，蜂腰狂学沈郎围。","针尖笔颖参差是，更拣惊蛇一线灰。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十二","f":"七言律诗","c":["老缩黄杨痴妙喜，童年苗秀旧终军。","六经瘦得蚕成茧，七发留来犀有文。","偪侧青燐镫燄绿，崚嶒白发雪山尊。","鱼游濠上分庄惠，鸡唱南塘感逖琨。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十三","f":"七言律诗","c":["三更杀气三刀梦，七尺离魂七宝鞍。","毕战分畦争铁界，宜僚弄技逐金丸。","浪斟绿醑吞蓬栗，细切黄橙脍虱肝。","菡萏巳凋蜻蛚散，萧条秋色付谁看。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十四","f":"七言律诗","c":["燕南赵北樵者山，西牛东胜渔父湾。","中间如砺不得合，两头随打暂偷閒。","六眼龟消三觉睡，半张钞买九还丹。","今我不乐缘底事，谢豹如啼行路难。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十五","f":"七言律诗","c":["任驾潘车邀左瓦，无如圆凿对方穿。","嬴政烧书留秦誓，巨君买谶费汉钱。","鹦母参差葛卢慧，蜗牛宛转科斗篇。","白玉楼高卧才鬼，遮须国狞富顽仙。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十六","f":"七言律诗","c":["小试霜翎志黑雕，生雠白额倩青腰。","也知一札穿无力，为记三山去有桥。","棋罢花间才七日，雨馀虹线失双条。","纸窗蝇迹毛锥子，草檄曾将五岳摇。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十七","f":"古风","c":["从注麟书讥败绩，难瞒马脊卖之爻。","龙标落尾从鼍鼓，虎口翻身祇猬毛。","杨柳命轻游子折，?舸福稳吴儿操。","青编画阁难消汝，逆旅无烟亦偶遭。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十八","f":"七言律诗","c":["有客反唇过古庙，驱寒四目送新傩。","冠分莲叶红千浪，镜合菱花绿半窠。","褪粉翩翩惊蛱蝶，扬灰阵阵趁香骡。","桥头好记归时路，汤煮松风有孟婆。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其五十九","f":"古风","c":["哀梨甜在故无柤，风雨陵飞朽骨娲。","但惜粉香须枕臂，为贪?味得胶牙。","三千僧退孤留佛，八九乌生总类鸦。","厨下新羹容易煮，魂消洗手但蒸沙。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十","f":"七言律诗","c":["寻针死计东洋海，失火生缘露地车。","九曲径幽知路蚁，连城珠贱报恩蛇。","魂随月下琴心立，眼透云中扇影遮。","烈焰原头烧不尽，藏春依约绿些些。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十一","f":"七言律诗","c":["不怕古今担不起，黑风刀雨几人当。","揕胸刮洗能医病，借面悲啼枉吊丧。","小可垂帘私望月，大都瓦解在休粮。","还他炭妇矶头雪，何用浓煎皂荚汤。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十二","f":"七言律诗","c":["九首天吴扶不起，生怜尺木怕龙倾。","葛花疗醉穷千日，樱饱吟蚊闹五更。","岸帻有头讥子羽，迷楼无酒酹张衡。","鰆鸮翡翠同条活，莫溷兰苕共咒鹰。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十三","f":"七言律诗","c":["花落悠悠莺佞舌，霜寒脉脉雪欺头。","楼前已听歌三叠，海外如闻说九州。","生死两丸堪抵鹊，雨晴殊候罢呼鸠。","破除少府花边泪，堆垛王官谷口休。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十四","f":"七言律诗","c":["臧三耳自无三鼻，琴七弦容清七心。","龙讲火经珠夺彩，蝉耽露味腹高吟。","灵猫滥配先农食，白象殊烦普眼寻。","邀月为欢憎影在，碧玻瓈盏灭镫斟。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十五","f":"七言律诗","c":["聒厌黄鹂酢厌柑，舄飞双鸟叶飞杉。","鱼肠壤接要离冢，蟋馆源通渔父潭。","日月龙山抛两帽，音书船子杳千帆。","汗青微挂羚羊角，大费痴蝇着意探。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十六","f":"七言律诗","c":["薅经锄史饱霜镰，溅血囊头奏凯兼。","七制旂常随羽扇，九州筐篚贡茅檐。","酿成熊胆甜如蜜，吐尽猪肝臭似蔹。","曾赌张翁输雀骑，无劳王剪索兵添。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十七","f":"七言律诗","c":["凤衰尺鴳聊栖竹，牛鼎烹鸡只损盐。","粒粟太仓官琐尾，中流一瓠用廉纤。","填饥但煮山君掌，学哑难施百会砭。","列传他年凭雁字，芸香免被蠹鱼嫌。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十八","f":"七言律诗","c":["苔林云茧孰相寻，鸟篆虫书枉见侵。","横摘孝经穷司马，巧翻淫咒嬲祇林。","玄黄野逐唯君驾，皂白沟分记子衿。","一石桐油舂不了，披裘那识路旁金。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其六十九","f":"七言律诗","c":["忘情润础候晴徵，种秫无田罢酒兵。","老摘儿拳伸佛臂，閒抛鹤膝放龙鸣。","兜元卷叶轮为郭，安养堆螺顶化生。","点染青蝇争一笑，仲繇夜绝楚王缨。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十","f":"七言律诗","c":["荷花忘却荷叶遮，鼓吹左纛新蛙车。","鹅儿黄嫩微睍睆，鹄立红云捧夭斜。","青蚨血乾诛阿母，蝤蛴队辇试莫耶。","黄金榜射金人眼，欲问南商求沔茄。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十一","f":"七言律诗","c":["姜桓彭虫溷寺貂，独孤香饭迎女猫。","大呼巫觋沈邺豹，烂煮轩辕赐土枭。","林荫夸父已得日，河分王亥不如鳐。","唐珏无翼衔燕土，鲍焦有齿累蠡瓢。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十二","f":"七言律诗","c":["龙汉密编何国纪，龟阴高筑岂畦台。","时留虎迹三人笑，尽辇鱼肠一窖埋。","肉店羊头须别拣，窗棂牛尾莫相咍。","随他竹叶舟中去，移取琶蕉雪里来。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十三","f":"七言律诗","c":["六息何心化北鱼，三蹄无技弄黔驴。","麻皴淡写悬流瀑，之绕涎收篆壁蝓。","渡海已烹丁令鹤，当筵且吃晋公猪。","分明四十年来事，银蒜丝丝玉不如。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十四","f":"七言律诗","c":["鹿娘胎乳旧分麑，氐叟根苗颔似羝。","亲见唐尧唯蝙蝠，再来百丈亦狐狸。","季鹰不是思鲈鲙，吕雉谁为讳野鸡。","济水应心河应肺，双流清浊夹分脐。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十五","f":"七言律诗","c":["拾得寒山共一时，袁闳张俭不相知。","棋填黑白唯馀罫，琴泛宫商别有雌。","唤尽奈何邀笛步，问来不语影娥池。","丹枫绛帐青莎馆，鞭挞吟蛩作导师。"]},{"t":"读甘蔗生遣兴诗次韵而和之七十六首 其七十六","f":"七言律诗","c":["荔枝香国涨香风，岣嵝红泉泛落红。","翁仲铁肝金作掌，吴刚桂斧月为容。","跛夔一足箫韶舞，盲汉三更法界钟。","稿饫全篇藏孔壁，华严半偈出龙宫。"]},{"t":"广遣兴五十八首 其一","f":"七言律诗","c":["别峰烟水霭晴岚，病骨差池久罢参。","短晷恰逢寒九九，佳期谁待后三三。","藤枯树倒寻常得，月驶云移仔细勘。","败叶如蓑妨两翅，鹧鸪无藉忆天南。"]},{"t":"广遣兴五十八首 其二","f":"七言律诗","c":["晴鸠呼雨不呼泥，一艇流沙弱水西。","周赧筑台深避债，鲁哀徙宅再忘妻。","涂穷自我魂迷蝶，交绝烦谁死炙鸡。","橄榄蔗浆双掷取，侬家滋味在楂梨。"]},{"t":"广遣兴五十八首 其三","f":"七言律诗","c":["傀儡居然牵得动，千波万折亦何凭。","骈枝偶举庞公女，折臂新摧二祖肱。","浊水月昏菱刺手，寒灰春湿菌成蒸。","何时期满桐棺假，还汝晶瓶一片冰。"]},{"t":"广遣兴五十八首 其四","f":"七言律诗","c":["为怀正在秋冬际，匠意难忘惨淡中。","人我众生谁寿者，王侯委巷一雌风。","愁唯遇雨怜桃梗，怒即占晴怪土龙。","踏地唤天终偪侧，巫咸鸩鸟两无功。"]},{"t":"广遣兴五十八首 其五","f":"七言律诗","c":["屡试空拳狎虎獶，唯除汗脚入鏖糟。","莲凋玉井红疑热，桃落绥山小不豪。","亲见汾阳吞酒肉，传闻腐史传锥刀。","冲天六翮繇他剪，但惜当胸一毳毛。"]},{"t":"广遣兴五十八首 其六","f":"七言律诗","c":["逢人偏我缩蝤蛴，颊印深深涨紫泥。","乞火就萤池上影，登高揖鳖砌閒梯。","多情语雀怜佳婿，得计屠羊有富妻。","乍可吐冰看蜥蜴，难禁玩月到灵犀。"]},{"t":"广遣兴五十八首 其七","f":"七言律诗","c":["嫫母妒情因妒色，青蝇嗛死讵嗛生。","青天遣尔公无罪，白地描他酷不成。","纣灭且烧天智玉，卫存何有木桃琼。","火攻自笑阿奴拙，命在王敦那在卿。"]},{"t":"广遣兴五十八首 其八","f":"七言律诗","c":["瘖蝉浪欲恼啼莺，啭啭刁刁底不平。","讽刺多情非小己，文言无字更繇庚。","天高略与通消息，春尽聊为弄雨晴。","把似破除都教尽，千年鹤肉伴鸡烹。"]},{"t":"广遣兴五十八首 其九","f":"古风","c":["主言不出吾何死，客难徒云世所嗔。","七国有碑唯诅楚，六经灭迹待亡秦。","忘忧但记徐无鬼，结舌谁知虞有人。","馋?不餐千亩竹，斫来滥写一溪春。"]},{"t":"广遣兴五十八首 其十","f":"七言律诗","c":["蛛丝缚翅莫逡巡，一线乾坤九六真。","莺燕蜩螗分主客，蔘苓乌附尽君臣。","盲人眼外公孙述，哑女生前杜子春。","一把针尖罗什口，九回肠里贯双缗。"]},{"t":"广遣兴五十八首 其十一","f":"七言律诗","c":["一池寒水清如露，影取千山桕叶丹。","画鬼易工愁狗马，分龙莫问渴鲂鳏。","石田滞穗埋头拾，长夏新梅入梦寒。","书史不灵天亦杳，惺惺一掐印痴顽。"]},{"t":"广遣兴五十八首 其十二","f":"七言律诗","c":["当年不夹丝毫汞，猛火烧心可自探。","借得金锤忘错误，烹来石鼎记酸咸。","贪栽苜蓿程生马，吝予柔桑蠋似蚕。","姬歜孔芹舌底事，世人浪说待回甘。"]},{"t":"广遣兴五十八首 其十三","f":"七言律诗","c":["一条即栗千峰雪，寒在眉梢㬉在肩。","电口笑看霜汁雨，冰绳涕堕冻脓天。","侏儒苦怕雕衔去，醉汉何妨虎过前。","别有元关人不到，桃花片片逆流还。"]},{"t":"广遣兴五十八首 其十四","f":"古风","c":["游魂非吉亦非凶，红烂骷髅白玉容。","未?且随生老病，悲秋不舍夏春冬。","佛牙反碎羚羊角，瘦骨难留狮子虫。","七尺肌疮痂脱尽，深惭无物饷刘邕。"]},{"t":"广遣兴五十八首 其十五","f":"七言律诗","c":["谁把灰堆一幅张，并刀误剪半淞江。","梯山航海中流漩，绣岭花门倒影幢。","大宅火争焚宝所，无家别即孕莲邦。","石人双眼真胡越，玉箸犹输五百双。"]},{"t":"广遣兴五十八首 其十六","f":"古风","c":["火里遂雄萧相国，高山还戴穆提婆。","雀儿有檄传参政，鬼母无言听祝鮀。","鳖项不伸蚊浪嘬，蜣丸日辇蚻欢歌。","肺肠剜尽还乡客，殊费人间万斛?。"]},{"t":"广遣兴五十八首 其十七","f":"七言律诗","c":["锻锡称公伯亦屠，黄泉子母尽人夫。","主宾奴虏棒三十，砂汞银铅火一垆。","藕孔有丝愁易露，虚空无相不难箍。","当时谁酿狻猊乳，大地难消一滴酥。"]},{"t":"广遣兴五十八首 其十八","f":"古风","c":["芙蓉爱秋只爱?，杜鹃催哑漫催春。","李耳出胎无少壮，图澄人灭更酸辛。","覆舟肉脯归无路，绕臂金蚕嫁愈亲。","鸬鹚鸂?各明眼，胡孙蛱蝶巳翻唇。"]},{"t":"广遣兴五十八首 其十九","f":"七言律诗","c":["一折一波皆绝倒，依稀雁字看横陈。","久将六义衰丁卯，别有十香溷乙辛。","窃屦无劳师孟子，弃灰谁得侮商君。","松梢玉露垂珠琲，独点韦编过小春。"]},{"t":"广遣兴五十八首 其二十","f":"七言律诗","c":["险句矛头频淅米，老颜花下且摊裈。","三年病饱禾花瘴，八口粮赊牛尾瘟。","穷自讨天酬骏骨，饥难掘地种膻根。","银蟾一显河山影，识得虾蟆不是冤。"]},{"t":"广遣兴五十八首 其二十一","f":"七言律诗","c":["不知寒㬉通身血，莽御罡风把戏竿。","笑骂好官皆蝶梦，英雄孺子一蜣丸。","三焦苦属安金藏，片舌难如公玉丹。","大禹智穷人裸国，春风还在胫毛端。"]},{"t":"广遣兴五十八首 其二十二","f":"七言律诗","c":["挑镫契阔交双睫，画被纵横作十洲。","秦水无鱼痴钓渭，瞿塘如马稳乘流。","披麻斧劈皴皆可，点漆丹砂果自繇。","一笑梦中还说梦，三更头上与安头。"]},{"t":"广遣兴五十八首 其二十三","f":"七言律诗","c":["龋齿犹腾笑口高，无须注目孟劳劳。","史迁诞亦疑巢许，阮籍狂宁骂懿操。","小觑维摩须借饭，深雠蒯聩未分桃。","何当细语赵宣子，桑下壸飧莫饲獒。"]},{"t":"广遣兴五十八首 其二十四","f":"古风","c":["苍天哭杀西来意，争似天津看弄猴。","述梦终愁多蹇涩，捋须自悔不搂{扌叜}。","芩连难抑虚肠火，脂粉徒填色眼沟。","誓把一镫烧栈道，蜀王无迹问金牛。"]},{"t":"广遣兴五十八首 其二十五","f":"七言律诗","c":["半绺犹存活气呵，泥龙爱雨莫嫌波。","三生鬼死还成毕，一尺仙高旧惹魔。","粥饭充肠从背馁，尘沙侵眼幸眉多。","龙门无事须烧尾，只此当檐挂雀罗。"]},{"t":"广遣兴五十八首 其二十六","f":"七言律诗","c":["愁眉耻为生缘锁，笑口难于死地开。","一榻蘧蘧还栩栩，三年瞿瞿复梅梅。","龙生九子馀鰆吻，鲛泣千行对蛤魁。","劝勉祇烦衔草鹿，惭惶无那祭禽豺。"]},{"t":"广遣兴五十八首 其二十七","f":"七言律诗","c":["一梦巳惊还一梦，邯郸虽好只邯郸。","长延凤颈毛空刷，已竭珠胎泪半残。","新霁更逢壬子破，微霜难似甲辰寒。","耳轮冰冷还潮热，脑剑湍奔又海乾。"]},{"t":"广遣兴五十八首 其二十八","f":"七言律诗","c":["花萎香檀草自忧，凭将托钵笑宾头。","门东但哭耶娘饭，天际非迷贾客舟。","即遣金棺重露足，应知画饼不充喉。","两堂漫为猫儿鬨，顶戴芒鞋代汝愁。"]},{"t":"广遣兴五十八首 其二十九","f":"七言律诗","c":["离钩有信脱金鳞，神蔡茎毛重九斤。","沩仰一镫亲父子，洞曹五位旧君臣。","波心芦叶催孤履，海上扶桑乍几尘。","佛血自归佛法界，弥天歌利尽魔军。"]},{"t":"广遣兴五十八首 其三十","f":"七言律诗","c":["莫将马角望燕丹，合用狼渊警范山。","石虎肠原难洗涤，卢蒲发已向凋残。","随拈赝璧都归赵，一乱真鸡且度关。","几尺天低惊谢朓，三更雪败贺袁安。"]},{"t":"广遣兴五十八首 其三十一","f":"七言律诗","c":["古人如我我如渠，影不相如画偶如。","无䏿无肠非蟹党，不鳞不介寄鳅居。","宝鸡误识穿坟蝹，淮雉疑同化鼠鴽。","刍狗梦中轮辗足，墨胎相掖上奔舆。"]},{"t":"广遣兴五十八首 其三十二","f":"七言律诗","c":["不将落叶认秋凶，老泪慵垂笑眼中。","他日夜台真昼锦，片时春赏暂冬烘。","人间世且游若士，天下图其授马融。","除却死生吾与汝，看谁白战是英雄。"]},{"t":"广遣兴五十八首 其三十三","f":"七言律诗","c":["担头旧卖雨霏微，错惹桃花扑岸飞。","缩项鳊能师鳖智，食心螟不慰蝗饥。","墦间鬼食乾糇德，牛口妻□伏卵悲。","待夺耕夫黄犊子，一溪春草衬蓑衣。"]},{"t":"广遣兴五十八首 其三十四","f":"七言律诗","c":["小东皋畔古榕边，飞鸟遗音到耳喧。","为道攀龙邀七贵，更闻牵犬守三川。","参差犹认分杯胆，点缀初分各灶烟。","黄鹄当时矶上月，从来一枣醉孤仙。"]},{"t":"广遣兴五十八首 其三十五","f":"七言律诗","c":["向来无病学呻吟，色色悲秋夜夜砧。","扳柘且求轩后药，操舟姑免项王喑。","王孙一饭辜淮肆，弟子三虚谢孔林。","朔雪不摧曷旦羽，长随彩凤嚇飞禽。"]},{"t":"广遣兴五十八首 其三十六","f":"七言律诗","c":["尽敛千眉入酢罂，眉尖有事也分明。","东陵鸡漫催人起，阳羡鹅容载我行。","乍喜青天遮两眼，唤谁白日打三更。","南邻酒伴差相识，鹤颈截来短亦鸣。"]},{"t":"广遣兴五十八首 其三十七","f":"七言律诗","c":["瞿昙共命偏调达，盛宪长年送孔融。","为遣汾阳营李白，徒教梦得诮桃红。","山头鹰眼留匡术，郿坞人膏染蔡邕。","宰噽病原依伍员，文渊傲不怨梁松。"]},{"t":"广遣兴五十八首 其三十八","f":"七言律诗","c":["王戎钻死于陵李，弥子分残曼倩桃。","花鸟新来皆命薄，蛇龙此日足功高。","蕉边梦亦争秦鹿，槐下魂犹嗾晋獒。","只遣狂夫添白眼，摊钱三峡狎奔涛。"]},{"t":"广遣兴五十八首 其三十九","f":"七言律诗","c":["充耳还馀龙角幽，花趺不奈蝶须搂。","鸺鹠苦咒孀妻土，卢雉偏明懒妇油。","月令丹良羞白鸟，天情须女狎牵牛。","相逢幸得方今日，荆轲无冠万发柔。"]},{"t":"广遣兴五十八首 其四十","f":"七言律诗","c":["犹有村醪醉一杯，酣酣鼻息雪中雷。","臂肝虫鼠宽檐帽，齿舌刚柔破草鞋。","冶葛毒偏肥孟德，海棠香只醉渊材。","黄金鞭落新春额，放出泥牛卧绿苔。"]},{"t":"广遣兴五十八首 其四十一","f":"七言律诗","c":["缚饥篾用千寻竹，补衲毛看一寸龟。","无处扪天求口耳，有时向佛索须眉。","寸丝脱尽云为茧，叠浪横行水有皮。","幸剪丰干如鸲鹆，闾邱无路得相知。"]},{"t":"广遣兴五十八首 其四十二","f":"古风","c":["千年无寿看妖狐，半夏多辛饱鹧鸪。","隐语阑斑藏大鸟，短歌慷慨唱南乌。","庄鹅无意逃厨妇，鲁?犹工射仆姑。","见说语儿溪畔语，蠹鱼乾血碧模糊。"]},{"t":"广遣兴五十八首 其四十三","f":"七言律诗","c":["禦寇新来免十浆，海鸥争席只沧浪。","齐王已足一千蹠，李相姑留五百羊。","庆喜佞兄唯相好，丹霞烧木更威光。","前身悔住青龙寺，博得穷涂一枣尝。"]},{"t":"广遣兴五十八首 其四十四","f":"七言律诗","c":["卜肆帘垂去建阳，谁尸朽壳问行藏。","逢人遍握凶年粟，顾我元无续命汤。","鼠变不妨尧畏禹，羊亡自觉谷贤臧。","障泥拚取前溪滑，夜半深池纵瞎缰。"]},{"t":"广遣兴五十八首 其四十五","f":"七言律诗","c":["姜维宏演同肝胆，孙楚黔娄共枕衾。","阮籍狂才闻凤啸，骆丞囚得伴蝉吟。","祢衡寿等龚生夭，东野鸣传豫子瘖。","井底史留坑外字，秦廷筑和雍门琴。"]},{"t":"广遣兴五十八首 其四十六","f":"七言律诗","c":["救日劳劳走啬夫，上天脉脉忆群巫。","火城莫保裴中立，水阵长悲李左车。","高会不成诛宋义，贫交劣得失田苏。","竹王一曲祠今古，山鬼旁招魂有无。"]},{"t":"广遣兴五十八首 其四十七","f":"七言律诗","c":["击仇鱼笏赌奸袍，尽不如他也自豪。","何有巷牛腓后稷，情知丧狗异皋陶。","石难与语酬开府，钱不能神福鲁褒。","他日无烦来大鸟，杜鹃春已到花梢。"]},{"t":"广遣兴五十八首 其四十八","f":"七言律诗","c":["覆窠无改伊风子，笭箵繇来元漫郎。","窜亦黄能憎屈姊，卧犹韦虎傲萧娘。","三茎鸡肋婴临济，百啭莺喉和帝江。","欲剪鸳鸯双袖落，郎当鲍老臂原长。"]},{"t":"广遣兴五十八首 其四十九","f":"七言律诗","c":["一令单提千令合，不除狂醉只除醒。","垂杨左肘飞花絮，腐草馀滋幻火萤。","枳棘芝兰同土壤，国皇月孛一辰星。","钟情我辈聊如此，瞥眼他生固不争。"]},{"t":"广遣兴五十八首 其五十","f":"七言律诗","c":["造次看花须看叶，分明夺眼不夺睛。","丝丝香篆萦空湿，泼泼江流荡远晴。","一剑杀生生在杀，五更惺梦梦元惺。","空窠蜂子痴如醉，泥涧元蜦懒不矜。"]},{"t":"广遣兴五十八首 其五十一","f":"七言律诗","c":["栎火垆边缩猬毛，犹贤击楫唱离骚。","头风莫与陈琳檄，腹疾无庸叔展号。","春梦半醒逐妇鸟，岳云抔土抱娘蒿。","杀机夜半衾前动，扪虱思援斩佞刀。"]},{"t":"广遣兴五十八首 其五十二","f":"七言律诗","c":["慵将奇字溷侯芭，一卷轩辕鼎内砂。","拟听扬干诛魏绛，不髓荀勖妒张华。","胡兄煮死谁宜弟，厉子宵生且似耶。","留取神皋开五叶，愁提鬼掌卖莲花。"]},{"t":"广遣兴五十八首 其五十三","f":"七言律诗","c":["曾向孤峰驾一航，他家浪道木墀香。","通身是口云藏日，劈脊当心雪上霜。","捏碎函舆仍捻合，单提雷雨与分张。","乌元鹄白明看汝，懒学新秋架鹊梁。"]},{"t":"广遣兴五十八首 其五十四","f":"七言律诗","c":["且听冰霜冷万家，冻禽赢得吃梅花。","春风随手成红锦，朗月当头到碧纱。","虾岛鲸城疑海客，黄连白蜜信齐牙。","香飘第二月中桂，惭愧张骞问汉槎。"]},{"t":"广遣兴五十八首 其五十五","f":"七言律诗","c":["真陶潜外无陶潜，药价如虚减亦添。","草履犹能名不借，刍灵何待与三钳。","葵无定影疑天恕，桃换新符怕鬼嫌。","自是聪明涂已尽，飞鱼空笑上竿鲇。"]},{"t":"广遣兴五十八首 其五十六","f":"七言律诗","c":["冰虫无分夏陈尸，且救头燃迅速时。","说火犹防烧象齿，分波不管攫龙儿。","李陵恩重频携手，陶令缘悭但皱眉。","待废公孙坚白论，孔穿无膝拜皋比。"]},{"t":"广遣兴五十八首 其五十七","f":"七言律诗","c":["微吟即遣暗虫惊，齐语繇来挞不成。","旧学刑书墨剕劓，新悬乐笋怒飞鸣。","法筵道得犹三棒，地狱难消在一茎。","略向东风赊妩媚，还逢百舌禁流莺。"]},{"t":"广遣兴五十八首 其五十八","f":"七言律诗","c":["方春两眼不曾饥，饱拣花枝到柳枝。","哀乐无端生杀外，河山有样去来时。","狂夫顾笑难消汝，哑女当歌拟倩谁。","何事延陵观乐客，强删苗黍下泉诗。"]},{"t":"和梅花百咏诗 其一 古梅","f":"七言绝句","c":["早岁先登秦女峰，腰垂绿发玉为容。","不知甲子真多少，问取前溪偃盖松。"]},{"t":"和梅花百咏诗 其二 早梅","f":"七言绝句","c":["不遣西园久放闲，微阳烘蒂坼朱殷。","南征雁过惊春色，睥睨寒汀拟北还。"]},{"t":"和梅花百咏诗 其三 庭梅","f":"七言绝句","c":["素锦光摇玉篆牌，曈胧清影正当阶。","画垣底事重重闭，未有尘飞走马街。"]},{"t":"和梅花百咏诗 其四 官梅","f":"七言绝句","c":["碧干扶疏间古槐，晨衙画鼓隔檐催。","迎春初进缠红仗，一日偷闲得看来。"]},{"t":"和梅花百咏诗 其五 江梅","f":"七言绝句","c":["横梢淅沥入船窗，低映棠桡乱雪淙。","雁尽天南人未返，憎他带影一双双。"]},{"t":"和梅花百咏诗 其六 溪梅","f":"七言绝句","c":["香雾氤氲霭碧湾，流澌一夜送潺湲。","低垂乱惹珠光溅，疑是疑非响佩环。"]},{"t":"和梅花百咏诗 其七 岭梅","f":"七言绝句","c":["藏春有坞贮轻融，直上千寻故御风。","平甸下看烟漠漠，孤擎宝露出清空。"]},{"t":"和梅花百咏诗 其八 野梅","f":"七言绝句","c":["牧笛无心倚玉箫，青帘得意远兰桡。","生憎杀景张功甫，浪与移栽向六桥。"]},{"t":"和梅花百咏诗 其九 忆梅","f":"七言绝句","c":["先春不得待春阑，渺渺西洲欲见难。","唯有梨花赊剩粉，黄昏烟雨殢人看。"]},{"t":"和梅花百咏诗 其十 梦梅","f":"七言绝句","c":["湘簟凝凉菡萏开，幽香冷触幻春回。","因缘漫向痴人说，只作当先及第猜。"]},{"t":"和梅花百咏诗 其十一 寻梅","f":"七言绝句","c":["消息心知在别峰，南参烟水尚重重。","溪云乍捲流泉细，一点香飘带影逢。"]},{"t":"和梅花百咏诗 其十二 问梅","f":"七言绝句","c":["不是桃源惘去津，知开知落也难真。","南邻酒伴经旬饮，欲与商量恐过春。"]},{"t":"和梅花百咏诗 其十三 探梅","f":"七言绝句","c":["扳枝已见绿催新，敛萼犹疑粉未匀。","子夜霜鸡惊晓起，逢迎不早怕花瞋。"]},{"t":"和梅花百咏诗 其十四 索梅","f":"七言绝句","c":["楼头遥望识春生，雪径过从奈宿酲。","闻说冻禽争采啄，何妨分我一杯羹。"]},{"t":"和梅花百咏诗 其十五 观梅","f":"七言绝句","c":["脉脉从看为解颐，阳和一茧细抽丝。","捐情似水容相见，不许香车宝马窥。"]},{"t":"和梅花百咏诗 其十六 赏梅","f":"七言绝句","c":["徵诗檄就隔林催，鹤膝猩毡渡水来。","婪尾不须倾腊酒，瓮头还有煮青醅。"]},{"t":"和梅花百咏诗 其十七 友梅","f":"七言绝句","c":["大夫已见受秦封，君子还惊化鹤容。","独抱冰心邀瑞叶，溪头三笑一相逢。"]},{"t":"和梅花百咏诗 其十八 寄梅","f":"七言绝句","c":["红尘日日促香乾，欲赠相思行路难。","知到陇头春已尽，祗应将作柳枝看。"]},{"t":"和梅花百咏诗 其十九 评梅","f":"七言绝句","c":["绝色平分雪几曾，清香不怕月难胜。","双标第一花卿品，莫遣姚黄妒汝能。"]},{"t":"和梅花百咏诗 其二十 歌梅","f":"七言绝句","c":["乍炙银笙试朔吹，旋抛珠串赛清姿。","晓风残月伤心句，不待杨花扑岸时。"]},{"t":"和梅花百咏诗 其二十一 别梅","f":"七言绝句","c":["离筵及早酌屠苏，留看镫宵待得无。","知有前期霜信后，小窗人奈雪侵须。"]},{"t":"和梅花百咏诗 其二十二 惜梅","f":"七言绝句","c":["情知无计奈春何，水涘山椒玉一波。","密筱藏阴香几瓣，还愁微霰祝暄和。"]},{"t":"和梅花百咏诗 其二十三 折梅","f":"七言绝句","c":["蹑藓墙东带笑披，暄风还向手中吹。","閒情贪授寻春客，不管高枝怨别离。"]},{"t":"和梅花百咏诗 其二十四 剪梅","f":"七言绝句","c":["当窗妨绣凤头鞋，出閤惊捎小燕钗。","拚取惜花情几许，并刀一割玉龙乖。"]},{"t":"和梅花百咏诗 其二十五 浴梅","f":"七言绝句","c":["台上天花白㲲巾，戒香腊日洗尘尘。","寒崖莫有三冬㬉，为现瞿昙四月身。"]},{"t":"和梅花百咏诗 其二十六 浸梅","f":"七言绝句","c":["清泉细点石硫黄，留得荀公几日香。","蜡蒂涓涓升宿润，犹疑疏雨过银塘。"]},{"t":"和梅花百咏诗 其二十七 簪梅","f":"七言绝句","c":["宜春燕子缕金花，抛掷偏拈紫玉芽。","风味爱他林下好，妆成掬雪试烹茶。"]},{"t":"和梅花百咏诗 其二十八 妆梅","f":"七言绝句","c":["低回怕得近帘钩，宝髻当心五瓣收。","萼绿华传新样子，吴娃错道牡丹头。"]},{"t":"和梅花百咏诗 其二十九 蟠梅","f":"七言绝句","c":["藤捎蔓惹怕清狂，收拾闲心寸步香。","向日迎风千笑合，来回无影过东墙。"]},{"t":"和梅花百咏诗 其三十 接梅","f":"七言绝句","c":["裁素纫红半臂嵌，缝成知费手掺掺。","新恩特赐加绯服，仍带银鱼旧日衔。"]},{"t":"和梅花百咏诗 其三十一 谱梅","f":"七言绝句","c":["乡国原标大庾南，飘零偶籍百花潭。","宗支的的吴门隐，指李荒唐笑老聃。"]},{"t":"和梅花百咏诗 其三十二 苔梅","f":"七言绝句","c":["紫葆初含故叶稀，孤茎独秀绿茸肥。","晴云润浥虬枝软，倒写溪光碧玉围。"]},{"t":"和梅花百咏诗 其三十三 杏梅","f":"七言绝句","c":["薄袂圆襟一式裁，骎骎旋接落英开。","便娟为少新条绿，遥向日边掠彩来。"]},{"t":"和梅花百咏诗 其三十四 蜡梅","f":"七言绝句","c":["弱粉难支雪色侵，檀痕相倚赖知音。","连床各梦还同调，冻蝶迷香记浅深。"]},{"t":"和梅花百咏诗 其三十五 竹梅","f":"七言绝句","c":["妩媚檀栾共一时，鸭头新浴鹭飘丝。","长疑剩粉归何处，密裹龙孙出箨枝。"]},{"t":"和梅花百咏诗 其三十六 雪梅","f":"七言绝句","c":["减取琼花一片开，五铢轻较六铢裁。","亭亭小立雕楹外，白纻闲看舞袖回。"]},{"t":"和梅花百咏诗 其三十七 月梅","f":"七言绝句","c":["轻梢无叶出空微，弱片多惊定影非。","碧海胧胧烟似水，清晖略带一分肥。"]},{"t":"和梅花百咏诗 其三十八 风梅","f":"七言绝句","c":["云痕乍裂袅孤烟，薄媚东君试一暄。","背水独摇香阵阵，芳心透过柳枝边。"]},{"t":"和梅花百咏诗 其三十九 烟梅","f":"七言绝句","c":["一片芳情悄自拘，未分明处不模糊。","凭谁洗涤幽香魄，为倩绵山缟臆乌。"]},{"t":"和梅花百咏诗 其四十 孤梅","f":"七言绝句","c":["空明碧瀁粉离离，寒鹊寻香远不迷。","野渡问津人共指，重来犹记折残枝。"]},{"t":"和梅花百咏诗 其四十一 移梅","f":"七言绝句","c":["徼欢得向玉堂栽，油帟朱阑碧甃台。","断岸当年生长地，春云如絮野棠开。"]},{"t":"和梅花百咏诗 其四十二 疏梅","f":"七言绝句","c":["暮雨萧萧梦几忘，晨星落落意争狂。","从教子结调羹用，不倚多金傲雒阳。"]},{"t":"和梅花百咏诗 其四十三 老梅","f":"七言绝句","c":["天涯迟暮岁寒心，浅着铅华远罩阴。","消渴文园相待久，黄金为买白头吟。"]},{"t":"和梅花百咏诗 其四十四 新梅","f":"七言绝句","c":["试雨禁风始出胎，根苗忘尽旧亭台。","倡条冶叶轻前辈，庾信江南老自哀。"]},{"t":"和梅花百咏诗 其四十五 矮梅","f":"七言绝句","c":["舞衣不浪费冰绡，仰笑垂杨衒楚腰。","罗袜风生惊飏起，旋看缘带上头娇。"]},{"t":"和梅花百咏诗 其四十六 远梅","f":"七言绝句","c":["邻院新栽叶未滋，窗前无分慰相思。","逢人把过石桥去，借问攀从晓露时。"]},{"t":"和梅花百咏诗 其四十七 落梅","f":"七言绝句","c":["乍㬉初催朵朵齐，蛟冰风捲画楼西。","琉璃国土堪埋玉，不遣馀香上燕泥。"]},{"t":"和梅花百咏诗 其四十八 瘦梅","f":"七言绝句","c":["断岸欹危挂古藤，红泉瑞露饱何曾。","清羸百鸟衔来易，将供日中一食僧。"]},{"t":"和梅花百咏诗 其四十九 宫梅","f":"七言绝句","c":["玉鳞遍覆软条青，合殿金铺尽日扃。","唯有楼东人睡起，垆烟移远水晶瓶。"]},{"t":"和梅花百咏诗 其五十 檐梅","f":"七言绝句","c":["纤枝上与午烟齐，坠玉旁依乳雀栖。","冰溜夜悬三百颗，双邀斜月漾玻瓈。"]},{"t":"和梅花百咏诗 其五十一 寒梅","f":"七言绝句","c":["生缘同在凅阴天，栗烈何因授记偏。","为有临风观望客，迟迟春日拥黄绵。"]},{"t":"和梅花百咏诗 其五十二 咀梅","f":"七言绝句","c":["闻说犹疑耳亦贪，终年不食更何堪。","轻松脆软清泉味，池底夺将雪藕甘。"]},{"t":"和梅花百咏诗 其五十三 盆梅","f":"七言绝句","c":["平塘梦断夕阳红，曲槛容遮五夜风。","一点春愁分不去，当阶斜睨锦熏笼。"]},{"t":"和梅花百咏诗 其五十四 红梅","f":"七言绝句","c":["对色疑非香不非，迎暄莫问素心违。","光风灼灼传新喜，残雪全消散落晖。"]},{"t":"和梅花百咏诗 其五十五 粉梅","f":"七言绝句","c":["从捐螺黛洗鸦黄，金母熏成姹女妆。","色坏为铅难似此，凌风九转更欺霜。"]},{"t":"和梅花百咏诗 其五十六 青梅","f":"七言绝句","c":["花事阑珊绿覆除，累累带雨更愁余。","涛笺藉染胭脂色，聊寄江南一纸书。"]},{"t":"和梅花百咏诗 其五十七 黄梅","f":"七言绝句","c":["酿就莺醅已过春，日长还遣翠眉嚬。","石家莫倚风狂味，霪雨新添妒妇津。"]},{"t":"和梅花百咏诗 其五十八 盐梅","f":"七言绝句","c":["鼎烹鼎食在逡巡，谁遣酸寒入梦真。","滋味何如末下豉，秋风招隐啜湘莼。"]},{"t":"和梅花百咏诗 其五十九 千叶梅","f":"七言绝句","c":["赊春无已索春添，簇簇新齐闹不嫌。","狂瘦痴肥从肉眼，神清无事卖廉纤。"]},{"t":"和梅花百咏诗 其六十 鸳鸯梅","f":"七言绝句","c":["青豆相思意偶通，开时疑说并头红。","无端赚杀林和靖，三十六双一梦中。"]},{"t":"和梅花百咏诗 其六十一 绿萼梅","f":"七言绝句","c":["叶色通梢晓气醒，趺香浮干艳心扃。","单于莫怪胭脂失，汉月昏黄冢自青。"]},{"t":"和梅花百咏诗 其六十二 胭脂梅","f":"七言绝句","c":["红蓝染髓换霜肤，血滴灵芸凝玉壶。","莫讶施朱教太赤，入时学得牡丹图。"]},{"t":"和梅花百咏诗 其六十三 西湖梅","f":"七言绝句","c":["缥渺芳情送画船，苏堤莫诧柳如烟。","葑田捲尽琉璃现，此是开山白乐天。"]},{"t":"和梅花百咏诗 其六十四 东阁梅","f":"七言绝句","c":["香国扬州锦阵豪，诗情偏向峭寒高。","都官吟后输声价，倾盖白头只水曹。"]},{"t":"和梅花百咏诗 其六十五 清江梅","f":"七言绝句","c":["沙明难辨几枝生，浪碧微看浅色轻。","一疋练飞花样细，还从豆蔻夜熏成。"]},{"t":"和梅花百咏诗 其六十六 孤山梅","f":"七言绝句","c":["放鹤亭空客已仙，裙腰褪粉断桥边。","广陵新送青娥怨，苦判馀芳作杜鹃。"]},{"t":"和梅花百咏诗 其六十七 罗浮梅","f":"七言绝句","c":["客路相逢散旅愁，桄桹月落海天悠。","何当移向神山种，得共师雄赋白头。"]},{"t":"和梅花百咏诗 其六十八 汉宫梅","f":"七言绝句","c":["长门春锁万花深，纨扇无愁到玉林。","记得虞渊官簿说，紫华紫叶结同心。"]},{"t":"和梅花百咏诗 其六十九 廨舍梅","f":"七言绝句","c":["被拥黄紬晓睡醺，蜃窗晴送暗香闻。","故山春色今何许，空署当轩五朵云。"]},{"t":"和梅花百咏诗 其七十 书窗梅","f":"七言绝句","c":["檐牙折向纸镫龛，数蕊巡香漏已三。","误捡秦风求故实，终南原只有条楠。"]},{"t":"和梅花百咏诗 其七十一 琴屋梅","f":"七言绝句","c":["晴轩融敞静香传，器冷心闲好扣弦。","一片低飞疑窃听，随风巧入郭公砖。"]},{"t":"和梅花百咏诗 其七十二 棋墅梅","f":"七言绝句","c":["未了寻香又拂枰，冰绡遥映碧纱明。","春前开亦随春落，先手何心百转争。"]},{"t":"和梅花百咏诗 其七十三 钓湾梅","f":"七言绝句","c":["小穗侵波曲罥钩，危根拿石细分流。","羊裘垫卧收缗晚，争唼落英看白鸥。"]},{"t":"和梅花百咏诗 其七十四 樵径梅","f":"七言绝句","c":["谷口凝阴宿雪淹，槎枒望断白云尖。","夜来野烧刚馀得，一树垂垂出短檐。"]},{"t":"和梅花百咏诗 其七十五 僧舍梅","f":"七言绝句","c":["宝刹疑看珠雨飞，香烟幢影共霏微。","雪山十九因缘熟，那但长留舍利衣。"]},{"t":"和梅花百咏诗 其七十六 道院梅","f":"七言绝句","c":["鹤径风回香细萦，仙衣长似御风轻。","砂胎初剖银芽出，还恐流珠㬉易倾。"]},{"t":"和梅花百咏诗 其七十七 柳营梅","f":"七言绝句","c":["系马蟠根铁色粗，寒光飞练射昆吾。","花前莫话封侯事，一树功成万木枯。"]},{"t":"和梅花百咏诗 其七十八 蔬圃梅","f":"七言绝句","c":["挑荠正美芥回青，脆甲中含碎玉零。","缓火夜烹风味别，孤芳生齿酒初醒。"]},{"t":"和梅花百咏诗 其七十九 茅舍梅","f":"七言绝句","c":["小角阴垂槲径遮，浅檐风转搅横斜。","佳人何必牵萝补，百琲明珠缀若邪。"]},{"t":"和梅花百咏诗 其八十 药畦梅","f":"古风","c":["竹籞密排落叶蠲，寻芽访蕊试新年。","黄精苗绝蘼芜?，略报东风一点暄。"]},{"t":"和梅花百咏诗 其八十一 前村梅","f":"七言绝句","c":["小径冰封碍往还，春心遥寄有无间。","开窗欲觅香来处，犹隔当门一段山。"]},{"t":"和梅花百咏诗 其八十二 炤水梅","f":"七言绝句","c":["朱点当心印不如，一花五叶我逢渠。","万波摇动兼遮显，斜领犹看不见馀。"]},{"t":"和梅花百咏诗 其八十三 山中梅","f":"七言绝句","c":["捷径无心假息机，豹林谁买玉田肥。","人閒好句传高启，驱遣袁安卧翠微。"]},{"t":"和梅花百咏诗 其八十四 城头梅","f":"七言绝句","c":["画影斜连大旆阴，丽谯日暮饱归禽。","岧峣一听睢阳笛，月苦云深天地心。"]},{"t":"和梅花百咏诗 其八十五 冰竹梅","f":"七言绝句","c":["寒池清浅影笼冰，雾上云鬟冷不胜。","斜倚琅玕舒凤尾，翠帏深拥㬉香凝。"]},{"t":"和梅花百咏诗 其八十六 水月梅","f":"七言绝句","c":["玉魄昏黄罩素魂，縠波潋滟吸香痕。","分身自在双涵得，总被空青一镜吞。"]},{"t":"和梅花百咏诗 其八十七 担上梅","f":"七言绝句","c":["累垂得得到江城，妆点琴囊衬酒鎗。","棐几素屏充供养，闺中莫听卖花声。"]},{"t":"和梅花百咏诗 其八十八 杖头梅","f":"七言绝句","c":["玉色分鸠瑩不任，庞眉霜鬓映森森。","道逢禅客机缘捷，摆落天花雪满襟。"]},{"t":"和梅花百咏诗 其八十九 隔帘梅","f":"七言绝句","c":["银蒜遮寒小閤深，胆瓶曲槛两沈吟。","疏筠咫尺天涯路，一曲潇湘万里心。"]},{"t":"和梅花百咏诗 其九十 照镜梅","f":"七言绝句","c":["鼻观分明到眼惊，他心通尽意身生。","凭谁拈笑分宾主，水月空轮挂宝璎。"]},{"t":"和梅花百咏诗 其九十一 十月梅","f":"七言绝句","c":["为惜霜红昨日凋，续香补艳倩新条。","一枝迎雪元多丽，何事王维更画蕉。"]},{"t":"和梅花百咏诗 其九十二 二月梅","f":"七言绝句","c":["□馡怕被素玚欺，青豆傍看玉蕊垂。","听彻莺喉邀蝶舞，风流何必少年时。"]},{"t":"和梅花百咏诗 其九十三 未开梅","f":"七言绝句","c":["万顷春膏凝玉酥，晓霜残月足踟蹰。","须须叶叶无中有，一幅先天五老图。"]},{"t":"和梅花百咏诗 其九十四 乍开梅","f":"七言绝句","c":["蚌胎微吐露灵砂，略与东皇报岁华。","底事花魂多荏苒，逼人诗思在些些。"]},{"t":"和梅花百咏诗 其九十五 半开梅","f":"七言绝句","c":["心心长待笋班齐，南北中分人望迷。","残腊易消春易老，怕教抛尽惹莺啼。"]},{"t":"和梅花百咏诗 其九十六 全开梅","f":"七言绝句","c":["晨探莫惮冻云天，一日风光尽一年。","暂喜真珠抛十斛，悬愁银甲搯苔钱。"]},{"t":"和梅花百咏诗 其九十七 水墨梅","f":"七言绝句","c":["冷晕圆拖碯碗浆，古香浓喷豹皮囊。","分圈硬用中峰笔，百首诗情此较长。"]},{"t":"和梅花百咏诗 其九十八 画红梅","f":"七言绝句","c":["被酒濡毫敌晓寒，淋漓狂扫万枝珊。","禅心为笑花光老，借得妆楼绣谱看。"]},{"t":"和梅花百咏诗 其九十九 玉笛梅","f":"七言绝句","c":["曲里寻春已惘然，瑶村况觅洞庭仙。","空花和合声香色，带影独头起识田。"]},{"t":"和梅花百咏诗 其一○○ 纸帐梅","f":"七言绝句","c":["幽艳浓熏㬉雪窝，流香横漾皱纹波。","轻姿梦醒镫前现，隔断白云奈采何。"]},{"t":"追和王百谷梅花绝句十首 其一","f":"七言绝句","c":["梅叶上红争欲落，南枝何处索春光。","姮娥前夕开明镜，莫有佳人试早妆。"]},{"t":"追和王百谷梅花绝句十首 其二","f":"七言绝句","c":["元魂不死空明外，秋水秋云总似花。","直待江春问消息，痴拈袜线觅袈裟。"]},{"t":"追和王百谷梅花绝句十首 其三","f":"七言绝句","c":["停觞待月似蒸砂，一瓠先生病吃茶。","认得六桥鳏处士，湖光封雪觅梅花。"]},{"t":"追和王百谷梅花绝句十首 其四","f":"七言绝句","c":["当时幸免赐官湖，败叶聊遮冷鹧鸪。","有土种梅三百树，焚香无地避催租。"]},{"t":"追和王百谷梅花绝句十首 其五","f":"七言绝句","c":["万花争尽垒东西，雪骨霜魂分不齐。","金粟迎寒开月浦，絪缊香雾一双迷。"]},{"t":"追和王百谷梅花绝句十首 其六","f":"七言绝句","c":["黄梅瓤熟无多日，玉露催秋月屡弦。","但使看花留老眼，不愁春色恼人偏。"]},{"t":"追和王百谷梅花绝句十首 其七","f":"七言绝句","c":["白头綵笔写氤氲，香霭描来雪几分。","犹恐相逢不相识，拟添残月与轻云。"]},{"t":"追和王百谷梅花绝句十首 其八","f":"七言绝句","c":["断岭知谁旧种来，藤萝无限妒花开。","蓬蒿初剪清魂洗，旧尉三生也姓梅。"]},{"t":"追和王百谷梅花绝句十首 其九","f":"七言绝句","c":["渐老看花似隔烟，诗情欲懒上滩船。","绯桃红药输年少，把雪吟霜却少年。"]},{"t":"追和王百谷梅花绝句十首 其十","f":"七言绝句","c":["彭城才子太怜梅，一舸轻移郢树开。","红粉喷香薰小阁，冻蜂迢递许重来。"]},{"t":"洞庭秋三十首 其一","f":"七言律诗","c":["潇湘北下巴江东，上蟠下际抟青空。","天地忘忧消偪侧，凄清作意撩鸿濛。","夔子孤城悬太白，三苗馀垒挂残虹。","古今无那此俄顷，欹危歘尔生蘋风。"]},{"t":"洞庭秋三十首 其二","f":"七言律诗","c":["月似芦花烟似水，似如不似劳形容。","喷雪凝寒犹清适，涵晖冷燄飞轻松。","星汉相看交不昧，心魂欲之亦奚从。","但觉晃煟透圆碧，不辨愁来忽已逢。"]},{"t":"洞庭秋三十首 其三","f":"七言律诗","c":["大仪悬张覆釜幢，谁其至者弗心降。","长天纤忽随泯泯，商飙骚屑入淙淙。","浩瀚无馀一丝挂，清微欲将九鼎扛。","安得沐日仍浴月，东赪西皎晶荧双。"]},{"t":"洞庭秋三十首 其四","f":"七言律诗","c":["洞䆗虚无净一规，惊涛相即不相疑。","精金大冶鍊幽蚃，俊鹘老鼍愁倾危。","炎心已改何洗涤，高旻受荡还清嬉。","妙香浮动非蘋芷，水雾上摄开轻吹。"]},{"t":"洞庭秋三十首 其五","f":"七言律诗","c":["乾坤倦游行将归，损山容益水光肥。","片云帆侧不能影，木叶天际知己飞。","游子去妻百交感，战伐渔樵双息机。","驱除姝暖返肃爽，禁愁为惜素心违。"]},{"t":"洞庭秋三十首 其六","f":"七言律诗","c":["羁心劈破芥浮居，色色消沈远近如。","险目不平夹韵度，凉魂小住姑安舒。","孙刘战争问沤沫，怀葛徂伏留萧疏。","情知涕泗无栖泊，放浪磊砢任太虚。"]},{"t":"洞庭秋三十首 其七","f":"七言律诗","c":["翛然容与清泠都，何求不得须黄垆。","函盖双枢合骀宕，明暗半丝分有无。","潜蛟旅雁忘兴废，疏云片月矜昭苏。","缩为椰子沁心肾，幻计无忝移山愚。"]},{"t":"洞庭秋三十首 其八","f":"古风","c":["空有无垠铲径蹊，分明至极翻凄迷。","远视不正非野马，客心已窘聊木鸡。","帆蝶卖眼惊天末，樯乌亡赖啼日西。","阴光夕灼动绿气，?然鬼臂相牵携。"]},{"t":"洞庭秋三十首 其九","f":"七言律诗","c":["碧落无疑鹏背揩，入寥天一绝安排。","邂逅不停增蹇产，虚空未破犹沈埋。","略遣水光存芥蒂，想知天骨正厓柴。","鲸鲤可骑终未称，吾生箬笠双青鞋。"]},{"t":"洞庭秋三十首 其十","f":"七言律诗","c":["回头摇落悲群动，广大昌明亦自猜。","无触之声消梦晷，不寒而慄贮骚才。","藏舟后夜同归壑，张楚初心冀缓哀。","驰骛清狂何所吝，寒潭降潦畏相催。"]},{"t":"洞庭秋三十首 其十一","f":"七言律诗","c":["瀰瀰盈盈不借春，千萧万瑟屯嶙峋。","水力未至溢浩淼，雄心仅可吞清贫。","张乐鼓瑟凭慰藉，巫娥湘后惘逡巡。","自然难释虚无恨，斜月流霜非有因。"]},{"t":"洞庭秋三十首 其十二","f":"七言律诗","c":["目穷差别耳非闻，逼塞诸根但有云。","触法大都无软美，宽饶何处着殷勤。","如浮今古谁为纽，尽费烟霄不受熏。","一笑中流誇定力，那知悽恻破三分。"]},{"t":"洞庭秋三十首 其十三","f":"七言律诗","c":["西清启寒亦有门，扃魂不扃金水魂。","方诸津润遂昌大，青女娥㜲失恭温。","孤云峰势向凌替，海天精彩捐烦冤。","空洞虽非万法侣，临之未易相贪吞。"]},{"t":"洞庭秋三十首 其十四","f":"七言律诗","c":["随处波心着戏竿，刚森簇簇护轻安。","充形暄气存黍米，大冶昭质任烹爨。","根株吾岂依坟埴，须发何庸非羽翰。","霏苍飏碧自生意，行与浑仪谋团栾。"]},{"t":"洞庭秋三十首 其十五","f":"七言律诗","c":["远行之感剧登山，壑断湍哀梦亦悭。","戍火祠烟荡精切，长天白雨怙痴顽。","天涯交臂早无绍，去景凝眸暂不閒。","难与此怀觅止竟，征鸿一缕空飞还。"]},{"t":"洞庭秋三十首 其十六","f":"七言律诗","c":["塞臆英多杜口宣，清歌难唤奈何天。","古人不见閒邀月，置我无从小学仙。","铁脊未妨聊旖旎，金轮犹恐不刚坚。","馀霞落日关何事，带影微茫起识田。"]},{"t":"洞庭秋三十首 其十七","f":"七言律诗","c":["法界孤微此泬寥，鲲游亦竦等鹪鹩。","环区不鲠鱼头乙，泓水方凝雀目椒。","浓露可怜添浥润，片云何恃得逍遥。","穷涂收拾千年恨，虾国游谁出斗跳。"]},{"t":"洞庭秋三十首 其十八","f":"七言律诗","c":["欱然敛精归元包，匀凝活汞停煎炮。","穹窿舍此复何有，沆瀣相干故不交。","稍觉丝缗牵静谧，非分玉笛喧淫咬。","神光四映飞芒角，讵倚星月相杂殽。"]},{"t":"洞庭秋三十首 其十九","f":"七言律诗","c":["弱骨凌乘一线操，未凭长目送雄豪。","通身冰血争融结，伸臂烟霄试抑搔。","岂必人生方幻寄，足知厚载不功高。","金风但鼓囊中籥，大费尖酸徒尔劳。"]},{"t":"洞庭秋三十首 其二十","f":"七言律诗","c":["晶辉蠕影萦一窝，澄之荡之夫如何。","容裔积已成坚冽，鏦铮喧外绝烦苛。","绿非荇藻发谁浦，光带露霜自昨波。","惊鸿亦知无闻见，抱意长鸣凌嵯峨。"]},{"t":"洞庭秋三十首 其二十一","f":"七言律诗","c":["大圆不息翻河车，闪烁万顷吹银芽。","化汁一色混潇皛，青气双合通荒遐。","无质可抟犹沐浴，有见不盈奚开遮。","何得丧耦此孤坐，谁邀明月觅芦花。"]},{"t":"洞庭秋三十首 其二十二","f":"七言律诗","c":["三秋三楚填淫荒，谁能不断忧思肠。","遥遥极浦浮云树，渺渺生洲迷荻蒋。","马殷南国飞星白，陆逊西垒落日凉。","咫尺千波杳向往，孰为大壑恣埋藏。"]},{"t":"洞庭秋三十首 其二十三","f":"七言律诗","c":["浮槎无系巴邱城，缥渺之楼空若惊。","微霜覆蓑失残梦，远火照帆悲他情。","乘乘宇内既清澈，脉脉空际或经营。","小范于此言忧乐，胸中无故横甲兵。"]},{"t":"洞庭秋三十首 其二十四","f":"七言律诗","c":["微风软縠退以听，濯濯平远拔昭灵。","吝俭物情不获巳，险阻大造故须经。","馀霞半壁从明灭，征雁万双亦伶俜。","居然幻泡警凉魄，无数浮心一日扃。"]},{"t":"洞庭秋三十首 其二十五","f":"七言律诗","c":["崚嶒何来凛气增，舍此空轮无与胜。","吴天海色遥迎送，楚霜蜀冻交消凝。","荡涤赤日曳素练，消息银汉络珠绳。","从知白帝威权甚，万象泻影涵倾崩。"]},{"t":"洞庭秋三十首 其二十六","f":"七言律诗","c":["鹧鸪声断西日浮，君山未愁黄陵愁。","白浪几何倾楚塞，金风既展讫神州。","萧飒万个撼斑管，迢递千古疑胶舟。","贾至张说尔何物，落拓欲牵万里忧。"]},{"t":"洞庭秋三十首 其二十七","f":"七言律诗","c":["但哀无端眇淫淫，长啸不展狂歌瘖。","欲与招魂迷南北，横令此愁亘古今。","蛰雷残雨无所藉，金枢玉露亦难谌。","日暮息棹殊未已，寒波倒射冉枫林。"]},{"t":"洞庭秋三十首 其二十八","f":"七言律诗","c":["玻瓈帝网两镜参，元中之元清灵酣。","露泡影相合不二，水月空观谁为三。","中流两岸四无定，鸟道一碧微自谙。","军持满汲寒沁骨，容受无多祇大惭。"]},{"t":"洞庭秋三十首 其二十九","f":"七言律诗","c":["青幕白地清涎黏，浓淡分界唯微纤。","未审天容亏半壁，定疑水气消馀炎。","披襟不让云将御，理楫略挂羚羊尖。","鏖空白战九十日，吸月餐风亦损廉。"]},{"t":"洞庭秋三十首 其三十","f":"七言律诗","c":["玉液统此微霄函，俯仰不知灵与凡。","旭雾平收兜罗捲，阴彩夕涌牟尼嵌。","肉翅欲愁千里倦，韵目难厌一晌馋。","苍螺半点点霜色，谪仙何情强欲芟。"]},{"t":"前雁字诗十九首 其一","f":"五言律诗","c":["缕缕渐深深，当天一片心。","书云占朔色，縆瑟谱商音。","尺帛无劳系，南楼未易寻。","暝烟生极浦，长夜付浮沈。"]},{"t":"前雁字诗十九首 其二","f":"五言律诗","c":["碧浪合逡巡，萧条接迹亲。","三苍言外旨，七日句中春。","避暑疑秦火，怀沙吊楚臣。","云林添画笔，中土不无人。"]},{"t":"前雁字诗十九首 其三","f":"五言律诗","c":["活谱赋秋声，音容共一清。","空顽难转语，天老未忘情。","羽调悲寒水，行吟倦汨征。","芦干悽怨急，绝笔意谁平。"]},{"t":"前雁字诗十九首 其四","f":"五言律诗","c":["鹊渡已如梦，深秋始报章。","偷临无乳燕，低诵有寒螀。","落叶勤雠误，墟烟与秘藏。","重来无粉本，随意写苍苍。"]},{"t":"前雁字诗十九首 其五","f":"五言律诗","c":["纪艳非吾义，惊春去色匆。","分飞南北史，历乱桧曹风。","天问凭条答，空言未道穷。","何须藏鲁壁，丝竹奏清融。"]},{"t":"前雁字诗十九首 其六","f":"五言律诗","c":["无待月中听，哀吟意已形。","同文从鸟纪，驰檄指龙庭。","旁午悲边雪，零丁寄汗青。","清泉涵片影，井底血函经。"]},{"t":"前雁字诗十九首 其七","f":"五言律诗","c":["冉冉漾轻柔，关河只此愁。","鹰鹯疑谤诅，鸠鸴漫咨诹。","水月三人影，霜霄一抹秋。","江山日日改，挟策亦奚游。"]},{"t":"前雁字诗十九首 其八","f":"五言律诗","c":["今古一相如，飘飖赋子虚。","元文披带草，碧个仿林于。","兰叶肥还瘦，银钩蹙已舒。","稻粱非汝志，投笔莫欷歔。"]},{"t":"前雁字诗十九首 其九","f":"五言律诗","c":["乘风莫草草，雨雪且舒邪。","燕国迷苍素，鹃言染茹藘。","六歌怀天水，尺一谢休屠。","一线台城诏，难忘纸鹞书。"]},{"t":"前雁字诗十九首 其十","f":"五言律诗","c":["此字无人识，空劳历九州。","分明扶日月，因革自春秋。","鸩篆删妖步，莺歌耻佞喉。","冥飞谁弋篡，不坠草元楼。"]},{"t":"前雁字诗十九首 其十一","f":"楚辞体","c":["野水漾初春，苔涵绿字新。","烟云都不染，风雨故如神。","软影翰非弱，馀寒手不龟。","凤兮衰已久，还现素臣身。"]},{"t":"前雁字诗十九首 其十二","f":"五言律诗","c":["终知无寄处，不欲昧前期。","人世谁长目，天心自列眉。","寒宵闻见外，皑雪炫荧时。","岂为知音绝，停毫罢远思。"]},{"t":"前雁字诗十九首 其十三","f":"五言律诗","c":["脉脉有心期，行行且浪嬉。","大人狂客传，小雅遗民诗。","解就名鸿烈，书成授意而。","关门邀紫气，聊与著雄雌。"]},{"t":"前雁字诗十九首 其十四","f":"五言律诗","c":["晴空不易得，欲示下方难。","黑月韦编绝，酸风蠹迹残。","黄麻悲鹭序，白简笑鹰弹。","独吹青燐火，传书乙夜寒。"]},{"t":"前雁字诗十九首 其十五","f":"五言律诗","c":["倚杖孰亭皋，寻行送望劳。","霞章添旖旎，星采点萧骚。","唯觉孤心合，难将远目韬。","昏鸦空泼墨，何当一鸿毛。"]},{"t":"前雁字诗十九首 其十六","f":"五言律诗","c":["居然缘慧业，亦自种情苗。","始旦回鸾帖，清秋题鹊桥。","弥天知泛宅，露地注逍遥。","既證无师智，灵云瞥眼消。"]},{"t":"前雁字诗十九首 其十七","f":"五言律诗","c":["痴蝇钻故纸，窗隙溷云容。","天外劳一笑，书中谁万钟。","童乌何足与，燕颔止为佣。","小过占哀俭，飞离不恤凶。"]},{"t":"前雁字诗十九首 其十八","f":"五言律诗","c":["一从悲凤靡，长是问苍旻。","南北招重叠，风霜挟苦辛。","昔时人不见，归去柰何春。","童子三生塔，还留慧命因。"]},{"t":"前雁字诗十九首 其十九","f":"五言律诗","c":["青女授灵符，全身入画图。","血潮勒款识，毛鸷化酸迂。","天变人终定，云生道不孤。","无心持换米，生计有雕胡。"]},{"t":"后雁字十九首 其一","f":"五言律诗","c":["之绕打虚空，经营惨淡中。","虫鱼多诘屈，龙马半昭聋。","副墨传溪影，雌黄听落虹。","天情骀宕里，消息一丝通。"]},{"t":"后雁字十九首 其二","f":"五言律诗","c":["寓言河汉迥，草线与灰蛇。","应迹说随扫，文身开复遮。","梵书疑以八，易象半交叉。","飞舞茅龙趣，江门忆白沙。"]},{"t":"后雁字十九首 其三","f":"五言律诗","c":["抗坠引清微，灵心挟肉飞。","蜗银真白俗，鲗墨莽钟肥。","主乙疑无定，偏傍竟不违。","方春湘水上，拓得禹碑归。"]},{"t":"后雁字十九首 其四","f":"五言律诗","c":["尘气不馀纤，凭虚一缕黏。","分歧垂远势，透露簇微尖。","曳脚神还整，藏锋力自铦。","臣书真逸品，凤藻得无嫌。"]},{"t":"后雁字十九首 其五","f":"五言律诗","c":["闪霍仿公孙，垂垂引漏痕。","装潢悬玉宇，授受付金昆。","带雨流鹑火，衔芦赋大言。","灵文人未测，只倩记寒温。"]},{"t":"后雁字十九首 其六","f":"五言律诗","c":["密迹簇春蚕，青编削蔚蓝。","阙文唯夏五，足用及冬三。","元鸟谁徵宋，金天旧问郯。","笔花欲有授，鸟梦柰沈酣。"]},{"t":"后雁字十九首 其七","f":"五言律诗","c":["湘岸临潭帖，天山拓汉铭。","为谁修楚史，自解注禽经。","语雀羞刑牍，言鹦笑说铃。","挥毫千里泻，腕脱不曾停。"]},{"t":"后雁字十九首 其八","f":"五言律诗","c":["耻化顽仙羽，新宫待尔题。","河山双划断，物论片言齐。","脉望徒吞字，蟾蜍未映迷。","寒陵劳坐卧，极目去踪低。"]},{"t":"后雁字十九首 其九","f":"五言律诗","c":["霁雪曙南天，孤萦倍可怜。","蛾眉流晓镜，香尾篆垆烟。","幽意蝇头密，连丝茧绪牵。","灵纹惊易没，移入断云边。"]},{"t":"后雁字十九首 其十","f":"五言律诗","c":["秋思本无多，千行自不讹。","清姿从倒薤，壮志欲眠戈。","散队连行草，遥天任擘窠。","催花看尽发，谁与换群鹅。"]},{"t":"后雁字十九首 其十一","f":"五言律诗","c":["涤砚袅元云，潇湘写练裙。","龙蛇双腕竞，鱼燕尾梢分。","出像传毛颖，题帧仿墨君。","夫人学已熟，谁复笑羊欣。"]},{"t":"后雁字十九首 其十二","f":"五言律诗","c":["素宇无留墨，平沙印别痕。","暗书还自省，未到意先吞。","映雪功弥苦，依天道已尊。","八纮开义海，潇洒动乾坤。"]},{"t":"后雁字十九首 其十三","f":"五言律诗","c":["浑敦帝鸿开，谁云子不才。","国门悬月令，南极转三能。","下士称微者，雄风咏快哉。","匆匆春早驾，荐福畏惊雷。"]},{"t":"后雁字十九首 其十四","f":"五言律诗","c":["沙雪笺银暗，芦锋笔阵降。","惊飙催就急，虚白人钩双。","发细萦空镜，晴波上晓窗。","研朱和露滴，枫冷落吴江。"]},{"t":"后雁字十九首 其十五","f":"五言律诗","c":["有句兼无句，羚羊偶挂尖。","吹毛传密谛，带影悟廉纤。","化迹空三藏，迷人顶一砭。","献花岩畔鸟，半偈不曾拈。"]},{"t":"后雁字十九首 其十六","f":"五言律诗","c":["刮目经年别，惊非吴下蒙。","四声终写入，六义不删风。","耻逐蝌文乱，谁凭雉译通。","斯文知未丧，几复畏虚弓。"]},{"t":"后雁字十九首 其十七","f":"五言律诗","c":["淡墨布层层，痴肥自不胜。","回文低落月，影本暗渔镫。","险句从空搆，秋思与上兴。","悬题天阙迥，为尔费冰兢。"]},{"t":"后雁字十九首 其十八","f":"五言律诗","c":["始知空阔里，无数妙诠偕。","娓娓谈天衍，痕痕炼石娲。","纸光从月砑，笔冢有云埋。","仙笈传青鸟，空劳曼倩谐。"]},{"t":"后雁字十九首 其十九","f":"五言律诗","c":["未肯负居诸，飘流不废书。","长涂收史料，小正作经疏。","赝迹徒相似，鸿儒亦借誉。","鲲鹏聊志怪，终是不才樗。"]},{"t":"题芦雁绝句十八首 其一","f":"七言绝句","c":["惊风吹霰雪中还，万里黄云一线关。","回首江南此风景，唯将呜咽写潺湲。"]},{"t":"题芦雁绝句十八首 其二","f":"七言绝句","c":["汀渚谁家尽自疑，悬愁渔火隔江知。","飘零亦是前生果，不羡鹪鹩老一枝。"]},{"t":"题芦雁绝句十八首 其三","f":"七言绝句","c":["月明是水是芦花，逗漏清空片影斜。","沙上有踪谁见得，侬家曾泛逆流槎。"]},{"t":"题芦雁绝句十八首 其四","f":"七言绝句","c":["健翮先飞下浅汀，鱼虾虽饱却馀腥。","何如且带斜阳影，点缀残山一段青。"]},{"t":"题芦雁绝句十八首 其五","f":"七言绝句","c":["秋江淼淼月微明，飞雪纵横点翅轻。","自学春莺穿柳絮，不知白羽赚苏卿。"]},{"t":"题芦雁绝句十八首 其六","f":"七言绝句","c":["簇簇霜花覆浅滩，荻根蒋叶一江寒。","秋声彻夜惊鸥鹭，筝柱参差不忍弹。"]},{"t":"题芦雁绝句十八首 其七","f":"七言绝句","c":["蜀雪消迟水拍空，前时汀渚杳蘋风。","今宵随分聊收翼，只在秋声一派中。"]},{"t":"题芦雁绝句十八首 其八","f":"七言绝句","c":["老碧蒙茸嫩叶齐，一钩斜月照幽栖。","清宵寒梦虽无据，不到飞狐谷口西。"]},{"t":"题芦雁绝句十八首 其九","f":"七言绝句","c":["南来不为稻粱谋，彻骨森寒月下洲。","藻苦荇甜随口过，饥鸢莫漫为含愁。"]},{"t":"题芦雁绝句十八首 其十","f":"七言绝句","c":["书人欲倦曳波长，一幅皑皑侧理光。","尽捲丹坟归竹素，不留之绕待雌黄。"]},{"t":"题芦雁绝句十八首 其十一","f":"七言绝句","c":["浅白平铺万绿稠，苍翎碧水素沙洲。","色如非色云何摄，一味分明墨气收。"]},{"t":"题芦雁绝句十八首 其十二","f":"七言绝句","c":["渔艇无踪樵径荒，平沙露冷月微茫。","问师此景从谁得，莫是前身现雁王。"]},{"t":"题芦雁绝句十八首 其十三","f":"古风","c":["惊心矰?晓饥馀，何有壸浆一艇渔。","莫道相酬无宝剑，明年先寄报恩书。"]},{"t":"题芦雁绝句十八首 其十四","f":"七言绝句","c":["密叶修茎翠万竿，未须还怨晓霜寒。","天涯拚作无归客，且得清秋一夕安。"]},{"t":"题芦雁绝句十八首 其十五","f":"七言绝句","c":["回望还惊伴侣迟，分飞愁绝故心移。","江皋莫爱霜枫紫，自是栖乌夜宿枝。"]},{"t":"题芦雁绝句十八首 其十六","f":"七言绝句","c":["秋心万古此潇湘，汉苑胡关带恨长。","谁道灵均哀思绝，唯将鶗鴂怨年芳。"]},{"t":"题芦雁绝句十八首 其十七","f":"七言绝句","c":["斜晖欲下飐金飙，绿苞初开碎练飘。","莫认天山飞雪早，江南饶有可怜宵。"]},{"t":"题芦雁绝句十八首 其十八","f":"七言绝句","c":["墨光之外喷秋光，夜永江寒楚塞长。","记得苍梧多泪竹，缄愁无柰断衡阳。"]},{"t":"仿昭代诸家体三十八首 一 刘护军基 秋兴","f":"七言律诗","c":["括苍云绕缙云都，万簇芙蓉翠色铺。","红雨湿飞乌桕薄，碧波晴点鹭痕孤。","登楼有赋依州牧，长揖无门傲酒徒。","不识故园他日泪，蘋花还送暗香无。"]},{"t":"仿昭代诸家体三十八首 二 杨提举维桢 嬉春","f":"七言律诗","c":["选胜明朝陌上花，狂夫已宿黄公家。","连钱夜洗香泥点，团扇新描软縠纱。","燕尾掠人沾绿酒，莺歌随处咒兰芽。","片云南浦不成雨，油幕高搴看晚霞。"]},{"t":"仿昭代诸家体三十八首 三 倪处士瓒 园居","f":"七言律诗","c":["长夏新桐洗绿茎，乳莺历乱啄朱樱。","不知微雨遮青嶂，即次流珠溅紫萍。","閒整丹经香篆歇，小临鹤径碧苔生。","棋枰已敛湘帘捲，稍觉银钩挂岭横。"]},{"t":"仿昭代诸家体三十八首 四 贝助教琼 感乱","f":"七言律诗","c":["正作越来溪上梦，潮声夜打浙东城。","春花春柳皆他日，羽檄羽书悲此生。","戍火摇烟低片月，归鸿掠浦警三更。","堂堂岁月相欺得，明镜新添雪几茎。"]},{"t":"仿昭代诸家体三十八首 五 袁御史凯 白燕","f":"七言律诗","c":["乌衣莫与怨斜阳，雪色新裁素练裳。","隋苑柳疏长带月，河阳花满不惊霜。","琼窗瞥眼窥银字，玉镜偷临斗靓妆。","似妒蘋花秋色好，不留清影照寒塘。"]},{"t":"仿昭代诸家体三十八首 六 高太史启 梅花","f":"七言律诗","c":["稍觉逢春客思催，江春无奈促花开。","一枝横水寒潭月，几点回风雪砌苔。","啼鸟易惊归客梦，陇云空寄故园哀。","东风已遣芳心尽，谁与垂杨衒楚台。"]},{"t":"仿昭代诸家体三十八首 七 刘典签炳 早朝","f":"七言律诗","c":["暄风绿草凤台新，金爵浮光射宝轮。","云敛三山澄海气，日华双阙起江春。","衣裳初识龙文阔，导唱遥欣黼座亲。","还使故园归兴尽，鸣珂长日惜芳尘。"]},{"t":"仿昭代诸家体三十八首 八 孙典籍蕡 客思","f":"七言律诗","c":["扁舟下峤识春寒，五两随风度几滩。","古渡铙吹侵月奏，孤城楼堞带云看。","故园荔酒经春熟，过岭梅花度雪残。","一曲沧浪牵客泪，羊城珠斗冷仙坛。"]},{"t":"仿昭代诸家体三十八首 九 高礼曹柄 酬答","f":"七言律诗","c":["弹铗新从上国行，遥瞻山斗识才名。","汉廷属望贤良策，鲁殿初传丝竹声。","柳色上衣春日酒，梅花吹笛岁寒情。","殷勤莫负乘槎约，拂剑欣看碧汉清。"]},{"t":"仿昭代诸家体三十八首 十 李少师东阳 感春","f":"七言律诗","c":["小园花发镇帘垂，春草临阶未觉滋。","香尾困风穿湿幕，墨胶凝水带冰澌。","病中药裹烦南客，梦里兰芳记楚辞。","犹有湘干田二顷，君恩不许趁耕时。"]},{"t":"仿昭代诸家体三十八首 十一 陈简讨献章 晚酌","f":"七言律诗","c":["日㬉风微柳匝溪，分明莎径未须迷。","莺声过涧还如近，蝶翅因花亦屡低。","心迹同原聊共赏，乾坤双歇恰单提。","芒鞋是处寻春好，不拣苍苔与沁泥。"]},{"t":"仿昭代诸家体三十八首 十二 祝京兆允明 悲秋","f":"七言律诗","c":["独坐不知秋日短，行年唯有鬓霜新。","病过柳市愁京兆，梦记番禺狎海人。","泡影勋名消易得，牢骚日月阅来亲。","乌藤拄杖明朝事，怕见丹枫映水滨。"]},{"t":"仿昭代诸家体三十八首 十三 唐解元寅 落花","f":"七言律诗","c":["啼莺流水怨匆匆，万顷春华一梦中。","芳韵悠悠随画角，閒愁点点到帘栊。","回风无望依瑶草，韶月难期映晚红。","回首繁华能几日，碧条簇簇惹薰风。"]},{"t":"仿昭代诸家体三十八首 十四 李副使梦阳 怀古","f":"七言律诗","c":["百尺丽谯俯暮原，黄河捲雪拥蛟门。","朱仙祠庙青松冷，艮岳风霾白日昏。","华表定留千载恨，灵旗难返九招魂。","寒鸦斜照苍茫外，酹酒长怀国士恩。"]},{"t":"仿昭代诸家体三十八首 十五 何副使景明 游历","f":"七言律诗","c":["轺车明发启秦关，缥渺河山紫气殷。","清渭波萦劳怅望，莲峰云杳阻跻攀。","鸿门霸气苍烟合，汉寝遗封翠柏閒。","万里萧条随薄宦，不知明镜改朱颜。"]},{"t":"仿昭代诸家体三十八首 十六 文待诏徵明 斋宿","f":"七言律诗","c":["星华浅映御池冰，栖鹊寒喧树影层。","独对画垣围藻井，遥知香雾达觚棱。","钟人屡扣流霜杵，羽骑长依带月灯。","应有五云迎凤葆，晓风已觉透青绫。"]},{"t":"仿昭代诸家体三十八首 十七 郑稽勋善夫 送客","f":"七言律诗","c":["相送今朝倒客杯，风高木落试登台。","乾坤带甲无终日，草泽纡筹几骏才。","南去祇悲湘水雁，北书唯寄陇头梅。","栖迟迢递双极目，大旆孤城画角哀。"]},{"t":"仿昭代诸家体三十八首 十八 杨殿撰慎 塞垣","f":"七言律诗","c":["碎叶孤城朔雁飞，安西都擭候骑归。","汉旌已觉交龙捲，虏酒初骄撞马肥。","桃叶杨花江上梦，敲冰燧火北庭围。","伏波未洗明珠恨，莫诧中朝有建威。"]},{"t":"仿昭代诸家体三十八首 十九 李廉访攀龙 登眺","f":"七言律诗","c":["绝巘岧峣接太清，登临极目羽翰轻。","青徐海色侵牛斗，河朔云山拥凤城。","汉树龙鳞秋色爽，秦碑屃赑暮烟横。","探崖欲问长生诀，咫尺蓬壶万里情。"]},{"t":"仿昭代诸家体三十八首 二十 王司寇世贞 投赠","f":"七言律诗","c":["白雪仙郎雅奏偏，秋曹云冷綵毫传。","迢遥星棹依元礼，萧瑟高楼忆仲宣。","采药三山迷蜃气，长歌万里看龙渊。","东方千骑空筹策，愧尔酬恩紫禁边。"]},{"t":"仿昭代诸家体三十八首 二十一 高廉访叔嗣 宦况","f":"七言律诗","c":["三晋云山西爽开，犹凭呼吸近燕台。","时依朱邸陪仙仗，喜际青阳进寿杯。","铃阁雪消春草长，牙旌风急暮笳哀。","葵心欲逐桑乾水，萦绕金河辇道苔。"]},{"t":"仿昭代诸家体三十八首 二十二 梁秋官有誉 吊古","f":"七言律诗","c":["陆沈不拟尽天涯，回忆西湖怨梦华。","万古神州消白浪，中流尺土捲黄沙。","云蒸海气栖樯燕，树隐龙宫急暮鸦。","遥想讲筵当日语，唯留碧血洒鱼虾。"]},{"t":"仿昭代诸家体三十八首 二十三 屠大仪隆 送别","f":"七言律诗","c":["高楼清瑟送离群，欲逐杨花怨夕曛。","绣袷春寒三月雨，牙樯风急一江云。","狂歌戏马台前客，回首钟山移后文。","浩荡长淮分咫尺，扬州红药属夫君。"]},{"t":"仿昭代诸家体三十八首 二十四 朱九江曰藩 闺怨","f":"七言律诗","c":["章台垂柳叶凋秋，孤怨孤栖荡妇楼。","六朝香粉丁都护，万里戎韬霍小侯。","明月机中双纽缕，黄云城上千金钩。","此生不拟长相忆，犹梦落花逐上流。"]},{"t":"仿昭代诸家体三十八首 二十五 王上舍稚登 月游","f":"七言律诗","c":["秋满吴淞江外江，棠桡波敛夜推窗。","月华始出照五两，白鸟飞来恰一双。","客散歌声犹有恨，霜寒酒力未全降。","西归更送山阳笛，写入落梅别调腔。"]},{"t":"仿昭代诸家体三十八首 二十六 于阁学慎行 纪赐","f":"七言律诗","c":["龙胎密孕御园春，蔬署寻芳剥锦鳞。","天诏正如裁玉版，臣心未敢拟霜筠。","中宵酒醒香生颊，缓火羹清玉点唇。","肉食承恩沾凤实，秋风忍忆故乡莼。"]},{"t":"仿昭代诸家体三十八首 二十七 徐秀才渭 怀古","f":"七言律诗","c":["湖光千顷敞祠宫，雪捲长堤缀蓼红。","血迹梦残凋燕垒，灵旗云闪起蛟风。","局争成败天难主，情到华夷感亦同。","古鼎香烟飘碧篆，丝丝飞绕六陵东。"]},{"t":"仿昭代诸家体三十八首 二十八 汤遂昌显祖 寄怀","f":"七言律诗","c":["星汉当檐挂素秋，元禽欲去复缄愁。","江花笑拂荷衫袖，縠水回迎竹叶舟。","行药定逢菖九节，忆梅遥爱月三洲。","垂杨色色萦歌扇，未遣新筝怨雁楼。"]},{"t":"仿昭代诸家体三十八首 二十九 袁吏部宏道 放言","f":"七言律诗","c":["乾坤非短梦非长，花落聊纾粉蝶忙。","莫遣酒星囚北海，偶逢伏日饱东方。","蝇窗乍裂双眸阔，狐帽随拈彻骨香。","唯有昭文琴外谱，不从夔旷问宫商。"]},{"t":"仿昭代诸家体三十八首 三十 王太史衡 春赏","f":"七言律诗","c":["几日新阴软碧莎，羽笙日日入莺歌。","花如静女添春绣，月许游人画浅蛾。","病减恰逢垂柳瘦，诗成长在野亭多。","银笺欲寄催花句，却为情深未订讹。"]},{"t":"仿昭代诸家体三十八首 三十一 陈徵君继儒 閒居","f":"七言律诗","c":["衡门过雪草心蠲，玉茗胎红透始暄。","乍响青松烹紫笋，閒移斑几就黄绵。","茅山书至兼酬药，上海鹤归未买田。","熟煮清酤添箬裹，为移春闰入新年。"]},{"t":"仿昭代诸家体三十八首 三十二 钟少参惺 淮泛","f":"七言律诗","c":["书史笙歌尽未殊，林光江气各清迂。","深知帝里春偏静，小爱閒官韵不拘。","水有性情鸥鹭得，月函虚皛藻蘋孤。","回舟群动皆空谧，隔岸笼灯半有无。"]},{"t":"仿昭代诸家体三十八首 三十三 谭解元元春 岳游","f":"七言律诗","c":["不知猿鸟至何方，叶叶晴容发静光。","潭黑龙能深定力，苔新云亦恋幽香。","泉于草树情偏挚，日以森寒影倍长。","始觉向来湘艇上，孤危错拟露锋铓。"]},{"t":"仿昭代诸家体三十八首 三十四 王佥事思任 登岱","f":"七言律诗","c":["何须大叫帝阍闻，肸蚃通天黍米分。","吴练凄迷亏老寿，汉封细碎到亭云。","欲收元气无坚影，自笑顽躯亦片云。","帝鬼痴灵皆一蚁，强将斋沐溷元君。"]},{"t":"仿昭代诸家体三十八首 三十五 曹兰台学佺 感时","f":"七言律诗","c":["杉关关外几分春，已报江干惹战尘。","临水自浇三日洒，看花无那百年人。","仙函难访龙韬秘，瑶草谁于御辇亲。","暂与风光相蕴藉，巡池杞柳亦芳辰。"]},{"t":"仿昭代诸家体三十八首 三十六 倪司徒元璐 抒愤","f":"七言律诗","c":["狂歌不审定因何，夹臆红潮湃万波。","怖鬼已勤悬紫蟹，冲天无望锢苍鹅。","妒津日日添风雨，疑网重重长薜萝。","为爱信陵多纵酒，糟邱无奈酝情魔。"]},{"t":"仿昭代诸家体三十八首 三十七 陈黄门子龙 赠戍","f":"七言律诗","c":["江潭瑶草不须生，自折疏麻送远行。","九庙威灵元白日，四愁风雨有孤荣。","青编白简星光迥，大纛高牙落照倾。","极目苍生悲海色，唯馀三学傲公卿。"]},{"t":"仿昭代诸家体三十八首 三十八 顾秀才开雍 恸哭","f":"七言律诗","c":["馋蛟风激怒涛腥，逝水东倾夜不扃。","无望金山邀北岸，恰逢潮水落皋亭。","乌衣夜色空迷燕，碧血中宵欲化萤。","回首五云蟠御寝，断肠鹃哭向冬青。"]},{"t":"霜度函口","f":"五言律诗","c":["坠叶满行衣，径草试霜色。","何知山川想，足敌绝尘力。","初暾峰紫摇，浮空夹苍植。","似可就奇光，问之求羽翼。"]},{"t":"即事 其二","f":"七言绝句","c":["看山正好北风吹，寒在峰头最上枝。","莫漫放松筇竹杖，诘朝晴好野翁知。"]},{"t":"寒甚下山访病儿存没道中逢夏仲力下小竹舁慄不能语哀我无衣授之以絮归山有咏志感也 其一","f":"五言律诗","c":["应自友朋恩，知深谢不言。","无衣度霜雪，多难际乾坤。","泥重芒鞋涩，云浓湿帽昏。","更愁从此去，托足向何门。"]},{"t":"寒甚下山访病儿存没道中逢夏仲力下小竹舁慄不能语哀我无衣授之以絮归山有咏志感也 其二","f":"五言律诗","c":["得絮不云暖，此情君合知。","主忧臣但尔，心死身何为。","绿草华山带，高楼燕子枝。","讵言身未嫁，可任东风吹。"]}]};